/* ---------------- Sliding segmented control ---------------- */
/* A section tab is a smaller version of the same move.

   Jorge: "if elements are selected that aren't in the top navigation bar, they
   should have their own small side to side transitions, because every page when
   it loads has the elements pop from the bottom up."

   Exactly the fault: the tabs within a tool were reusing the page's mount
   animation, so moving one step sideways along a strip made the whole page jump
   up from the bottom. It travels the way the strip does now — shorter and
   quicker than a tool switch, because it is a smaller move and should not cost
   the same. */
/* Two beats, the same shape as a tool switch and shorter. The first version had
   one: the new tab's blocks slid in from the side while the old ones were simply
   gone, because the content was swapped in the same click that started the
   animation. Half a move reads as a flicker, however well the arriving half is
   drawn — what the eye wants is the thing it was looking at LEAVING. So the
   swap now waits for the exit, and `apply` is what does it. */
/* The last block starts 48ms in and its exit runs 140, so the swap cannot happen
   before 188 without cutting it off mid-flight — and a block that vanishes halfway
   through leaving is exactly what reads as a flicker. Same arithmetic as
   TOOL_EXIT. */
const TAB_EXIT = 190;
const TAB_ENTER = 400;
let tabTimers = [];
function clearTabMove() {
  tabTimers.forEach(clearTimeout);
  tabTimers = [];
  if (typeof document === "undefined") return;
  settleReveals();
  document.documentElement.classList.remove("tab-move", "tab-exit", "tab-enter", "tab-dir-r", "tab-dir-l");
}
function tabMove(dir, apply) {
  const run = typeof apply === "function" ? apply : () => {};
  if (typeof document === "undefined") { run(); return; }
  try {
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) { run(); return; }
  } catch (e) {}
  const root = document.documentElement;
  clearTabMove();
  /* Read once, so the class lands in its own frame rather than being added and
     removed inside one and never painting. */
  void root.offsetWidth;
  root.classList.add("tab-move", "tab-dir-" + dir, "tab-exit");
  tabTimers.push(setTimeout(() => {
    run();
    root.classList.remove("tab-exit");
    root.classList.add("tab-enter");
    tabTimers.push(setTimeout(clearTabMove, TAB_ENTER + 120));
  }, TAB_EXIT));
}

function SegControl({ items, value, onChange, renderExtra, attentionId }) {
  /* The strip answers the finger straight away even though the page underneath
     waits 130ms for its exit: the thumb and the active label follow `shown`,
     which is the tab that was pressed, not the tab that has arrived. Without it
     the control would look 130ms slower than it is. */
  const [pending, setPending] = useState(null);
  useEffect(() => { setPending(null); }, [value]);
  /* And released even if it never arrives. A parent is free to ignore an onChange
     it does not like, and without this the strip would sit lit on a tab the page
     never went to. */
  useEffect(() => {
    if (pending === null) return undefined;
    const t = setTimeout(() => setPending(null), TAB_EXIT + 400);
    return () => clearTimeout(t);
  }, [pending]);
  const shown = pending !== null && items.some((it) => it[0] === pending) ? pending : value;
  const wrapRef = useRef(null);
  const btnRefs = useRef({});
  const [thumb, setThumb] = useState({ left: 0, width: 0, ready: false });

  const measure = useCallback(() => {
    const btn = btnRefs.current[shown];
    const wrap = wrapRef.current;
    if (!btn || !wrap) return;
    setThumb({ left: btn.offsetLeft, width: btn.offsetWidth, ready: true });
  }, [shown]);

  useEffect(() => {
    measure();
    /* Centre the active segment by scrolling this control and nothing else.
       scrollIntoView was doing it before, and block:"nearest" is not the
       safeguard it looks like: "nearest" still scrolls every ancestor that can
       scroll, the document included, whenever the control is off screen. On a
       phone a strip sitting below the fold pulled the whole page down to itself
       on mount, so every page carrying one opened slightly scrolled. Setting
       scrollLeft touches the horizontal axis of this element only, which is all
       that was ever wanted. */
    const btn = btnRefs.current[shown];
    const wrap = wrapRef.current;
    if (btn && wrap && wrap.scrollWidth > wrap.clientWidth + 1) {
      const want = btn.offsetLeft - (wrap.clientWidth - btn.offsetWidth) / 2;
      const max = wrap.scrollWidth - wrap.clientWidth;
      wrap.scrollLeft = Math.max(0, Math.min(max, want));
    }
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [shown, measure]);

  // re-measure once fonts settle
  useEffect(() => { const t = setTimeout(measure, 150); return () => clearTimeout(t); }, [measure]);

  return (
    <div className="seg" ref={wrapRef}>
      <div className={"seg-thumb" + (thumb.ready ? " ready" : "")} style={{ transform: `translateX(${thumb.left}px)`, width: thumb.width }} />
      {items.map(([id, label]) => (
        <button key={id} ref={(el) => (btnRefs.current[id] = el)}
          className={"seg-btn" + (shown === id ? " active" : "") + (attentionId === id && shown !== id ? " seg-wave" : "")}
          onClick={() => {
            /* Which way along the strip, from the strip itself rather than from
               a list somebody has to keep in step with it. */
            const from = items.findIndex((it) => it[0] === shown);
            const to = items.findIndex((it) => it[0] === id);
            if (to === from) { onChange(id); return; }
            setPending(id);
            tabMove(to > from ? "r" : "l", () => onChange(id));
          }}>
          {label}
          {renderExtra && renderExtra(id)}
        </button>
      ))}
    </div>
  );
}

/* ---------------- Standalone TV leaderboard (HTML string) ---------------- */
function LEADERBOARD_HTML(p) {
  return `<!doctype html><html><head><meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>${p.storeName} · Leaderboard</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&display=swap');
  @import url('https://fonts.googleapis.com/css2?family=Geist:wght@300;400;500;600;700&family=Sora:wght@300;400;500;600;700&family=Geist+Mono:wght@400;500&family=JetBrains+Mono:wght@400;500&display=swap');
  * { margin:0; padding:0; box-sizing:border-box; }
  :root { --blue:#2A5E9B; --dblue:#1D4674; --lime:#C1D730; --lblue:#88C6EA;
    --green:#2E9E4F; --greenbg:#E4F4E7; --yellow:#E0A100; --yellowbg:#FCF2D3; --red:#D5433A; --redbg:#FBE3E1; }
  /* Same guard as the app: plenty of these screens are driven by an Android stick
     or an Android TV, and every size on this board is computed from the height of
     the screen. Chrome deciding a column should be bigger than the arithmetic said
     is the one thing that can throw the whole layout out. */
  html,body { height:100%; -webkit-text-size-adjust:100%; text-size-adjust:100%; }
  body { font-family:'Space Grotesk',system-ui,-apple-system,'Segoe UI',sans-serif; color:#EAF1F8;
    font-variant-numeric:tabular-nums; font-feature-settings:'tnum' 1;
    background:#0E2033; overflow:hidden; }
  /* Store colors mode: the whole backdrop derives from the store's brand palette,
     darkened for contrast so the rows and pills still read from across a floor. */
  body.bg-store { background: color-mix(in srgb, var(--bd, #1D4674), black 62%); }
  body.bg-store::before {
    background:
      radial-gradient(42% 55% at 18% 8%, color-mix(in srgb, var(--bp, #2A5E9B), transparent 20%), transparent 70%),
      radial-gradient(38% 50% at 82% 12%, color-mix(in srgb, var(--ba, #C1D730), transparent 84%), transparent 70%),
      radial-gradient(50% 60% at 50% 100%, color-mix(in srgb, var(--bp, #2A5E9B), transparent 60%), transparent 72%);
  }
  /* slow aurora. Long cycles on purpose: this hangs on a wall all day and must never
     become the thing people look at instead of the numbers. */
  body::before { content:''; position:fixed; inset:-15%; z-index:0; pointer-events:none;
    background:
      radial-gradient(42% 55% at 18% 8%, rgba(36,79,128,.95), transparent 70%),
      radial-gradient(38% 50% at 82% 12%, rgba(193,215,48,.12), transparent 70%),
      radial-gradient(50% 60% at 50% 100%, color-mix(in srgb, var(--p2) 35%, transparent), transparent 72%);
    animation: aurora 40s ease-in-out infinite alternate; }
  @keyframes aurora {
    0% { transform: translate3d(0,0,0) scale(1); }
    100% { transform: translate3d(-2.5%, 2%, 0) scale(1.08); }
  }
  /* The wall screen is always "idle", so it gets the faster colour travel the app
     only reaches once a manager stops scrolling. */
  body::after { content:''; position:fixed; inset:-22%; z-index:0; pointer-events:none;
    background:
      radial-gradient(24% 26% at 28% 26%, rgba(122,79,155,.26), transparent 70%),
      radial-gradient(22% 24% at 74% 60%, rgba(0,168,150,.26), transparent 70%),
      radial-gradient(20% 22% at 52% 92%, rgba(193,215,48,.16), transparent 72%);
    animation: tvMorph 15s ease-in-out infinite alternate; }
  @keyframes tvMorph {
    0%   { transform: scale(1) rotate(0deg); filter: hue-rotate(0deg) saturate(1); }
    50%  { transform: scale(1.16) rotate(-7deg); filter: hue-rotate(130deg) saturate(1.3); }
    100% { transform: scale(1.3) rotate(12deg); filter: hue-rotate(265deg) saturate(1.1); }
  }
  /* Display tuning, set at the TV itself.
     --tscale   : overall text size
     --squeeze  : horizontal pre-compression. If the TV stretches the picture sideways
                  (casting 4:3 into 16:9, or a stretched picture mode), squeezing the
                  content here means it comes out the right shape on the wall.
     --pad      : edge inset, for TVs that overscan and crop the borders. */
  .wrap { position:relative; z-index:1;
    --tscale: 1; --squeeze: 1; --pad: 0vw;
    padding-left: calc(2vw + var(--pad)); padding-right: calc(2vw + var(--pad));
    transform: scaleX(var(--squeeze));
    transform-origin: center center; }
  .wrap { height:100vh; display:flex; flex-direction:column; padding:2.2vh 2vw; }
  .head { display:flex; align-items:center; justify-content:space-between; margin-bottom:1.6vh; }
  .head-l { display:flex; align-items:center; gap:1.2vw; }
  .head-r { display:flex; align-items:center; gap:2.4vw; }
  .head-logo { width:calc(6.6vh * var(--tscale)); height:calc(6.6vh * var(--tscale)); border-radius:1.2vh; background:#fff; display:flex; align-items:center; justify-content:center; overflow:hidden; }
  .head-logo img { width:100%; height:100%; object-fit:contain; }
  .head-title { font-family:'Space Grotesk',sans-serif; font-weight:700; letter-spacing:-.01em; font-size:calc(5.4vh * var(--tscale)); letter-spacing:.5px; line-height:1; }
  .head-sub { font-size:calc(1.7vh * var(--tscale)); color:#A8CBEA; letter-spacing:.10em; text-transform:uppercase; font-weight:600; }
  .total { text-align:right; }
  .total-num { font-family:'Space Grotesk',sans-serif; font-weight:700; letter-spacing:-.01em; font-size:calc(5.8vh * var(--tscale)); line-height:1; color:var(--lime); }
  .total-cap { font-size:calc(1.5vh * var(--tscale)); color:#A8CBEA; letter-spacing:.10em; text-transform:uppercase; font-weight:700; margin-top:.4vh; }
  .clock { text-align:right; font-family:'Space Grotesk',sans-serif; }
  .clock-time { font-size:calc(3.2vh * var(--tscale)); font-weight:700; }
  .clock-date { font-size:1.5vh; color:#9FC2E4; display:flex; align-items:center; gap:.4vw; justify-content:flex-end; }
  .live { width:.8vh; height:.8vh; border-radius:50%; background:#69E08A; flex:0 0 auto;
    box-shadow:0 0 0 0 rgba(105,224,138,.7); animation: livePulse 2.4s ease-out infinite; }
  @keyframes livePulse {
    0% { box-shadow:0 0 0 0 rgba(105,224,138,.55); }
    70% { box-shadow:0 0 0 1.1vh rgba(105,224,138,0); }
    100% { box-shadow:0 0 0 0 rgba(105,224,138,0); }
  }

  /* ---- the hand-over ----
     The board's unit mark is a car, so a screen changing store is those cars
     making the trip: the outgoing board slides away, a convoy crosses carrying
     the next store's name, and the new board slides in behind it.

     The veil FADES rather than wipes. A wedge wide enough to cover a screen has
     its leading edge off the other side of it while it covers, which takes the
     convoy riding that edge off screen with it — the cars were invisible for
     exactly the part of the move they exist for. A fade lets the convoy cross the
     middle of the screen where it can be seen, and a fade is not a cut. */
  .handoff { position:fixed; inset:0; z-index:60; pointer-events:none; overflow:hidden; }
  /* ---- The convoy's clock ----
     One variable so the veil, the road, the name and the cars can never drift out
     of step with each other, and so the whole hand-over can be lengthened by
     changing a single number. Slow on purpose: this is the one moment the board
     asks to be watched, and at 1.6s it was over before anybody looked up. */
  .handoff { --ho: 3.4s; }
  .ho-veil {
    position:absolute; inset:0; background:rgba(9,20,34,.93);
    animation:hoVeil var(--ho) linear both;
  }
  /* Longer at full strength than before, and eased in and out rather than cut in
     at a fixed frame — the veil is what hides the swap, so the moment it covers is
     the moment there is room to work in. */
  @keyframes hoVeil { 0% { opacity:0 } 14%, 74% { opacity:1 } 100% { opacity:0 } }
  /* a low band of light the convoy travels along, so it reads as a road rather
     than as icons floating on a dark screen */
  .ho-road {
    position:absolute; left:0; right:0; top:0; bottom:0;
    background:linear-gradient(180deg, transparent 6%, rgba(193,215,48,.05) 34%,
      rgba(193,215,48,.09) 50%, rgba(193,215,48,.05) 66%, transparent 94%);
    animation:hoVeil var(--ho) linear both;
  }
  /* Each car carries its own duration: the big ones in the near lanes cross
     faster than the small ones further off, which is what a road actually looks
     like from the side. All of them stay linear — a car that eases into and out
     of its own speed reads as a slide, not as traffic. */
  .ho-car {
    position:absolute; top:var(--lane); left:-24vw; width:var(--sz); height:var(--sz);
    color:#C1D730; opacity:var(--fade, 1);
    filter:drop-shadow(0 0 1.2vh rgba(193,215,48,.55)) drop-shadow(0 0 4vh rgba(193,215,48,.22));
    animation:hoDrive var(--dur, 3s) linear var(--dly) both;
  }
  /* .pix9 sets width:1em and is defined later in this sheet, so the car needs a
     selector that outranks it rather than a bare class of its own. */
  .ho-car > svg { width:100%; height:100%; display:block; }
  @keyframes hoDrive { from { transform:translateX(0) } to { transform:translateX(152vw) } }
  .ho-name {
    position:absolute; top:50%; left:50%; width:76vw; margin-left:-38vw;
    text-align:center; white-space:nowrap;
    font-family:'Space Grotesk',sans-serif; font-weight:700; letter-spacing:-.01em;
    /* --tscale lives on .wrap and this layer is a sibling of it on the body, so
       without the fallback the whole calc is invalid and the text collapses to
       whatever it happens to inherit. */
    font-size:calc(5.6vh * var(--tscale, 1)); color:#F4F9FF;
    text-shadow:0 .4vh 3.4vh rgba(0,0,0,.85);
    animation:hoName var(--ho) cubic-bezier(.32,0,.30,1) both;
  }
  .ho-name .ho-to {
    display:block; font-size:calc(1.5vh * var(--tscale, 1)); letter-spacing:.18em;
    text-transform:uppercase; color:#C1D730; margin-bottom:.8vh; font-weight:700;
  }
  /* The name rides in with the convoy, then holds still in the middle for a beat
     — long enough to actually be read, which is the point of putting it there. */
  @keyframes hoName {
    0%       { transform:translate(-46vw,-50%) scale(.94); opacity:0 }
    26%      { transform:translate(0,-50%)     scale(1);   opacity:1 }
    68%      { transform:translate(0,-50%)     scale(1);   opacity:1 }
    100%     { transform:translate(46vw,-50%)  scale(.96); opacity:0 }
  }
  /* the board steps aside and comes back from the other side, under the veil */
  #root.drive-out { animation:boardOut 1s cubic-bezier(.5,0,.85,.4) both; }
  #root.drive-in  { animation:boardIn 1.15s cubic-bezier(.16,.72,.28,1) both; }
  @keyframes boardOut { to { transform:translateX(-8vw); opacity:0; } }
  @keyframes boardIn { from { transform:translateX(8vw); opacity:0; } }
  @media (prefers-reduced-motion: reduce) {
    .ho-car, .ho-road { display:none }
    #root.drive-out, #root.drive-in { animation-duration:.35s }
    @keyframes boardOut { to { opacity:0 } }
    @keyframes boardIn { from { opacity:0 } }
  }

  /* one panel, one table, everybody visible without scrolling */
  .panel { flex:1; position:relative; background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.1);
    border-radius:1.4vh; padding:1.2vh 1.2vw; min-height:0; overflow:hidden;
    display:flex; flex-direction:column; }
  .scroller { flex:1 1 auto; min-height:0; overflow:hidden; }
  /* The podium stays on screen while the rest of the list walks past it.
     Its own table above the scroller, rather than three sticky rows inside it.
     Sticky was the obvious way and it does not survive this board: every row
     carries the rowIn entrance, whose filled end state leaves an identity
     transform behind, so each row is permanently its own stacking context and a
     z-index on a pinned cell can never lift it above a row that comes later in
     the document. Lifting the three out of the scroll container removes the
     question entirely — nothing overlaps because nothing shares a scrollport.
     Both tables are width:100% with table-layout:fixed and the same column
     classes, which is what keeps the columns lined up across the join. */
  .podium-tbl { flex:0 0 auto; }
  .podium-tbl tbody tr > td { background:rgba(255,255,255,.05); }
  .podium-tbl tbody tr:nth-child(even) > td { background:rgba(255,255,255,.025); }
  /* one hairline where the fixed three meet the moving list */
  .podium-edge { flex:0 0 auto; height:1px; background:rgba(255,255,255,.14); margin:.5vh 0 .4vh; }
  /* soft fade at the bottom edge so a row cut mid-scroll reads as intentional */
  .panel::after { content:''; position:absolute; left:0; right:0; bottom:0; height:5vh; pointer-events:none;
    background:linear-gradient(180deg, transparent, rgba(14,32,51,.75)); border-radius:0 0 1.4vh 1.4vh; }
  /* The table is capped and centred. Stretched across a 65in screen the columns drifted
     so far apart the eye lost the row on the way across. */
  .lb { width:100%; max-width:1500px; margin:0 auto; border-collapse:separate; border-spacing:0; table-layout:fixed; }
  .lb th { font-size:calc(1.7vh * var(--tscale)); text-transform:uppercase; letter-spacing:.10em; color:#A8CBEA;
    font-weight:700; padding:0 .5vw 1.2vh; text-align:center; }
  .lb th.nm { text-align:left; padding-left:1vw; }
  .lb td { padding:var(--rowpad) .5vw; font-size:var(--rowfs); text-align:center; }

  /* zebra striping instead of hairlines: from across the room a solid band is far
     easier to track than a 1px line */
  .lb tbody tr:nth-child(odd) { background:rgba(255,255,255,.045); }
  .lb tbody tr td:first-child { border-radius:1vh 0 0 1vh; }
  .lb tbody tr td:last-child { border-radius:0 1vh 1vh 0; }

  .lb .rank { width:6%; }
  /* podium badges. Gold, silver, bronze read instantly from across a floor. */
  .badge { display:inline-flex; align-items:center; justify-content:center;
    width:calc(var(--rowfs) * 1.7); height:calc(var(--rowfs) * 1.7); border-radius:50%;
    font-family:'Space Grotesk',sans-serif;  font-size:calc(var(--rowfs) * .82);
    background:rgba(255,255,255,.08); color:#8FB3D6; }
  .badge.m1 { background:linear-gradient(145deg,#FFD75E,#E0A100); color:#3A2B00;
    box-shadow:0 0 calc(var(--rowfs)*.8) rgba(255,200,60,.55); }
  .badge.m2 { background:linear-gradient(145deg,#E6ECF2,#AFBECB); color:#2A3540; }
  .badge.m3 { background:linear-gradient(145deg,#E8A87C,#C0764A); color:#3A1E0B; }

  .lb .nm { width:30%; text-align:left; padding-left:1vw; font-weight:700;
    font-size:calc(var(--rowfs) * 1.12); letter-spacing:-.01em;
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

  /* Delivered doubles as a bar chart: volume is instantly comparable down the column */
  .lb .sold { width:14%; position:relative; }
  /* --barw is a percentage of the cell, and the leader gets 100%. Starting at 6% meant
     the leader's bar ran to 106% and spilled into the Internet column. Scale it into
     the space that actually exists. */
  .lb .sold .bar { position:absolute; left:5%; top:14%; bottom:14%;
    width:calc(var(--barw) * 0.86);
    background:linear-gradient(90deg, rgba(193,215,48,.32), rgba(193,215,48,.08));
    border-radius:.5vh; z-index:0; transition:width .8s cubic-bezier(.22,1,.36,1); }
  .lb .sold .soldnum { position:relative; z-index:1;
    font-family:'Space Grotesk',sans-serif;  color:var(--lime);
    font-size:calc(var(--rowfs) * 1.45); }
  .lb .pcell { width:16.6%; white-space:nowrap; }

  /* rows arrive in sequence rather than all at once */
  .lb tbody tr.row { animation: rowIn .5s cubic-bezier(.22,1,.36,1) both;
    animation-delay: calc(var(--i) * 45ms); }
  @keyframes rowIn { from { opacity:0; transform: translateY(1.2vh); } to { opacity:1; transform:none; } }

  /* the leader gets a lit band and a slow shine that travels across it */
  .lb tbody tr.leader { position:relative; }
  .lb tbody tr.leader td { background:linear-gradient(90deg, rgba(193,215,48,.16), rgba(193,215,48,.03) 60%, transparent); }
  .lb tbody tr.leader .nm { color:#F2F7DC; }
  .lb tbody tr.leader .nm::after { content:''; position:absolute; inset:0; pointer-events:none;
    background:linear-gradient(105deg, transparent 35%, rgba(255,255,255,.16) 50%, transparent 65%);
    background-size:220% 100%; animation: shine 5.5s ease-in-out infinite; }
  @keyframes shine { 0% { background-position:180% 0; } 55%,100% { background-position:-60% 0; } }

  .pill { font-family:'Space Grotesk',sans-serif; font-weight:700; letter-spacing:-.01em; font-size:calc(var(--rowfs) * 1.05);
    padding:.3vh 0; border-radius:.9vh; display:inline-flex; align-items:center; justify-content:center;
    width:7vw; text-align:center; box-sizing:border-box; font-variant-numeric:tabular-nums; }
  .pill.g { background:var(--greenbg); color:var(--green); }
  .pill.y { background:var(--yellowbg); color:var(--yellow); }
  .pill.r { background:var(--redbg); color:var(--red); }
  .pill.dim { background:rgba(255,255,255,.07); color:#6E93BC; }
  .pill-mark { display:inline-flex; align-items:center; line-height:0; margin-right:.35vw; opacity:1;
    font-size:calc(var(--rowfs) * 1.05); }
  /* Every dot glyph is one em square and inherits the colour of the text around it,
     so a mark, an arrow and a car all scale with the row rather than fighting it. */
  .pix9 { width:1em; height:1em; display:block; fill:currentColor; }
  .pix-flat { opacity:.5; }
  /* The trend slot is a fixed width. It used to size itself to its contents, so a
     row carrying a delta pushed its pill sideways and the column stopped lining up. */
  .move { display:inline-flex; align-items:center; gap:.25vw; justify-content:flex-start;
    position:absolute; left:100%; top:50%; transform:translateY(-50%); margin-left:.5vw;
    width:3.6vw; min-width:3.6vw; }
  .lb .pcell { text-align:center; }
  .pcell-in { position:relative; }
  .lb .pcell-in { display:inline-flex; align-items:center; justify-content:center; }
  .trend { font-size:calc(var(--rowfs) * 1.0); display:inline-flex; align-items:center; }
  .delta { font-size:calc(var(--rowfs) * .72); font-weight:700; font-variant-numeric:tabular-nums; }
  .up { color:#69E08A; } .down { color:#FF8A80; } .flat { color:#5C7F9F; }

  .flag { color:#FFCF6B; }
  .foot { text-align:center; font-size:1.4vh; color:#7FA8D4; margin-top:1.1vh; letter-spacing:.04em; }
  .empty { color:#7FA8D4; font-size:2vh; padding:4vh; text-align:center; }
  .fade { animation:fade .5s ease; } @keyframes fade { from{opacity:0;transform:translateY(6px);} to{opacity:1;} }

  /* tuning controls: nearly invisible until someone goes looking for them */
  .gear { position:fixed; right:1.2vw; bottom:1.2vh; z-index:40; width:4.4vh; height:4.4vh; border-radius:50%;
    border:1px solid rgba(255,255,255,.16); background:rgba(255,255,255,.07); color:#9FC2E4;
    font-size:2.2vh; cursor:pointer; opacity:.16; transition:opacity .25s, background .25s; }
  .gear:hover { opacity:1; background:rgba(255,255,255,.14); }
  /* ---- Bars style (Digital-Dealership-System look): one huge striped bar per person ---- */
  .lb2 { width:100%; max-width:1500px; margin:0 auto; border-collapse:separate; border-spacing:0; table-layout:fixed; }
  .lb2 th { font-size:calc(1.7vh * var(--tscale)); text-transform:uppercase; letter-spacing:.04em; color:#A8CBEA;
    padding:.6vh .4vw; border-bottom:1px solid rgba(255,255,255,.14); text-align:left;
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
  .lb2 td { padding:var(--rowpad) .5vw; font-size:var(--rowfs); }
  .lb2 tbody tr:nth-child(odd) { background:rgba(255,255,255,.045); }
  .lb2 tbody tr td:first-child { border-radius:1vh 0 0 1vh; }
  .lb2 tbody tr td:last-child { border-radius:0 1vh 1vh 0; }
  .lb2 .rank { width:5%; text-align:center; }
  .lb2 .nm { width:12%; font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
  .lb2 .sold2 { width:10%; text-align:center; padding-right:1vw; }
  .lb2 td.sold2 { font-family:'Space Grotesk',sans-serif; font-weight:700; letter-spacing:-.01em;
    font-size:calc(var(--rowfs) * 1.1); }
  /* Each % column is a fixed width and its contents are centred, so every pill is
     the same size across the whole board. The pill has a fixed width too (all
     percentages read identically), and the arrow lives in a reserved lane to the
     right so a row with movement doesn't shove the pill off-centre from one without. */
  .lb2 .pcell2 { width:15%; text-align:center; white-space:nowrap; }
  .lb2 .pcell-in { display:inline-flex; align-items:center; justify-content:center; }
  /* pill + arrow are sized in em so they grow with the row's own font, not the
     screen width — on a wide TV the row gets taller and the pills grow with it,
     and horizontal scroll (already built) covers any overflow. */
  .lb2 .pcell2 .pill { width:5.6em; min-width:0; padding:.28em 0; text-align:center;
    font-size:calc(var(--rowfs) * .96); }
  .lb2 .move2 { width:2.6em; min-width:2.6em; margin-left:.4em; justify-content:flex-start; }
  .lb2 .move2 .delta { font-size:calc(var(--rowfs) * .66); }
  .lb2 .move2 .trend { font-size:calc(var(--rowfs) * .95); }
  .lb2 .sold2 { width:10%; text-align:center; }
  .lb2 td.sold2 { padding:0; font-size:calc(var(--rowfs) * 1.15); }
  .lb2 .sold2 .soldnum { display:inline-block; }
  .lb2 .carcell { width:26%; padding-left:.6vw; }
  /* soft "holding the last board" banner when a refresh is distrusted */
  .stale-note { position:fixed; left:50%; top:1.4vh; transform:translate(-50%,-140%); z-index:60;
    background:rgba(20,40,66,.92); color:#DCEBFA; font-weight:600; font-size:1.8vh;
    padding:1vh 2vw; border-radius:1vh; border:1px solid rgba(136,198,234,.3);
    box-shadow:0 1vh 3vh rgba(0,0,0,.35); backdrop-filter:blur(8px);
    transition:transform .6s cubic-bezier(.22,1,.36,1); pointer-events:none; }
  .stale-note.on { transform:translate(-50%, 0); }

  /* congratulations sweep: a card per new sale, entering from the right with a
     confetti burst, holding, then sliding off. Staggered so a double gets its own. */
  .congrats { position:fixed; right:2.5vw; top:12vh; z-index:70; display:flex; flex-direction:column;
    gap:1.4vh; pointer-events:none; transition:opacity .7s ease; }
  .congrats.out { opacity:0; }
  .cg-card { position:relative; display:flex; align-items:center; gap:1.2vw; overflow:visible;
    background:linear-gradient(120deg, rgba(193,215,48,.96), rgba(120,180,60,.96));
    color:#132; padding:1.6vh 2vw 1.6vh 1.6vw; border-radius:1.4vh; min-width:22vw;
    box-shadow:0 1.4vh 4vh rgba(0,0,0,.4), inset 0 1px 0 rgba(255,255,255,.5);
    transform:translateX(120%); opacity:0;
    animation: cgIn .7s cubic-bezier(.22,1,.36,1) var(--d) forwards,
               cgOut .6s ease calc(var(--d) + 4.4s) forwards; }
  @keyframes cgIn  { from { transform:translateX(120%); opacity:0; } to { transform:translateX(0); opacity:1; } }
  @keyframes cgOut { from { transform:translateX(0); opacity:1; } to { transform:translateX(120%); opacity:0; } }
  .cg-ico { font-size:4vh; line-height:1; animation: cgPop .5s ease var(--d) both; }
  @keyframes cgPop { 0%{ transform:scale(0) rotate(-20deg);} 60%{ transform:scale(1.25) rotate(8deg);} 100%{ transform:scale(1) rotate(0);} }
  .cg-txt b { font-family:'Space Grotesk',sans-serif; font-size:2.7vh; display:block; letter-spacing:-.01em; }
  .cg-txt span { font-size:1.9vh; font-weight:600; opacity:.85; }
  /* confetti burst behind the icon */
  .cg-burst { position:absolute; left:2.6vw; top:50%; width:0; height:0; }
  .cg-burst::before, .cg-burst::after { content:''; position:absolute; left:0; top:0; width:.9vh; height:.9vh;
    border-radius:2px; animation: cgConfetti 1s ease var(--d) both; }
  .cg-burst::before { background:#2A5E9B; }
  .cg-burst::after  { background:#fff; animation-delay: calc(var(--d) + .08s); }
  @keyframes cgConfetti {
    0% { transform:translate(0,0) scale(1); opacity:1; }
    100% { transform:translate(3vw,-4vh) scale(0); opacity:0; }
  }
  .car-more { font-family:'Space Grotesk',sans-serif; font-weight:700; font-size:calc(var(--rowfs) * .9);
    color:#C7DDF2; margin-left:.4vw; align-self:center; }
  .cars { display:flex; align-items:center; flex-wrap:nowrap; gap:0 .12vw; overflow:hidden;
    animation: carsIn .6s cubic-bezier(.22,1,.36,1) both; animation-delay:calc(var(--i) * .06s); }
  @keyframes carsIn { from { opacity:0; transform:translateX(-1vw); } to { opacity:1; transform:none; } }
  .cars-inner { display:flex; align-items:center; flex-wrap:nowrap; gap:0 .1vw; width:100%; }
  .car { width:calc(var(--rowfs) * var(--csz, 1)); height:calc(var(--rowfs) * var(--csz, 1)); flex:0 0 auto;
    fill:var(--carfill); }
  .cars.g { --carfill:#3ECf6E; } .cars.y { --carfill:#EFD75A; } .cars.r { --carfill:#EF6A72; }
  /* the delivered number sits right of the % pills now, with its trend beside it */
  .lb2 .sold2 .move { min-width:0; margin-left:.3vw; }
  .lb2 td.sold2 { line-height:1.05; }
  .lb2 tbody tr.leader .nm { color:var(--lime); }

  /* bottom ticker, bars style only: streaks and callouts drift by like a news crawl */
  .ticker { position:relative; overflow:hidden; margin-top:1vh; border-radius:1vh;
    background:rgba(255,255,255,.06); border:1px solid rgba(255,255,255,.10);
    font-size:calc(2.1vh * var(--tscale)); font-weight:700; padding:.8vh 0; }
  .ticker-track { display:inline-block; white-space:nowrap; padding-left:100%;
    animation: tickerMove var(--tickdur, 40s) linear infinite; }
  @keyframes tickerMove { to { transform: translateX(-100%); } }
  .ticker-item { display:inline-block; margin-right:3.5vw; }
  .ticker-item .tk-cap { color:#A8CBEA; font-weight:600; margin-right:.4vw; }

  .tuner-seg { display:flex; gap:.5vw; margin-bottom:1vh; }
  .tuner-seg button { flex:1; padding:.8vh .5vw; border-radius:.9vh; border:1px solid rgba(255,255,255,.18);
    background:transparent; color:#BFD9F0; cursor:pointer; font:inherit; font-size:1.6vh; }
  .tuner-seg button.on { background:#C1D730; border-color:#C1D730; color:#0E2033; font-weight:800; }

  .tuner { position:fixed; right:1.2vw; bottom:7vh; z-index:41; width:min(340px, 32vw);
    background:rgba(10,24,40,.96); border:1px solid rgba(255,255,255,.14); border-radius:1.4vh;
    padding:1.6vh 1.4vw; display:none; box-shadow:0 1.5vh 4vh rgba(0,0,0,.55); font-size:1.6vh; }
  .tuner.on { display:block; }
  .tuner-head { display:flex; justify-content:space-between; align-items:center;
    font-weight:800; font-size:1.9vh; margin-bottom:1.2vh; }
  .tuner-x { background:none; border:none; color:#9FC2E4; font-size:2.4vh; cursor:pointer; line-height:1; }
  .tuner-row { display:block; margin-bottom:1vh; }
  .tuner-row span { display:flex; justify-content:space-between; color:#BFD9F0; margin-bottom:.5vh; }
  .tuner-row b { color:#fff; }
  .tuner-row input[type=range] { width:100%; accent-color:#C1D730; }
  .tuner-rota { display:flex; flex-direction:column; gap:.5vh; margin:.6vh 0 .2vh; max-height:22vh; overflow-y:auto; }
  .tuner-rota button { display:flex; align-items:center; gap:.7vw; width:100%; text-align:left;
    font:inherit; font-size:1.5vh; color:#DCE9F6; background:rgba(255,255,255,.06);
    border:1px solid rgba(255,255,255,.12); border-radius:.8vh; padding:.7vh .9vw; cursor:pointer; }
  .tuner-rota button.on { background:rgba(193,215,48,.16); border-color:rgba(193,215,48,.5); color:#F2F7DC; }
  .tuner-rota .tick { flex:0 0 auto; width:1.6vh; height:1.6vh; border-radius:.4vh;
    border:1px solid rgba(255,255,255,.3); display:grid; place-items:center; font-size:1.1vh; }
  .tuner-rota button.on .tick { background:#C1D730; border-color:#C1D730; color:#26301A; }
  .tuner-rota .none { color:#8FB3D6; font-size:1.4vh; padding:.4vh 0; }
  .tuner-hint { color:#7FA8D4; font-size:1.35vh; margin:-.3vh 0 1.2vh; line-height:1.45; }
  .tuner-foot { display:flex; gap:.6vw; margin-top:1.4vh; }
  .tuner-btn { flex:1; padding:.9vh .6vw; border-radius:.9vh; border:1px solid rgba(255,255,255,.18);
    background:rgba(255,255,255,.06); color:#EAF1F8; font-size:1.5vh; font-weight:700; cursor:pointer; }
  .tuner-btn.primary { background:#C1D730; color:#1F2A00; border-color:#C1D730; }
  .tuner-msg { color:#69E08A; font-size:1.35vh; margin-top:.8vh; min-height:1.6vh; }

  /* ---- on a phone ----
     This board is laid out for a television: seven columns, everything sized in
     vh so it fills a wall. On a 390px screen the columns run off the right and
     the units bar lands on top of the Delivered figure.

     Same board, made to fit. Each person becomes a card — rank and name on top
     with the units figure, the three channel rates on their own row, the bar
     underneath — and vh gives way to px, because a phone's viewport height has
     nothing to do with how big text should be in the hand. Nothing is dropped:
     it is the same seven cells, stacked. */
  @media (max-width: 700px) {
    body { overflow-y:auto; }
    .wrap, .panel { height:auto; min-height:0; padding:10px 12px 28px; }
    /* The header rules here used to name .head h1, .store, .kpi, .sub and
       .kpi-lbl — none of which this board has. They matched nothing, so the
       header kept its wall sizes: a 45px store name over a 70px logo. These are
       the real class names. */
    .head { flex-wrap:wrap; gap:10px 14px; padding:12px; }
    .head-l { flex:1 1 100%; gap:10px; min-width:0; }
    .head-logo { width:40px; height:40px; border-radius:9px; flex:0 0 auto; }
    .head-title { font-size:22px; line-height:1.1; letter-spacing:0; }
    .head-sub { font-size:10.5px; }
    /* The units figure and the clock keep the right-hand side they hold on a
       TV. Wrapping put them on their own line but left them hard against the
       left edge, under the store name, reading as two more lines of the title
       block rather than as the day's number. */
    .head-r { flex:1 1 100%; justify-content:flex-end; align-items:flex-end; gap:18px; }
    .total-num { font-size:30px; }
    .total-cap, .clock-date { font-size:10px; }
    .clock-time { font-size:18px; }
    .scroller { overflow:visible; }
    .gear { width:34px; height:34px; font-size:15px; opacity:.5; right:10px; bottom:10px; }

    /* Almost every size on this board is calc(var(--rowfs) * n), and --rowfs is
       set inline in vh so the rows fill a wall. On a phone that makes the badge,
       the pills, the arrows and the deltas all read the viewport HEIGHT, which is
       why they came out at wildly different weights from the px sizes below them.
       Pinning --rowfs to px here re-bases the whole sheet in one line. It needs
       !important only because the vh value is an inline style on .panel. */
    .panel { --rowfs:12px !important; --rowpad:5px !important; }

    .lb, .lb2 { display:block; table-layout:auto; }
    .lb thead, .lb2 thead { display:none; }          /* each cell carries its own label */
    .lb tbody, .lb2 tbody, .lb tr, .lb2 tr, .lb td, .lb2 td { display:block; }
    /* Three equal columns, not 34px | 1fr | auto. The old tracks were cut for
       row 1 and row 2 had to live in them too — so the first rate was squeezed
       into a 34px track and the third pushed its delta off the side of the card.
       That is the "spread out weirdly". Row 1 keeps its narrow badge by letting
       the name SHARE the badge's column and step past it with padding; grid items
       are allowed to overlap, and it is what lets both rows use one set of
       tracks. */
    .lb tr, .lb2 tr {
      display:grid; grid-template-columns:repeat(3, 1fr); gap:6px 10px; align-items:center;
      margin-bottom:8px; padding:10px 12px; border-radius:14px;
      background:rgba(255,255,255,.06) !important; }
    .lb td, .lb2 td { padding:0; font-size:15px; }
    .lb .rank, .lb2 .rank { grid-column:1; grid-row:1; width:auto; font-size:15px;
      justify-self:start; z-index:1; }
    .badge { width:28px; height:28px; font-size:13px; }
    .lb .nm, .lb2 .nm { grid-column:1 / 3; grid-row:1; width:auto; font-size:17px;
      padding-left:36px; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
    .lb .sold, .lb2 .sold2 { grid-column:3; grid-row:1; width:auto; text-align:right;
      font-size:20px; padding-right:0; }
    .lb .sold .soldnum, .lb2 .sold2 .soldnum { font-size:20px; }

    /* the three rates share one row, evenly */
    .lb .pcell, .lb2 .pcell2 { grid-row:2; width:auto; text-align:center; font-size:12px; }
    .lb .pcell:nth-of-type(4), .lb2 .pcell2:nth-of-type(3) { grid-column:1; }
    .lb .pcell:nth-of-type(5), .lb2 .pcell2:nth-of-type(4) { grid-column:2; }
    .lb .pcell:nth-of-type(6), .lb2 .pcell2:nth-of-type(5) { grid-column:3; }
    /* The pill is 5.6em wide and its arrow another 2.6em on a TV, where the
       column is a fixed 15% of a very wide table. In a third of a phone card
       those add up to more than the column holds, and the overflow is what ran
       off the right. Both size to their content here. */
    /* This is the one that actually caused it. On a TV the trend is pinned
       OUTSIDE its pill — position:absolute, left:100% — so the pills stay on a
       shared grid no matter who has a delta. Hung off the end of a third of a
       phone card, each arrow landed on top of the next pill along and the last
       one hung off the edge of the card entirely. Back in flow here, and under
       the pill rather than beside it, because side by side the pair is wider
       than the column. */
    .lb .pcell-in, .lb2 .pcell-in { display:flex; flex-direction:column;
      align-items:center; justify-content:center; gap:2px; min-width:0; }
    .lb .pcell .move, .lb2 .pcell2 .move { position:static; transform:none;
      margin-left:0; width:auto; min-width:0; justify-content:center; }
    .lb2 .pcell2 .pill { width:auto; min-width:0; padding:.3em .5em; }
    .lb2 .move2 { width:auto; min-width:0; margin-left:0; }

    /* width:auto matters as much as the grid placement. The desktop rule sets
       .carcell to 26% for a seven-column table, and 26% of a phone card is 82px
       — so the units row was folding onto three lines inside a strip a quarter
       of the card wide while the rest of the row sat empty. */
    .lb2 .carcell { grid-column:1 / -1; grid-row:3; width:auto;
      padding-left:0 !important; text-align:left; }
    .lb2 .carcell svg, .lb2 .carcell .pix { max-width:100%; }
    /* One glyph is one unit, so a phone must wrap them rather than clip them —
       nowrap plus overflow:hidden silently cut a big month down to whatever fit
       the width, which is the one thing this row must never do. */
    .cars, .cars-inner { flex-wrap:wrap; overflow:visible; row-gap:2px; }
    .cars { height:auto; }
    .crown { font-size:13px; }
  }
</style></head>
<body>
<div class="stale-note" id="stale-note">Holding the last board: the newest report looked incomplete. Updating on the next cycle.</div>
<div class="wrap" id="root"><div class="empty">Loading leaderboard…</div></div>

<!-- Tuning happens standing at the TV, so the controls live here rather than back in the app. -->
<button class="gear" id="gear" title="Display settings">&#9881;</button>
<div class="tuner" id="tuner">
  <div class="tuner-head">Display <button class="tuner-x" id="tclose">&times;</button></div>

  <label class="tuner-row"><span>Board style</span></label>
  <div class="tuner-seg">
    <button id="sty-classic">Classic</button>
    <button id="sty-bars">Bars</button>
  </div>

  <label class="tuner-row"><span>Background</span></label>
  <div class="tuner-seg">
    <button id="bg-navy">Navy</button>
    <button id="bg-store">Store colors</button>
  </div>

  <label class="tuner-row">
    <span>Text size <b id="v-t">100%</b></span>
    <input id="s-t" type="range" min="60" max="160" step="5" value="100">
  </label>

  <label class="tuner-row">
    <span>Horizontal squeeze <b id="v-s">100%</b></span>
    <input id="s-s" type="range" min="70" max="100" step="1" value="100">
  </label>
  <p class="tuner-hint">If the TV stretches the picture sideways, pull this down until the letters look the right shape on the wall.</p>

  <label class="tuner-row">
    <span>Edge inset <b id="v-p">0%</b></span>
    <input id="s-p" type="range" min="0" max="8" step="0.5" value="0">
  </label>
  <p class="tuner-hint">For screens that crop the edges.</p>

  <label class="tuner-row"><span>Also show</span></label>
  <div class="tuner-rota" id="rot-list"></div>
  <p class="tuner-hint">Tick a store and this screen will show its board too, handing over each time the list has scrolled all the way down.</p>

  <div class="tuner-foot">
    <button class="tuner-btn" id="treset">Reset</button>
    <button class="tuner-btn primary" id="tsave">Save for this store</button>
  </div>
  <div class="tuner-msg" id="tmsg"></div>
</div>
<script>
  var CFG = ${JSON.stringify(p)};
  // The same one grid as the rest of the tool, sent whole rather than as two
  // tables the board then has to choose between. Drawn at 1em so every mark
  // scales with the row text instead of being pinned to a pixel size.
  var PIXG = ${JSON.stringify(PIX)};
  function pix(g, cls, frac){
    var rows = PIXG[g] || PIXG.dot, out = '';
    var n = rows.length;
    var r = 0.48;   // same ratio as PixIcon, and for the same reason
    for (var y = 0; y < n; y++) {
      var row = rows[y];
      for (var x = 0; x < row.length; x++) {
        if (row[x] !== '1') continue;
        // frac fills the glyph left to right, which is how a half unit is drawn
        var lit = (frac == null) || (((x + 0.5) / row.length) <= frac);
        out += '<circle cx="' + (x + 0.5) + '" cy="' + (y + 0.5) + '" r="' + r + '"'
          + (lit ? '' : ' fill="rgba(255,255,255,.13)"') + '/>';
      }
    }
    return '<svg class="pix9' + (cls ? ' ' + cls : '') + '" viewBox="0 0 ' + n + ' ' + n + '"'
      + ' shape-rendering="geometricPrecision">' + out + '</svg>';
  }
  function norm(s){return (s||'').trim().toLowerCase().replace(/\\s+/g,' ');}
  // No external library and no CDN. A TV on a dealership network may not be able to
  // reach an external CDN at all, and an import that never resolves left it stuck on
  // "Loading" forever. Plain fetch against the REST API, with the token refreshed by
  // hand so the screen can sit there unattended for days.
  var TOK = CFG.tokens ? {
    access: CFG.tokens.access_token,
    refresh: CFG.tokens.refresh_token
  } : null;
  // The board row is readable with the anon key alone, which is what lets a TV with
  // nobody signed in sit there for weeks. A signed-in session is used when one was
  // handed over, but nothing here depends on it.
  var DB = CFG.db || (CFG.tokens ? { url: CFG.tokens.url, anonKey: CFG.tokens.anonKey } : null);

  function withTimeout(promise, ms){
    return Promise.race([
      promise,
      new Promise(function(_, rej){ setTimeout(function(){ rej(new Error('timeout')); }, ms); })
    ]);
  }

  async function refreshToken(){
    if (!TOK || !TOK.refresh) return false;
    try {
      var r = await withTimeout(fetch(CFG.tokens.url + '/auth/v1/token?grant_type=refresh_token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', apikey: CFG.tokens.anonKey },
        body: JSON.stringify({ refresh_token: TOK.refresh })
      }), 12000);
      if (!r.ok) return false;
      var d = await r.json();
      if (!d.access_token) return false;
      TOK.access = d.access_token;
      if (d.refresh_token) TOK.refresh = d.refresh_token;
      return true;
    } catch (e) { return false; }
  }

  function getStore(){ return getStoreByKey(CFG.storeKey); }
  async function getStoreByKey(storeKey){
    if (!DB) return { __err: 'This board has no database details. Open it again from the tool.' };
    var url = DB.url + '/rest/v1/app_data?key=eq.' + encodeURIComponent(storeKey) + '&select=value';
    function headers(){
      return { apikey: DB.anonKey, Authorization: 'Bearer ' + (TOK ? TOK.access : DB.anonKey) };
    }
    try {
      var res = await withTimeout(fetch(url, { headers: headers() }), 12000);
      if (res.status === 401 || res.status === 403) {
        var ok = await refreshToken();
        if (!ok) return { __err: 'This screen cannot read the board row. Check the database read rule for lpc:board keys.' };
        res = await withTimeout(fetch(url, { headers: headers() }), 12000);
      }
      if (!res.ok) return { __err: 'Could not reach the database (' + res.status + '). Retrying...' };
      var rows = await res.json();
      return (rows && rows[0]) ? rows[0].value : null;
    } catch (e) {
      return { __err: 'No connection to the database. Retrying...' };
    }
  }

  // keep the session alive well before it lapses, so an all-day board never drops out
  setInterval(function(){ refreshToken(); }, 40 * 60 * 1000);
  // each channel is judged on its own scale: a 25% showroom close and a 25% internet
  // close are nowhere near the same achievement
  // A row of little cars: one filled car per whole unit, a half-filled car for a
  // half (splits credit .5). Scaled against the leader and capped so a monster
  // month can't run off a TV.
  // One car per whole unit, a half-filled car for a .5 split, always matching the
  // number exactly. If the leader is over CAP whole cars we DON'T rescale the
  // count (that broke the 1-car-per-unit promise and rounded 5.5 up to 6); we draw
  // the honest cars up to CAP and append a "+N" so the row still fits a TV.
  var CAR_ROW = 0;
  function cars(sold, maxSold){
    // Cars shrink to fit: the row-leader's count sets the size for everyone, so the
    // whole column shares one scale and the biggest month still fits on one line.
    // Past HARDCAP even that is illegible, so those overflow into a "+N".
    var HARDCAP = 34;
    CAR_ROW++;
    var whole = Math.floor(sold + 1e-6);
    var half = (sold - whole) >= 0.5 - 1e-6 ? 1 : 0;
    var CAP = HARDCAP;
    // A dot car. A half unit lights the left half of the grid, so the split still
    // reads honestly from across the floor without any clip paths to collide.
    function car(frac){ return pix('car', 'car', frac <= 0 ? 0 : frac); }
    var drawWhole = Math.min(whole, CAP);
    // The most anyone sold decides the shared car size: more cars => smaller cars,
    // clamped so a light day's cars don't balloon. Set once per render on the row.
    var peak = Math.min(Math.max(maxSold, 1), CAP + (half ? 0.5 : 0));
    var sizeEm = Math.max(0.62, Math.min(1.15, 22 / peak));
    var out = '<span class="cars-inner" style="--csz:' + sizeEm.toFixed(3) + '">';
    for (var i=0;i<drawWhole;i++) out += car(1);
    if (whole <= CAP && half) out += car(0.5);
    if (whole > CAP) out += '<span class="car-more">+'+(whole - CAP + (half ? 0.5 : 0))+'</span>';
    if (!whole && !half) out += car(0);
    out += '</span>';
    return out;
  }

  function soldArrow(cur, prev){
    if (prev == null || cur == null) return ['','',''];
    var d = cur - prev;
    if (d > 0.001)  return ['up','▲','+'+(Math.round(d*10)/10)];
    if (d < -0.001) return ['down','▼',(Math.round(d*10)/10).toString()];
    return ['flat','',''];
  }
  function soldMove(cur, prev){
    var ar = soldArrow(cur, prev);
    if (!ar[0] || ar[0]==='flat') return '';
    var delta = ar[2] ? '<span class="delta '+ar[0]+'">'+ar[2]+'</span>' : '';
    return '<span class="move"><span class="trend '+ar[0]+'">'+ar[1]+'</span>'+delta+'</span>';
  }

  function tone(pct, ch){
    if (pct==null) return 'r';
    var t = (CFG.thresholds && CFG.thresholds[ch]) || { green: 20, yellow: 10 };
    var v = pct*100;
    if (v>=t.green) return 'g';
    if (v>=t.yellow) return 'y';
    return 'r';
  }
  // symbol as well as colour, so the board reads for colour-blind viewers too
  function toneMark(t){ return pix(t === 'g' ? 'check' : t === 'y' ? 'warn' : 'close'); }
  // direction AND distance moved since the previous report, in percentage points
  function arrow(cur, prev){
    if (cur==null||prev==null) return ['flat', pix('dot','pix-flat'), ''];
    var d = (cur - prev) * 100;
    if (d > 0.05)  return ['up', pix('triup'), '+'+d.toFixed(1)];
    if (d < -0.05) return ['down', pix('tridown'), d.toFixed(1)];
    return ['flat', pix('dot','pix-flat'), ''];
  }
  function fmtPct(v){ return v==null?'-':(v*100).toFixed(1)+'%'; }
  function num(v){ return v==null?0:v; }
  function render(store){
    CAR_ROW = 0;
    var root = document.getElementById('root');
    // an error is not the same as an empty store: say which, never just hang
    if (store && store.__err){
      root.innerHTML = '<div class="empty">' + store.__err + '</div>';
      return;
    }
    if (!store){ root.innerHTML = '<div class="empty">No data yet for this store. Import the delivery reports in the tool and this board will fill in.</div>'; return; }
    var M = (store.months||{})[CFG.ym] || {stats:{}};

    // CFG.roles already excludes any role turned off for The Board (BDC by default),
    // so only the people who actually deliver units show up here.
    var boardRoles = {};
    (CFG.roles||[]).forEach(function(r){ boardRoles[r.id] = true; });

    var gone = {};
    (CFG.departed || store.departed || []).forEach(function(n){ gone[norm(n)] = true; });
    var people = (store.roster||[])
      .filter(function(a){ return a.roleId && boardRoles[a.roleId] && !gone[norm(a.name)]; })
      .map(function(a){
        var s = M.stats[norm(a.name)] || {};
        var iU=num(s.internetUnits), pU=num(s.phoneUnits), rU=num(s.showroomUnits);
        var cU=num(s.campaignUnits);   // service-to-sales and finance apps: units count, close rate is not graded
        var haveAll = (s.internetUnits!=null) && (s.phoneUnits!=null) && (s.showroomUnits!=null);
        return {
          name:a.name,
          internetPct:s.internetPct, phonePct:s.phonePct, showroomPct:s.showroomPct,
          prev:(s.prevPct||{}),
          camp: cU,
          sold: iU+pU+rU+cU,
          prevSold: (function(pu){
            if(!pu) return null;
            var any = ['internet','phone','showroom','campaign'].some(function(c){ return pu[c]!=null; });
            if(!any) return null;
            return num(pu.internet)+num(pu.phone)+num(pu.showroom)+num(pu.campaign);
          })(s.prevUnits),
          haveAll:haveAll
        };
      })
      .sort(function(a,b){ return b.sold - a.sold; });

    // Short display names: first name + last initial ("Sterling B.") to buy the bars
    // room. If two people collide (Juan R. twice), the last-name prefix grows just
    // enough to tell them apart (Juan Ra. / Juan Ro.) instead of showing the same tag.
    (function(){
      function parts(n){ var t = String(n||'').trim().split(/\\s+/); return { first: t[0]||'', rest: t.slice(1).join(' ') }; }
      people.forEach(function(x){
        var pr = parts(x.name);
        x.disp = pr.rest ? pr.first + ' ' + pr.rest[0] + '.' : pr.first;
      });
      var need = true, len = 1;
      while (need && len < 8) {
        need = false;
        var seen = {};
        people.forEach(function(x){ seen[x.disp] = (seen[x.disp]||0) + 1; });
        people.forEach(function(x){
          if (seen[x.disp] > 1) {
            var pr = parts(x.name);
            if (pr.rest && pr.rest.length > len) { x.disp = pr.first + ' ' + pr.rest.slice(0, len+1) + '.'; need = true; }
          }
        });
        len++;
      }
    })();

    var totalSold = people.reduce(function(n,x){ return n + x.sold; }, 0);
    var grandFlag = Math.abs(totalSold - Math.round(totalSold)) > 0.01;

    // Everyone has to fit on one screen with no scrolling, so the rows scale to the
    // size of the team rather than being a fixed height.
    // Size from the space that is actually available rather than a fixed lookup.
    // This is on a TV across a showroom floor, so fill the screen: a small team should
    // read enormous, and a big team should still be as large as it possibly can be.
    var n = Math.max(people.length, 1);
    var AVAIL = 80;                                   // vh the table body gets
    /* The ceiling is what a rota exposed: a fifteen-person store fills the wall,
       then hands over to a three-person store that stopped growing at the old cap
       and sat in the top third of an empty screen. Both boards are sized from the
       screen, so both should reach the bottom of it — a small team is not a small
       board, it is a board with enormous rows. */
    var rowH  = Math.min(20, AVAIL / (n + 1));
    /* Six columns have to fit across as well, and type is sized in vh — so the real
       ceiling on a short list is the WIDTH of the screen, not its height. 3.15% of
       the width is the size the columns stop colliding at; on a 16:9 TV that is the
       5.6vh this board has always used, and a wider wall gets the benefit. */
    var wideCap = 3.15 * (window.innerWidth / window.innerHeight);         // vh
    // Never shrink below what is readable from across a floor. If the team does not
    // fit at that size, the board scrolls instead of squinting.
    var rowFs = Math.max(2.2, Math.min(wideCap, rowH * 0.62)) * DISP.tscale;   // vh
    /* Whatever height the type could not take, the row takes: a three-person store
       reaching the bottom of the wall in tall bands beats the same three rows
       stacked in the top third with the rest of the screen empty. */
    var tightPad = Math.max(0.35, rowH * 0.10) * DISP.tscale;
    var rowPad = Math.max(tightPad, (rowH - rowFs * 1.35) / 2 * DISP.tscale);

    function cell(pct, prevVal, ch){
      if (pct == null) return '<td class="pcell"><span class="pcell-in"><span class="pill dim">-</span><span class="move"></span></span></td>';
      var tn = tone(pct, ch);
      var ar = arrow(pct, prevVal);
      var delta = ar[2] ? '<span class="delta '+ar[0]+'">'+ar[2]+'</span>' : '';
      return '<td class="pcell"><span class="pcell-in">' +
        '<span class="pill '+tn+'"><span class="pill-mark">'+toneMark(tn)+'</span>'+fmtPct(pct)+'</span>' +
        '<span class="move"><span class="trend '+ar[0]+'">'+ar[1]+'</span>'+delta+'</span>' +
      '</span></td>';
    }

    var maxSold = people.reduce(function(m,x){ return Math.max(m, x.sold); }, 0) || 1;

    var rows = people.map(function(x,i){
      var medal = i < 3 ? ' m' + (i+1) : '';
      var barw = Math.round((x.sold / maxSold) * 100);
      return '<tr class="row' + (i === 0 ? ' leader' : '') + (i < 3 ? ' pin' : '') + '" style="--i:' + i + '; --barw:' + barw + '%">' +
        '<td class="rank"><span class="badge' + medal + '">' + (i+1) + '</span></td>' +
        '<td class="nm">' + x.disp + (x.haveAll ? '' : ' <span class="flag" title="A delivery report is missing for this person, so their total may be incomplete.">&#9873;</span>') + '</td>' +
        '<td class="sold"><span class="bar"></span><span class="soldnum" data-to="' + x.sold + '">0</span>' +
          soldMove(x.sold, x.prevSold) +
        '</td>' +
        cell(x.internetPct, x.prev.internet, 'internet') +
        cell(x.phonePct,    x.prev.phone,    'phone') +
        cell(x.showroomPct, x.prev.showroom, 'showroom') +
      '</tr>';
    });

    if (!rows.length) rows = ['<tr><td colspan="6" class="empty">No sales associates on the board yet. Give them a position in the tool.</td></tr>'];

    // ---- Bars style: rank, name, units, one huge striped bar sized against the leader ----
    var bars = DISP.style === 'bars';
    // bars view now carries the same +/- movement as the classic board; the pill
    // is narrower to leave room for the arrow beside it.
    function cell2(pct, ch, prevVal){
      if (pct == null) return '<td class="pcell2"><span class="pcell-in"><span class="pill dim">-</span><span class="move move2"></span></span></td>';
      var tn = tone(pct, ch);
      var ar = arrow(pct, prevVal);
      var delta = ar[2] ? '<span class="delta '+ar[0]+'">'+ar[2]+'</span>' : '';
      return '<td class="pcell2"><span class="pcell-in">' +
        '<span class="pill '+tn+'"><span class="pill-mark">'+toneMark(tn)+'</span>'+fmtPct(pct)+'</span>' +
        '<span class="move move2"><span class="trend '+ar[0]+'">'+ar[1]+'</span>'+delta+'</span>' +
      '</span></td>';
    }
    var rows2 = people.map(function(x,i){
      var medal = i < 3 ? ' m' + (i+1) : '';
      var ratio = x.sold / maxSold;
      // The podium is always green — top three have earned it no matter the spread.
      var t2 = i < 3 ? 'g' : ratio >= 0.75 ? 'g' : ratio >= 0.4 ? 'y' : 'r';
      var barw = Math.max(2, Math.round(ratio * 100));
      return '<tr class="row' + (i === 0 ? ' leader' : '') + (i < 3 ? ' pin' : '') + '" style="--i:' + i + '; --barw:' + barw + '%">' +
        '<td class="rank"><span class="badge' + medal + '">' + (i+1) + '</span></td>' +
        '<td class="nm">' + x.disp + (x.haveAll ? '' : ' <span class="flag" title="A delivery report is missing for this person, so their total may be incomplete.">&#9873;</span>') + '</td>' +
        cell2(x.internetPct, 'internet', x.prev.internet) +
        cell2(x.phonePct, 'phone', x.prev.phone) +
        cell2(x.showroomPct, 'showroom', x.prev.showroom) +
        '<td class="sold2"><span class="soldnum" data-to="' + x.sold + '">0</span>' + soldMove(x.sold, x.prevSold) + '</td>' +
        '<td class="carcell"><div class="cars ' + t2 + '">' + cars(x.sold, maxSold) + '</div></td>' +
      '</tr>';
    });
    if (!rows2.length) rows2 = ['<tr><td colspan="7" class="empty">No sales associates on the board yet. Give them a position in the tool.</td></tr>'];

    /* The top three come out of the scroll container and sit in their own table
       above it, so they stay on screen for the whole pass. */
    var PIN = 3;
    var pin  = function(a){ return a.slice(0, PIN).join(''); };
    var rest = function(a){ return a.length > PIN ? a.slice(PIN).join('') : ''; };

    // ticker items: leader + best of each channel, plus the streaks passed from the tool
    var tickerItems = [];
    if (people.length && people[0].sold > 0) tickerItems.push('&#128081; ' + people[0].name + ' leads with ' + people[0].sold + ' units');
    ['internetPct','phonePct','showroomPct'].forEach(function(k){
      var best = null;
      people.forEach(function(x){ if (x[k] != null && (!best || x[k] > best[k])) best = x; });
      if (best && best[k] > 0) {
        var lbl = k === 'internetPct' ? 'Top Internet' : k === 'phonePct' ? 'Top Phone' : 'Top Showroom';
        tickerItems.push('<span class="tk-cap">' + lbl + ':</span>' + best.name + ' ' + fmtPct(best[k]));
      }
    });
    (CFG.ticker || []).forEach(function(t){ tickerItems.push(t); });
    var tickerHtml = tickerItems.map(function(t){ return '<span class="ticker-item">' + t + '</span>'; }).join('');
    var tickDur = Math.max(25, tickerItems.length * 7);

    root.innerHTML =
      '<div class="head"><div class="head-l"><div class="head-logo">'+(CFG.icon?'<img src="'+CFG.icon+'"/>':'')+'</div>'+
      '<div><div class="head-title">'+CFG.storeName+'</div><div class="head-sub">Delivery Leaderboard</div></div></div>'+
      '<div class="head-r">'+
        '<div class="total"><div class="total-num"><span class="totnum" data-to="'+totalSold+'">0</span>'+(grandFlag?' <span class="flag">&#9873;</span>':'')+'</div><div class="total-cap">Units Delivered</div></div>'+
        '<div class="clock"><div class="clock-time" id="clk"></div><div class="clock-date" id="dat"><span class="live"></span><span id="datt"></span></div></div>'+
      '</div></div>'+
      '<div class="panel" style="--rowfs:'+rowFs+'vh; --rowpad:'+rowPad+'vh;">'+
        /* The header and the top three, fixed. Then the rest, scrolling. Both
           tables carry the same classes and table-layout:fixed, which is what
           keeps the columns aligned across the join. */
        (bars
          ? '<table class="lb2 podium-tbl">'+
              '<thead><tr>'+
                '<th class="rank">#</th>'+
                '<th class="nm">Associate</th>'+
                '<th class="pcell2" style="text-align:center">Internet %</th>'+
                '<th class="pcell2" style="text-align:center">Phone %</th>'+
                '<th class="pcell2" style="text-align:center">Showroom %</th>'+
                '<th class="sold2" style="text-align:center">Delivered</th>'+
                '<th class="carcell" style="text-align:left; padding-left:.6vw">units</th>'+
              '</tr></thead>'+
              '<tbody>'+pin(rows2)+'</tbody>'+
            '</table>'
          : '<table class="lb podium-tbl">'+
              '<thead><tr>'+
                '<th class="rank">#</th>'+
                '<th class="nm">Associate</th>'+
                '<th class="sold">Delivered</th>'+
                '<th class="pcell">Internet %</th>'+
                '<th class="pcell">Phone %</th>'+
                '<th class="pcell">Showroom %</th>'+
              '</tr></thead>'+
              '<tbody>'+pin(rows)+'</tbody>'+
            '</table>')+
        (((bars ? rows2 : rows).length > 3) ? '<div class="podium-edge"></div>' : '')+
        '<div class="scroller" id="scroller">'+
        (bars
          ? '<table class="lb2"><tbody>'+rest(rows2)+'</tbody></table>'
          : '<table class="lb"><tbody>'+rest(rows)+'</tbody></table>')+
        '</div>'+
      '</div>'+
      (bars
        ? '<div class="ticker"><div class="ticker-track" style="--tickdur:'+tickDur+'s">'+tickerHtml+'</div></div>'
        : '<div class="foot">' +
            'Green at: Internet ' + CFG.thresholds.internet.green + '%+ &middot; ' +
            'Phone ' + CFG.thresholds.phone.green + '%+ &middot; ' +
            'Showroom ' + CFG.thresholds.showroom.green + '%+' +
            ' &middot; arrows show the change since the previous report &middot; data refreshes every 15 minutes' +
          '</div>');
    tick();
    countUp();
    trimFill(tightPad, rowPad);
    startScroll();
  }

  /* The padding above is arithmetic against an ASSUMED 80vh of panel; the real
     panel is whatever the header, the footer and the ticker leave behind. When the
     guess overshoots, a list that fits on the screen would start scrolling for the
     sake of white space it never needed — so hand the height back until it fits,
     down to the tight padding a full board uses and no further. */
  function trimFill(tight, pad){
    var sc = document.getElementById('scroller');
    var panel = document.querySelector('.panel');
    if (!sc || !panel || pad <= tight) return;
    var vh = window.innerHeight / 100;
    for (var i = 0; i < 8 && pad > tight; i++) {
      var over = sc.scrollHeight - sc.clientHeight;
      if (over <= 4) return;
      var rows = document.querySelectorAll('.panel tbody tr').length + 1;   // + the header row
      pad = Math.max(tight, pad - (over / (2 * rows)) / vh);
      panel.style.setProperty('--rowpad', pad + 'vh');
    }
  }

  // If the whole team cannot fit at a readable size, the board walks slowly down the
  // list, holds at the bottom, then springs back to the top with a bounce. Nobody at
  // the bottom of the board should be invisible all day.
  var scrollRAF = null;
  var idleRefill = null;   // refill timer for boards small enough not to scroll
  var settleTimer = null;  // the measure-after-layout delay
  var dwellTimer = null;   // hand-over clock for a board too short to scroll
  /* Every render starts a scroll cycle, and a hand-over renders — so without a
     generation stamp each rotation leaves its predecessor's frame loop alive on a
     detached element, still counting down to a hand-over of its own. Two boards
     become four clocks, then eight, and the room sees the store change every few
     seconds. A cycle checks its stamp before it does anything; only the newest
     one is still the current cycle. */
  var scrollGen = 0;
  function startScroll(){
    var gen = ++scrollGen;
    if (scrollRAF) { cancelAnimationFrame(scrollRAF); scrollRAF = null; }
    if (settleTimer) { clearTimeout(settleTimer); settleTimer = null; }
    if (dwellTimer) { clearTimeout(dwellTimer); dwellTimer = null; }
    var el = document.getElementById('scroller');
    if (!el) return;

    // let layout settle before measuring
    settleTimer = setTimeout(function(){
      settleTimer = null;
      if (gen !== scrollGen) return;
      var over = el.scrollHeight - el.clientHeight;
      if (over <= 4) {
        // Everyone fits, so there's no scroll cycle to trigger the bar refill.
        // Give a non-scrolling board the same flourish on a gentle idle timer.
        if (idleRefill) clearInterval(idleRefill);
        idleRefill = setInterval(replayBars, 2 * 60 * 1000);
        /* A short list has no cycle to end, so the hand-over needs its own clock —
           otherwise a rotation that reaches a small store stops there for the day. */
        if (rotates()) dwellTimer = setTimeout(function(){
          dwellTimer = null;
          if (gen === scrollGen) nextStore();
        }, Math.max(3000, MIN_STORE_MS - (Date.now() - storeShownAt)));
        return;
      }
      if (idleRefill) { clearInterval(idleRefill); idleRefill = null; }

      var HOLD_TOP = 4000;                   // pause so the leaders get their moment
      var HOLD_BOTTOM = 2500;
      var SPEED = 13;                        // px per second: a slow, readable crawl
      var BLOOP = 950;                       // the spring back to the top

      var phase = 'holdTop', t0 = null, from = 0;

      function bloopEase(p){
        // overshoot slightly then settle: the "bloop"
        var c = 1.70158 * 1.2;
        return 1 + (c + 1) * Math.pow(p - 1, 3) + c * Math.pow(p - 1, 2);
      }

      function frame(ts){
        if (gen !== scrollGen) return;   // a newer cycle owns the board now
        if (t0 === null) t0 = ts;
        var dt = ts - t0;

        if (phase === 'holdTop') {
          el.scrollTop = 0;
          if (dt > HOLD_TOP) { phase = 'down'; t0 = ts; }
        } else if (phase === 'down') {
          var y = (dt / 1000) * SPEED;
          if (y >= over) { el.scrollTop = over; phase = 'holdBottom'; t0 = ts; }
          else el.scrollTop = y;
        } else if (phase === 'holdBottom') {
          if (dt > HOLD_BOTTOM) { phase = 'bloop'; t0 = ts; from = el.scrollTop; }
        } else if (phase === 'bloop') {
          var p = Math.min(1, dt / BLOOP);
          el.scrollTop = Math.max(0, from * (1 - bloopEase(p)));
          if (p >= 1) {
            el.scrollTop = 0; phase = 'holdTop'; t0 = ts; replayBars();
            /* One full pass, then the next store. The hand-over happens here rather
               than on a timer so a screen never changes store mid-scroll — you
               always see a board from its leader to its last name before it moves
               on. The frame loop is left running: the new render calls startScroll
               again, which retires this cycle by stamp, and if the hand-over fails
               there is still a board scrolling rather than a frozen one.

               A pass is the earliest a store may leave, not the moment it must:
               a board with barely more than a screenful scrolls a few pixels and
               springs straight back, and rotating on that is a store every ten
               seconds. It stays until it has had its minute, then leaves at the
               end of the next pass. */
            if (rotates() && Date.now() - storeShownAt >= MIN_STORE_MS) nextStore();
          }
        }
        scrollRAF = requestAnimationFrame(frame);
      }
      scrollRAF = requestAnimationFrame(frame);
    }, 400);
  }

  // When the board springs back to the top, the bars refill from zero as a little
  // reward moment. Only the bars: the numbers alongside them stay put, so the
  // figures on screen never look like they changed when they didn't.
  function replayBars(){
    var fills = document.querySelectorAll('.fill2');
    for (var k = 0; k < fills.length; k++) {
      (function(f){
        f.style.animation = 'none';
        void f.offsetWidth;                 // reflow so the animation actually restarts
        f.style.animation = '';
      })(fills[k]);
    }
  }

  // numbers roll up rather than snapping into place. Runs on every refresh, so a
  // new unit landing on the board actually announces itself.
  function countUp(){
    var els = document.querySelectorAll('[data-to]');
    for (var k = 0; k < els.length; k++) {
      (function(el){
        var to = parseFloat(el.getAttribute('data-to')) || 0;
        var dur = 900, t0 = null;
        function step(ts){
          if (!t0) t0 = ts;
          var p = Math.min(1, (ts - t0) / dur);
          var eased = 1 - Math.pow(1 - p, 3);
          var v = to * eased;
          el.textContent = (to % 1 === 0) ? Math.round(v) : v.toFixed(1);
          if (p < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      })(els[k]);
    }
  }
  function tick(){ var n=new Date();
    var c=document.getElementById('clk'); var d=document.getElementById('dat');
    if(c) c.textContent = n.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    var dt = document.getElementById('datt');
    if(dt) dt.textContent = n.toLocaleDateString([], {weekday:'long', month:'long', day:'numeric'});
    else if(d) d.textContent = n.toLocaleDateString([], {weekday:'long', month:'long', day:'numeric'}); }
  // A refresh that swings wildly from the last one is almost always a bad import
  // or a half-written file, not real. Hold the current board and try again next
  // cycle rather than flashing garbage onto a showroom TV. "Wildly" = the total
  // units moved by more than half, on a board that had real numbers to begin with.
  function tooDifferent(prev, next){
    try {
      if (!prev || !prev.store || !next || !next.store) return false;
      function totalUnits(st){
        var t = 0, r = (st.roster||[]);
        for (var i=0;i<r.length;i++){
          var v = (st.months && st.months[next.ym] && st.months[next.ym].stats) || {};
          var k = norm(r[i].name), o = v[k]; if (!o) continue;
          t += (+o.internetUnits||0)+(+o.phoneUnits||0)+(+o.showroomUnits||0)+(+o.campaignUnits||0);
        }
        return t;
      }
      var a = totalUnits(prev), b = totalUnits(next);
      if (a < 5) return false;                       // nothing meaningful to protect yet
      var drop = (a - b) / a;
      return drop > 0.5;                             // lost more than half: distrust it
    } catch(e){ return false; }
  }

  // Who sold since the last good refresh — drives the congratulations sweep.
  function newlySold(prev, next){
    var out = [];
    try {
      if (!prev || !next) return out;
      function unitsOf(st, name){
        var v = (st.months && st.months[next.ym] && st.months[next.ym].stats) || {};
        var o = v[norm(name)]; if (!o) return 0;
        return (+o.internetUnits||0)+(+o.phoneUnits||0)+(+o.showroomUnits||0)+(+o.campaignUnits||0);
      }
      var roster = (next.roster||[]);
      for (var i=0;i<roster.length;i++){
        var nm = roster[i].name;
        var before = unitsOf(prev, nm), after = unitsOf(next, nm);
        if (after > before + 1e-6) out.push({ name: nm, gained: after - before });
      }
    } catch(e){}
    return out;
  }

  function congratulate(list){
    if (!list.length) return;
    var host = document.createElement('div');
    host.className = 'congrats';
    // one banner per seller, staggered, so a double sale gets its own moment
    host.innerHTML = list.slice(0, 6).map(function(w, i){
      var u = w.gained % 1 ? w.gained.toFixed(1) : w.gained;
      return '<div class="cg-card" style="--d:'+(i*1.5)+'s">'
        + '<div class="cg-burst"></div>'
        + '<div class="cg-ico">&#127881;</div>'
        + '<div class="cg-txt"><b>'+w.name+'</b><span>just delivered '+u+(w.gained==1?' unit':' units')+'</span></div>'
        + '</div>';
    }).join('');
    document.body.appendChild(host);
    // total life = last card's delay + its own 5s, then fade
    var life = (Math.min(list.length,6) * 1.5 + 5) * 1000;
    setTimeout(function(){ host.classList.add('out'); setTimeout(function(){ host.remove(); }, 700); }, life);
  }

  async function loop(){
    var s = await getStore();
    var switched = SWITCHING; SWITCHING = false;
    // Failsafe: a good previous board plus a suspicious new one = keep the old one.
    // Skipped across a hand-over: two different dealerships are supposed to look
    // nothing like each other, and this check would refuse every rotation.
    if (!switched && LAST && !LAST.__err && s && !s.__err && tooDifferent(LAST, s)) {
      var warn = document.getElementById('stale-note');
      if (warn) warn.classList.add('on');
      return;                                        // skip this render entirely
    }
    /* Nobody "just delivered" anything because the screen changed store, so the
       congratulations are held across a hand-over too. */
    var wsold = (!switched && LAST && !LAST.__err && s && !s.__err) ? newlySold(LAST, s) : [];
    if (!LAST) {
      // First load only, so a live adjustment is never stamped over on refresh.
      // The store's published setting is the starting point; anything set on this
      // particular screen wins over it, because somebody stood in front of this
      // television and decided the text was the wrong size for this room.
      var d = (s && !s.__err && s.boardDisplay) ? s.boardDisplay : {};
      var mine = {};
      try { mine = JSON.parse(localStorage.getItem(DKEY) || '{}') || {}; } catch (e) {}
      var pick = function(k, dflt){
        if (mine[k] != null) return mine[k];
        if (d[k] != null) return d[k];
        return dflt;
      };
      DISP.tscale  = pick('tscale', 1);
      DISP.style   = pick('style', DISP.style);
      DISP.bg      = pick('bg', DISP.bg);
      DISP.squeeze = pick('squeeze', 1);
      DISP.pad     = pick('pad', 0);
      DISP.rotate  = pick('rotate', []) || [];
    }
    /* Its own row is the authority on who a store is: the sibling list only
       carries a name, and brand, icon and thresholds all differ per store. */
    SWITCHING = switched;
    renderStore(s);
    var warn = document.getElementById('stale-note');
    if (warn) warn.classList.remove('on');
    if (wsold.length) congratulate(wsold);
  }
  /* ---------- rotating through more than one store ----------
     A screen in a shared hallway shows one store's board, walks it top to bottom,
     then hands over to the next one on the list. The list is a display setting on
     the board it was opened for, so it is set standing at the TV like everything
     else here, and it saves to that store rather than to the screen.

     Every store publishes its whole board row — name, brand, icon, thresholds and
     all — so switching is a matter of pointing at another key and re-reading. No
     new data has to be written for this to work. */
  function rotates(){ return (DISP.rotate || []).length > 0; }
  function rotaList(){ return [HOME.id].concat(DISP.rotate || []); }
  var HOME = { id: CFG.storeId, key: CFG.storeKey, name: CFG.storeName,
               icon: CFG.icon, brand: CFG.brand, thresholds: CFG.thresholds };
  var ROT_I = 0;

  /* How long a store is entitled to the wall before the rota may move on. The
     scroll cycle decides WHEN it leaves — always at the end of a pass, never
     mid-list — and this decides how soon that is allowed to be. */
  var MIN_STORE_MS = 45000;
  var storeShownAt = Date.now();

  /* True for exactly one pass of loop(), because the two guards in it compare the
     board on screen with the one arriving — which is the right thing to do for a
     refresh of the same store and completely wrong across a hand-over. */
  var SWITCHING = false;
  var HANDING = false;      // one hand-over at a time

  /* The convoy.
     The board's own unit mark is a car, so the hand-over is that car making the
     trip: a few of them drive across the screen carrying the next store's name,
     and the board changes underneath while they cover it. No cut, and the room
     can see where the screen is going before it gets there.

     The next store's row is fetched BEFORE anything moves, so the new board is
     already in hand when the convoy reaches the middle. A hand-over that had to
     wait on the network would show an empty screen behind the cars. */
  function driveTo(label, swap){
    var lane = document.createElement('div');
    lane.className = 'handoff';
    /* Lane, size, head start, speed and weight: cars leaving together on one
       timing read as a graphic, cars leaving a beat apart read as traffic — and
       cars crossing at DIFFERENT speeds read as distance. The near lanes are big,
       bright and quick; the far ones are small, dimmer and slower, which is what
       gives the hand-over depth rather than a row of icons sliding past.
       [ lane vh, size vh, delay s, duration s, opacity ] */
    var lanes = [
      [10, 5.2, .10, 3.5, .55],
      [21, 7.0, .02, 3.0, .80],
      [33, 9.2, .16, 2.5, 1],
      [45, 5.8, .30, 3.3, .62],
      [57, 8.2, .08, 2.7, .95],
      [70, 6.2, .22, 3.2, .70],
      [82, 9.6, .00, 2.4, 1],
    ];
    var cars = lanes.map(function(l){
      return '<span class="ho-car" style="--lane:' + l[0] + 'vh; --sz:' + l[1] + 'vh; --dly:' + l[2]
        + 's; --dur:' + l[3] + 's; --fade:' + l[4] + '">' + pix('car', '', 1) + '</span>';
    }).join('');
    lane.innerHTML = '<div class="ho-veil"></div><div class="ho-road"></div>' + cars
      + '<div class="ho-name"><span class="ho-to">Now showing</span>' + label + '</div>';
    document.body.appendChild(lane);

    var root = document.getElementById('root');
    if (root) root.classList.add('drive-out');
    /* Swapped behind the convoy, not before it: the veil is at full strength from
       roughly 480ms to 2.5s of a 3.4s hand-over, and the swap sits in the middle of
       that window with room on both sides. These three numbers are the CSS clock
       read back — if --ho changes, they change with it. */
    setTimeout(function(){
      swap();
      var r = document.getElementById('root');
      if (r) { r.classList.remove('drive-out'); r.classList.add('drive-in');
        setTimeout(function(){ r.classList.remove('drive-in'); }, 1150); }
    }, 1250);
    setTimeout(function(){ lane.remove(); HANDING = false; }, 3600);
  }

  async function nextStore(){
    var list = rotaList();
    if (list.length < 2 || HANDING) return;
    HANDING = true;
    var at = (ROT_I + 1) % list.length;
    var id = list[at];
    var key = 'lpc:board:' + id + ':v1';
    var s = await getStoreByKey(key);
    if (!s || s.__err) {
      /* That store has never been published, or the network blinked. Stay where we
         are and let the next pass try the one after it, rather than driving the
         room to an empty board. */
      HANDING = false; ROT_I = at; storeShownAt = Date.now(); startScroll();
      return;
    }
    ROT_I = at;
    CFG.storeId = id;
    CFG.storeKey = key;
    var known = (CFG.siblings || []).filter(function(x){ return x.id === id; })[0];
    var name = s.storeName || (id === HOME.id ? HOME.name : (known && known.name)) || 'Next store';
    driveTo(name, function(){
      storeShownAt = Date.now();
      SWITCHING = true;
      renderStore(s);
    });
  }

  /* The tail of loop(), reusable: the hand-over already has the row in hand and
     must not fetch it a second time. */
  function renderStore(s){
    var switched = SWITCHING; SWITCHING = false;
    if (switched && s && !s.__err) {
      if (s.storeName) CFG.storeName = s.storeName;
      if (s.icon !== undefined) CFG.icon = s.icon;
      if (s.brand) CFG.brand = s.brand;
      if (s.thresholds) CFG.thresholds = s.thresholds;
    }
    if (s && !s.__err) LAST = s;
    applyDisp();
    render(s);
    wireTuner();
    applyDisp();
  }

  /* ---------- display tuning ---------- */
  // Read whatever was saved for this store, and let the person at the TV change it.
  var DISP = { tscale: 1, squeeze: 1, pad: 0, style: 'classic', bg: 'navy', rotate: [] };
  var DKEY = 'lpc:disp:' + (CFG.storeId || 'board');

  function applyDisp(){
    var b = CFG.brand || {};
    document.body.style.setProperty('--bp', b.primary || '#2A5E9B');
    document.body.style.setProperty('--bd', b.deep || '#1D4674');
    document.body.style.setProperty('--ba', b.accent || '#C1D730');
    document.body.className = DISP.bg === 'store' ? 'bg-store' : '';
    var w = document.getElementById('root');
    if (!w) return;
    w.style.setProperty('--tscale', DISP.tscale);
    w.style.setProperty('--squeeze', DISP.squeeze);
    w.style.setProperty('--pad', DISP.pad + 'vw');
    var t = document.getElementById('v-t'), s = document.getElementById('v-s'), pd = document.getElementById('v-p');
    if (t) t.textContent = Math.round(DISP.tscale * 100) + '%';
    if (s) s.textContent = Math.round(DISP.squeeze * 100) + '%';
    if (pd) pd.textContent = DISP.pad + '%';
  }

  function wireTuner(){
    var gear = document.getElementById('gear');
    var tun = document.getElementById('tuner');
    var st = document.getElementById('s-t'), ss = document.getElementById('s-s'), sp = document.getElementById('s-p');
    if (!gear || !tun) return;

    gear.onclick = function(){ tun.classList.toggle('on'); };
    function paintStyleSeg(){
      var bc = document.getElementById('sty-classic'), bb = document.getElementById('sty-bars');
      if (!bc) return;
      bc.className = DISP.style === 'bars' ? '' : 'on';
      bb.className = DISP.style === 'bars' ? 'on' : '';
    }
    paintStyleSeg();
    document.getElementById('sty-classic').onclick = function(){ DISP.style='classic'; paintStyleSeg(); if (LAST) render(LAST); };
    document.getElementById('sty-bars').onclick = function(){ DISP.style='bars'; paintStyleSeg(); if (LAST) render(LAST); };
    function paintBgSeg(){
      var bn = document.getElementById('bg-navy'), bs = document.getElementById('bg-store');
      if (!bn) return;
      bn.className = DISP.bg === 'store' ? '' : 'on';
      bs.className = DISP.bg === 'store' ? 'on' : '';
    }
    paintBgSeg();
    document.getElementById('bg-navy').onclick = function(){ DISP.bg='navy'; paintBgSeg(); applyDisp(); };
    document.getElementById('bg-store').onclick = function(){ DISP.bg='store'; paintBgSeg(); applyDisp(); };
    document.getElementById('tclose').onclick = function(){ tun.classList.remove('on'); };

    /* The rota list. Rebuilt on every open so a ticked store that has since been
       removed from the group does not linger as a dead row. */
    var rl = document.getElementById('rot-list');
    if (rl) {
      var sibs = CFG.siblings || [];
      if (!sibs.length) rl.innerHTML = '<div class="none">This is the only store on this account.</div>';
      else {
        DISP.rotate = (DISP.rotate || []).filter(function(id){
          return sibs.some(function(x){ return x.id === id; }); });
        rl.innerHTML = sibs.map(function(x){
          var on = (DISP.rotate || []).indexOf(x.id) >= 0;
          return '<button data-rot="' + x.id + '" class="' + (on ? 'on' : '') + '">'
            + '<span class="tick">' + (on ? '&#10003;' : '') + '</span>'
            + '<span>' + x.name + '</span></button>';
        }).join('');
        rl.querySelectorAll('[data-rot]').forEach(function(b){
          b.onclick = function(){
            var id = b.getAttribute('data-rot');
            var at = (DISP.rotate || []).indexOf(id);
            if (at >= 0) DISP.rotate.splice(at, 1); else (DISP.rotate = DISP.rotate || []).push(id);
            /* Back to the home board whenever the list changes, so what is on
               screen always matches what is ticked. */
            ROT_I = 0;
            if (CFG.storeId !== HOME.id) { CFG.storeId = HOME.id; CFG.storeKey = HOME.key;
              CFG.storeName = HOME.name; CFG.icon = HOME.icon; CFG.brand = HOME.brand;
              CFG.thresholds = HOME.thresholds; SWITCHING = true; loop(); }
            wireTuner();
          };
        });
      }
    }

    st.value = Math.round(DISP.tscale * 100);
    ss.value = Math.round(DISP.squeeze * 100);
    sp.value = DISP.pad;

    // text size changes the row maths, so re-render; the others are pure CSS
    st.oninput = function(){ DISP.tscale = st.value / 100; applyDisp(); if (LAST) render(LAST); };
    ss.oninput = function(){ DISP.squeeze = ss.value / 100; applyDisp(); };
    sp.oninput = function(){ DISP.pad = parseFloat(sp.value); applyDisp(); };

    document.getElementById('treset').onclick = function(){
      /* Reset is for the look of the board. The rota is what this screen is FOR,
         so it survives — losing it to a stray tap on Reset would be baffling. */
      DISP = { tscale: 1, squeeze: 1, pad: 0, style: DISP.style, bg: DISP.bg, rotate: DISP.rotate || [] };
      st.value = 100; ss.value = 100; sp.value = 0;
      applyDisp(); if (LAST) render(LAST);
    };

    document.getElementById('tsave').onclick = async function(){
      var msg = document.getElementById('tmsg');
      try {
        // Always keep it on the screen itself first, so a reboot, a nightly
        // reload or a new build cannot undo what someone set by hand.
        var kept = false;
        try { localStorage.setItem(DKEY, JSON.stringify(DISP)); kept = true; } catch (e) {}
        var op = window.opener || (window.parent !== window ? window.parent : null);
        if (op && op.__lpcSaveBoardDisplay) {
          /* HOME.id, not CFG.storeId: the tuner can be opened while the screen is
             part-way round its rota, and CFG.storeId is whichever store is on the
             wall at that moment. These settings belong to the board this screen
             was opened for. */
          var ok = await op.__lpcSaveBoardDisplay(HOME.id, DISP);
          msg.textContent = ok ? 'Saved for this store, on every screen.' : (kept ? 'Saved on this screen only.' : 'Could not save.');
        } else {
          msg.textContent = kept ? 'Saved on this screen. Save from the tool to set it everywhere.' : 'Could not save.';
        }
      } catch (e) { msg.textContent = 'Could not save.'; }
      setTimeout(function(){ msg.textContent = ''; }, 4000);
    };
  }

  var LAST = null;   // last store payload, so a text-size change can re-render

  // Data is pulled every 15 minutes. Hitting the database every 30 seconds all day
  // was pointless: the reports only change when a manager uploads one.
  // The clock is separate and ticks every 10 seconds, so the minute on screen is
  // always right regardless of when the data last refreshed.
  loop();
  setInterval(loop, 15 * 60 * 1000);
  setInterval(tick, 10000);
</script></body></html>`;
}

/* ---------------- Cinematic loading sequence ----------------
   Plays on the first sign-in of each calendar day. The Lead Performance logo whooshes
   in, fills the back, and morphs into a decorative version of The Board (no real data),
   then hands off into the Performance page. ~10 seconds, then onComplete fires. A Skip
   affordance appears only after someone has seen it a few times. */
/* ---------------- Sign-in handover, part two ----------------
   The mark left the login card growing. This picks it up at exactly that size,
   blooms it into the page, and assembles the shape of the manager's own dashboard
   underneath it, so the last frame of the animation IS the first frame of the app.
   No stand-in table of invented names, no full-screen blue: the aurora and the card
   shapes are the ones already on the page. */
/* Each manufacturer has a house typeface. These are the closest widely available
   matches, loaded on demand rather than shipped with the page, so a store's name
   is set in something that looks like its own brand rather than ours. */
const BRAND_FONTS = [
  [/honda/i,               "Roboto",         "wght@700"],
  [/acura/i,               "Roboto",         "wght@700"],
  [/mazda/i,               "Jost",           "wght@600"],
  [/audi/i,                "Barlow",         "wght@700"],
  [/hyundai|genesis/i,     "Titillium+Web",  "wght@700"],
  [/ford|lincoln/i,        "Archivo",        "wght@700"],
  [/mitsubishi/i,          "Inter",          "wght@700"],
  [/vinfast/i,             "Poppins",        "wght@600"],
  [/kia/i,                 "Rubik",          "wght@700"],
  [/toyota|lexus/i,        "Nunito+Sans",    "wght@700"],
  [/chevrolet|gmc|buick/i, "Overpass",       "wght@700"],
];
function inkOn(bg) {
  const hex = String(bg || "").trim().replace("#", "");
  const full = hex.length === 3 ? hex.split("").map((c) => c + c).join("") : hex;
  if (full.length !== 6) return "#FFFFFF";
  const lin = (v) => { const s = parseInt(v, 16) / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
  const L = 0.2126 * lin(full.slice(0, 2)) + 0.7152 * lin(full.slice(2, 4)) + 0.0722 * lin(full.slice(4, 6));
  // 0.45 sits between the contrast ratios for black and white against mid tones
  return L > 0.45 ? "#101820" : "#FFFFFF";
}

/* A translucent plate on the store's own colour, and the ink that reads on it.

   The chip belongs to the hero, and everything else on the hero is white, so
   white is what it should be too — a lone black label on a wall of white text
   reads as a mistake even when it is legible.

   The first version was white on a 22%-WHITE plate, which lightens the plate
   toward the text and measured 2.36:1 on the Driver's Mart teal. The second
   picked whichever direction scored highest, which took that store to black.
   Both were wrong in the same way: the plate is the thing to move, not the ink.
   Darkening it 36% carries white on every brand in play — Driver's Mart 6.3,
   Honda 10.7, Chevrolet 12.9, Mazda 13.4 — and only a genuinely pale brand
   (2.9) or a yellow one (3.9) fails, which is where the ink does flip. */
function chipOn(bg) {
  const raw = String(bg || "").trim().replace("#", "");
  // #0A9 and #00AA99 are the same colour; only one of them survives a /../ split
  const full = /^[0-9a-f]{3}$/i.test(raw) ? raw.split("").map((c) => c + c).join("") : raw;
  const parts = /^[0-9a-f]{6}$/i.test(full) ? full.match(/../g) : null;
  if (!parts) return { ink: "#FFFFFF", plate: "rgba(255,255,255,.22)" };
  const rgb = parts.slice(0, 3).map((v) => parseInt(v, 16));
  const hx = (a) => "#" + a.map((v) => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, "0")).join("");
  const over = (t, a) => hx(rgb.map((v, i) => v + (t[i] - v) * a));
  const lum = (h) => {
    const c = h.replace("#", "").match(/../g).map((v) => parseInt(v, 16) / 255);
    const g = (s) => (s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4));
    return 0.2126 * g(c[0]) + 0.7152 * g(c[1]) + 0.0722 * g(c[2]);
  };
  const ratio = (a, b) => {
    const x = lum(a), y = lum(b);
    return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
  };
  const dark = over([0, 0, 0], 0.36);
  if (ratio("#FFFFFF", dark) >= 4.5) return { ink: "#FFFFFF", plate: dark };
  return { ink: "#101820", plate: over([255, 255, 255], 0.62) };
}

function brandFontFor(name) {
  const hit = BRAND_FONTS.find(([re]) => re.test(String(name || "")));
  return hit ? { family: hit[1].replace(/\+/g, " "), spec: hit[1], axis: hit[2] } : null;
}

/* The cinematic that used to live here is gone: SageArrival replaced it. It
   drew a stand-in dashboard of invented shapes for three and a half seconds,
   which the new one does not need because it hands over to the real one. */

/* ---------------- Board launcher (after sign-in, role-aware) ---------------- */
function BoardLauncher({ config, session, onLaunch, onBack }) {
  const isAdmin = session.role === "admin";
  const stores = isAdmin ? config.stores : config.stores.filter((s) => (session.stores || []).includes(s.id));
  const single = stores.length === 1;
  /* It used to open the board by itself the moment a manager landed here. A
     window opened without a click is what a pop-up blocker exists to stop, so on
     a default Chrome or Safari it was blocked every time, and all anybody got
     was a message box behind the blocker's little icon. It opens on a press now,
     which is a press nobody minds and a window no browser argues with. */
  const [blocked, setBlocked] = useState(false);
  const launch = async (id) => {
    const ok = await onLaunch(id);
    setBlocked(ok === false);
  };

  if (stores.length === 0) {
    return <div className="empty">No store is assigned to your account yet, so there's no board to show. Ask your group admin to grant you store access.</div>;
  }

  if (single) {
    const s = stores[0];
    const b = s.brand || DEFAULT_BRAND;
    return (
      <div className="board-launch">
        <div className="bl-one" style={{ "--sp": b.primary, "--sd": b.deep }}>
          <div className="bl-logo">{s.icon ? <img src={s.icon} alt="" /> : <Logo size={54} animated />}</div>
          <h2 className="bl-title">{s.name}</h2>
          <p className="bl-onesub">The Board opens in its own window, sized for a TV or a big screen. It
            refreshes on its own every 30 seconds and shows the five: {FIVE.map((f) => f.label.toLowerCase()).join(", ")}.</p>
          <div className="bl-tile-acts">
            <button className="bl-go" onClick={() => launch(s.id)}>Open the board ↗</button>
            <CastLink storeId={s.id} config={config} compact />
          </div>
          {blocked && <p className="bl-blocked">Your browser stopped that window from opening. Allow pop-ups
            for this site and press again, or copy the TV link and open it yourself.</p>}
        </div>
        <button className="btn-link" onClick={onBack}>← Back to start</button>
      </div>
    );
  }

  /* Admin and Centralized BDC pick which store's board to throw on the screen.
     Every tile is in its own dealership's colours, and carries opening it, the TV
     link and publishing together: they are three things you do to one store, and
     they were split between a grid and a row of links underneath it. */
  return (
    <div className="board-launch">
      <div className="s2-hero bl-hero">
        <i className="s2-noise" aria-hidden="true" />
        <div className="s2-tube">
        <div className="s2-head">
          <div className="s2-ava"><PixIcon glyph="chart" size={24} /></div>
          <div className="s2-idtx">
            <div className="s2-greet">
              Choose a store · it opens in its own window, sized for a TV, and refreshes every 30 seconds
            </div>
            <h2 className="s2-store">The Board</h2>
          </div>
          <div className="s2-chips">
            <span className="fh-chip">{stores.length} {stores.length === 1 ? "store" : "stores"}</span>
          </div>
        </div>
        <div className="bl-herobody">
          <div className="bl-hstat"><span className="s2-cap">Showing</span>
            <span className="bl-hbig">The five</span>
            <span className="bl-hsub">{FIVE.map((f) => f.label.toLowerCase()).join(", ")}</span></div>
          <div className="bl-hstat"><span className="s2-cap">Managers</span>
            <span className="bl-hbig">No picker</span>
            <span className="bl-hsub">their own store opens straight away</span></div>
        </div>
        </div>
      </div>

      <div className="bl-grid">
        {stores.map((s) => {
          const b = s.brand || DEFAULT_BRAND;
          return (
            <div key={s.id} className="bl-tile" style={{ "--sp": b.primary, "--sd": b.deep }}>
              <span className="bl-tile-logo">{s.icon ? <img src={s.icon} alt="" /> : <span className="bl-tile-ph">{s.name[0]}</span>}</span>
              <span className="bl-tile-name">{s.name}</span>
              <span className="bl-tile-acts">
                <button className="bl-go" onClick={() => launch(s.id)}>Open the board ↗</button>
                <CastLink storeId={s.id} config={config} compact />
              </span>
            </div>
          );
        })}
      </div>
      {blocked && <p className="bl-blocked">Your browser stopped that window from opening. Allow pop-ups for
        this site and press again, or copy the TV link and open it yourself.</p>}
      <button className="btn-link" onClick={onBack}>← Back to start</button>
    </div>
  );
}

// The address a TV is pointed at. Copy it once, set it as the screen's start page,
// and nobody has to touch it again.
function CastLink({ storeId, label, config, compact }) {
  const [said, setSaid] = useState(false);
  const [pub, setPub] = useState(null);   // null | "working" | {ok, err}
  const url = boardTvUrl(storeId);
  const publish = async () => {
    setPub("working");
    const r = await publishBoardNow(config, storeId);
    setPub(r);
    if (r.ok) setTimeout(() => setPub(null), 4000);
  };
  return (
    <span className={"cast-wrap" + (compact ? " cast-compact" : "")}>
      <button className={compact ? "bl-tvb" : "btn-link cast-link"} title={url}
        onClick={() => {
          navigator.clipboard.writeText(url).then(() => { setSaid(true); setTimeout(() => setSaid(false), 3000); },
            () => window.prompt("Copy this address into the TV's browser:", url));
        }}>
        {said ? "Copied" : (label ? "Copy TV link for " + label : compact ? "Copy TV link" : "Copy the TV link")}
      </button>
      <button className={compact ? "bl-tvb" : "btn-link cast-link"} onClick={publish} disabled={pub === "working"}>
        {pub === "working" ? "Publishing..." : (pub && pub.ok ? "Published" : compact ? "Publish" : "Publish to TVs")}
      </button>
      {pub && pub !== "working" && !pub.ok && (
        <span className="cast-err">Could not publish: {pub.err}. The TVs will keep showing what they already have. Use the Help button to report this.</span>
      )}
    </span>
  );
}

// The only fields the board draws. Anything not on this list never leaves the
// private store row, which is the whole point of publishing a separate one.

function buildBoardPayload(config, storeId, sdata) {
  const store = (config?.stores || []).find((s) => s.id === storeId);
  const onBoard = new Set((config?.roles || []).filter((r) => r.onBoard !== false).map((r) => r.id));
  const key = ym();
  const src = ((sdata && sdata.months) || {})[key]?.stats || {};
  const stats = {}; const roster = []; const ticker = [];
  const std = { ...DEFAULT_ACTIVITY_STANDARDS, ...(store?.activityStandards || {}) };
  const gone = departedNames(sdata);
  for (const a of (sdata && sdata.roster) || []) {
    if (!a.roleId || !onBoard.has(a.roleId)) continue;
    if (gone.has(norm(a.name))) continue;
    /* The id rides along for the phone: an account is linked to a roster id, and
       on a morning the floor is not open yet the board row is the only public
       place that can turn that id back into a name. */
    roster.push({ id: a.id, name: a.name, roleId: a.roleId });
    const s = src[norm(a.name)];
    if (s) {
      const keep = {};
      for (const f of BOARD_STAT_FIELDS) if (s[f] !== undefined) keep[f] = s[f];
      stats[norm(a.name)] = keep;
    }
    try {
      const { dir, len } = currentStreak(sdata, a, std);
      if (dir === "up" && len >= 3) ticker.push(`&#128293; ${a.name} is on a ${len}-day streak`);
    } catch (e) {}
  }
  const extras = phoneExtras(sdata, roster.map((r) => ((sdata && sdata.roster) || []).find((a) => a.name === r.name) || r), key, norm);
  return {
    storeId,
    storeName: store?.name || "Store",
    icon: store?.icon || null,
    goals: extras.goals,
    off: extras.off,
    brand: store?.brand || DEFAULT_BRAND,
    thresholds: normThresholds(store?.thresholds),
    roles: (config?.roles || []).filter((r) => r.onBoard !== false).map((r) => ({ id: r.id })),
    boardDisplay: (sdata && sdata.boardDisplay) || null,
    ym: key,
    ticker,
    roster,
    departed: [...gone],
    months: { [key]: { stats } },
    updatedAt: new Date().toISOString(),
  };
}

// Publish the TV row. Called after every save so a casted screen never goes stale.
// A failure here must never fail the save, but it must not vanish either: a board
// row that never got written looks exactly like a board that was never opened.
async function publishBoard(config, storeId, sdata) {
  try {
    // Today's floor figures, in the one place a signed-out phone can read them.
    const t = today();
    const rows = ((sdata && sdata.activity) || {})[t];
    const store = (config?.stores || []).find((s2) => s2.id === storeId);
    const bar = (store?.activityStandards || {}).rockEdStars ?? DEFAULT_ACTIVITY_STANDARDS.rockEdStars;
    if (rows) { try { await saveShared(floorStatsKey(storeId, t), slimFloorStats(withRocked(sdata, t, rows, bar))); } catch (e) {} }
    const ok = await saveShared(boardKey(storeId), buildBoardPayload(config, storeId, sdata));
    if (!ok) console.error("board publish failed", boardKey(storeId), lastSaveError);
    return { ok, err: ok ? null : (lastSaveError || "unknown") };
  } catch (e) {
    console.error("board publish failed", boardKey(storeId), e);
    return { ok: false, err: (e && (e.message || e.code)) || String(e) };
  }
}

// Publish on demand, loading the store's own data first. Used by the Publish button
// so a TV can be brought to life without opening the board window at all.
async function publishBoardNow(config, storeId) {
  let sdata = null;
  try { sdata = await loadStore(storeId, null, true); }
  catch (e) { return { ok: false, err: "Could not read this store's data: " + ((e && (e.message || e.code)) || String(e)) }; }
  return publishBoard(config, storeId, sdata || {});
}

// Opens a standalone, auto-refreshing leaderboard in a new window sized for a TV.
async function openLeaderboard(config, storeId) {
  const w = window.open("", "lpc_leaderboard_" + storeId, "width=1600,height=900");
  /* Said on the page rather than in a message box: a blocked pop-up usually
     comes with the browser's own alert suppressed too, so the box nobody sees
     is the only thing that ever explained it. */
  if (!w) return false;
  // Publish the sanitized TV row first, so this window and any casted screen are
  // reading the exact same thing.
  let sdata = null;
  try { sdata = await loadStore(storeId); } catch (e) {}
  const board = buildBoardPayload(config, storeId, sdata || {});
  const pub = await publishBoard(config, storeId, sdata || {});
  if (!pub.ok) {
    alert("This board opened here, but it could NOT be published for the TVs.\n\nWhat the database said:\n" + pub.err
      + "\n\nA casted screen will keep showing whatever it already had. This is almost always a write-permission rule on the board keys. Use the Help button to report it with these details.");
  }
  const payload = {
    ...board,
    storeKey: boardKey(storeId),
    /* The other stores this screen could hand over to. On the window payload
       rather than in the published row: the row goes in the database and every
       board would then carry a copy of the group's store list for no reason. */
    siblings: (config?.stores || [])
      .filter((x) => x.id !== storeId)
      .map((x) => ({ id: x.id, name: x.name })),
    db: { url: SUPABASE_URL, anonKey: SUPABASE_ANON_KEY },
    tokens: null,
  };
  w.document.open();
  w.document.write(LEADERBOARD_HTML(payload));
  w.document.close();
  return true;
}

/* ---------------- Queue boards on a wall ----------------
   A screen showing who is up, in order, for one queue. Pointed at
   ?qboard={storeId}&k=line|online|floor and left alone: it reads the queue row,
   which is already readable without an account, refreshes every five seconds like
   the floor phones do, and reloads itself when a new build ships.

   Deliberately not the leaderboard. That board is about the month; this is about
   the next ten minutes, so it says one thing large: who is next. */
/* The three queues, in one table. All three answer the same question — who is
   next — over a different channel, and each carries its own colour and glyph
   everywhere it appears: this board, and the picker in the bottom bar. It was
   written out twice before, which is how a colour drifts. */
const QUEUE_TOOLS = [
  { id: "floor",  label: "Live Floor", glyph: "door",  accent: "#10B981", count: "on the floor" },
  { id: "line",   label: "The Line",   glyph: "phone", accent: "#5566F0", count: "in line" },
  { id: "online", label: "Online",     glyph: "globe", accent: "#8B5CF6", count: "in the queue" },
];
const queueTool = (id) => QUEUE_TOOLS.find((q) => q.id === id) || QUEUE_TOOLS[1];

function QueueBoard({ storeId, kind }) {
  const [row, setRow] = useState(null);
  const [board, setBoard] = useState(null);   // the published board row: names, month units
  const [err, setErr] = useState(false);
  useBuildWatchdog();

  const variant = queueTool(kind);

  useEffect(() => {
    let dead = false;
    const pull = async () => {
      try {
        const d = kind === "floor"
          ? await loadFloorRow(storeId, today())
          : await loadQueueRow(storeId, today(), kind === "online" ? "online" : "line");
        if (dead) return;
        if (d === undefined) { setErr(true); return; }   // read failed: hold what is shown
        setRow(d || null); setErr(false);
      } catch (e) { if (!dead) setErr(true); }
    };
    pull();

    /* A five second poll is for a phone in a pocket and wrong for a wall: a
       manager assigns somebody and the screen argues with the room for a few
       seconds. Postgres pushes the change instead, so the board turns over as the
       click happens. The poll stays underneath as a safety net, slowed right down,
       because a dropped socket must not leave a screen frozen for the afternoon. */
    const rowId = kind === "floor"
      ? floorRowId(storeId, today())
      : queueRowId(storeId, today(), kind === "online" ? "online" : "line");
    const table = kind === "floor" ? FLOOR_TABLE : QUEUE_TABLE;
    let channel = null;
    if (supabase) {
      try {
        channel = supabase.channel(`qb:${table}:${rowId}`)
          .on("postgres_changes",
            { event: "*", schema: "public", table, filter: `id=eq.${rowId}` },
            (payload) => {
              const v = payload && payload.new && payload.new.data;
              if (!dead && v) { setRow(v); setErr(false); }
            })
          .subscribe();
      } catch (e) { /* no realtime: the poll below still carries it */ }
    }
    const t = setInterval(pull, channel ? 20000 : 5000);
    const nightly = setInterval(() => {
      const d = new Date();
      if (d.getHours() === 4 && d.getMinutes() < 6) window.location.reload();
    }, 5 * 60 * 1000);
    return () => {
      dead = true; clearInterval(t); clearInterval(nightly);
      if (channel) { try { supabase.removeChannel(channel); } catch (e) {} }
    };
  }, [storeId, kind]);

  // The published board row carries this month's units, which is what decides the
  // top three. Read once a minute: it moves slowly and the queue does not.
  useEffect(() => {
    let dead = false;
    const pull = () => loadShared(boardKey(storeId), null).then((b) => { if (!dead && b) setBoard(b); }).catch(() => {});
    pull();
    const t = setInterval(pull, 60000);
    return () => { dead = true; clearInterval(t); };
  }, [storeId]);

  /* The store's top three for units this month. Ranked here rather than published,
     so the board and the leaderboard can never disagree about who is ahead. */
  const rank = useMemo(() => {
    const stats = ((board && board.months) || {})[board && board.ym] || null;
    if (!stats || !stats.stats) return {};
    const rows = Object.entries(stats.stats).map(([k, s]) => ({
      k, units: (s.internetUnits || 0) + (s.phoneUnits || 0) + (s.showroomUnits || 0) + (s.campaignUnits || 0),
    })).filter((r) => r.units > 0).sort((a, b) => b.units - a.units);
    const out = {};
    rows.slice(0, 3).forEach((r, i) => { out[r.k] = i + 1; });
    return out;
  }, [board]);

  const roster = (row && row.roster) || [];
  const entry = (id) => roster.find((r) => r.id === id) || null;
  const nameOf = (id) => (entry(id) || {}).label || "";
  const fullOf = (id) => (entry(id) || {}).name || (entry(id) || {}).label || "";
  const rankOf = (id) => rank[norm(fullOf(id))] || 0;
  const langsOf = (id) => ((entry(id) || {}).langs || []);

  const line = (row && row.line) || [];
  const waiting = line.filter((p) => p.status === "waiting" && !isTestId(p.id));
  const busy = line.filter((p) => p.status !== "waiting" && !isTestId(p.id));
  const next = waiting[0] || null;

  /* The way people actually get in the queue.
     A printed code goes stale the moment somebody reprints it, and on a wall there
     is a screen already showing the queue, so the code belongs there. It surfaces
     on its own every couple of minutes, holds long enough to be scanned from a few
     feet away, and goes again. Nobody has to be asked to put it up. */
  const signInUrl = (row && row.token)
    ? (kind === "floor"
        ? `${window.location.origin}${window.location.pathname}?f=${encodeURIComponent(storeId)}&d=${today()}&t=${encodeURIComponent(row.token)}`
        : queueSignInUrl(storeId, today(), row.token, kind === "online" ? "o" : "q"))
    : "";
  const [scan, setScan] = useState(false);
  const [pinned, setPinned] = useState(false);
  useEffect(() => {
    if (!signInUrl || pinned) return;
    let t1 = null, t2 = null;
    const cycle = () => {
      setScan(true);
      t2 = setTimeout(() => setScan(false), 22000);   // long enough to walk over and scan
    };
    t1 = setInterval(cycle, 150000);                   // every two and a half minutes
    return () => { clearInterval(t1); clearTimeout(t2); };
  }, [signInUrl, pinned]);
  const pod = waiting.slice(1, 4);
  const rest = waiting.slice(4, 9);

  const warmOf = (id) => { const r = rankOf(id); return r ? ` qb-warm qb-p${r}` : ""; };
  /* Languages, then earned strengths, then skills. A strength is set apart because
     it was earned rather than typed: it is the one thing on this wall that nobody
     can give themselves. */
  const tagPills = (id) => {
    const e = entry(id) || {};
    const l = e.langs || [], st = e.strengths || [], sk = e.skills || [];
    if (!l.length && !st.length && !sk.length) return null;
    const skillLabel = (t) => (DEFAULT_TAGS.find((x) => x.id === t) || {}).label || t;
    const strengthLabel = (t) => (STRENGTH_METRICS.find((x) => x.id === t) || {}).label || t;
    return (
      <span className="qb-langs">
        {l.map((x) => <span key={"l" + x} className="qb-lang" title={langName(x)}>{x}</span>)}
        {st.map((x) => <span key={"s" + x} className="qb-lang qb-strength">{strengthLabel(x)}</span>)}
        {sk.map((x) => <span key={"k" + x} className="qb-lang qb-skill">{skillLabel(x)}</span>)}
      </span>
    );
  };
  const avatar = (id, cls) => (
    <span className={"qb-av " + cls} style={{ background: `hsl(${hueFromName(fullOf(id))} 62% 62%)` }}>{initialsOf(fullOf(id))}</span>
  );
  const stepH = [150, 118, 92];

  return (
    <div className="qb" style={{ "--a": variant.accent }}>
      <div className="qb-hd">
        <span className="qb-tag"><span className="qb-live" /><PixIcon glyph={variant.glyph} size={22} /> {variant.label}</span>
        <span className="qb-store">{(row && row.storeName) || ""}</span>
        <span className="qb-hd-right">
          <span className="qb-pill"><b>{waiting.length}</b> {variant.count}</span>
          {next && <span className="qb-pill"><b>{qWaitLabel(qMinsSince(next.joinedAt))}</b> longest</span>}
        </span>
      </div>

      {err && <div className="qb-empty">Cannot reach the queue. This screen keeps trying on its own.</div>}
      {!err && !next && <div className="qb-empty">Nobody is up yet.</div>}

      {next && (
        <>
          <div className="qb-top">
            <div className={"qb-hero" + warmOf(next.id)}>
              <div className="qb-cap">Next up</div>
              <div className="qb-name">{nameOf(next.id)}</div>
              <div className="qb-sub">{qWaitLabel(qMinsSince(next.joinedAt))} waiting {tagPills(next.id)}</div>
            </div>
            <div className="qb-pod">
              {pod.map((p, i) => (
                <div key={p.id} className={"qb-col" + warmOf(p.id)}>
                  {avatar(p.id, "qb-av-md")}
                  <div className="qb-cnm">{nameOf(p.id)}</div>
                  <div className="qb-cw">{qWaitLabel(qMinsSince(p.joinedAt))}</div>
                  {tagPills(p.id)}
                  <div className="qb-step" style={{ height: stepH[i] }}>{i + 2}</div>
                </div>
              ))}
            </div>
          </div>

          <div className="qb-strip">
            {rest.map((p, i) => (
              <div key={p.id} className={"qb-card" + warmOf(p.id)}>
                <div className="qb-chead">
                  {avatar(p.id, "qb-av-sm")}
                  <span className="qb-pos">{i + 5}</span>
                </div>
                <div className="qb-cnm qb-left">{nameOf(p.id)}</div>
                <div className="qb-crow">
                  <span className="qb-cw">{qWaitLabel(qMinsSince(p.joinedAt))}</span>
                  {tagPills(p.id)}
                </div>
              </div>
            ))}
            {waiting.length > 9 && <div className="qb-card qb-more">+{waiting.length - 9} more</div>}
          </div>
        </>
      )}

      {/* Tap or click the screen to hold the code up, tap again to release it. Useful
          at a shift change, when everybody needs it at once. */}
      {signInUrl && (
        <button className="qb-scan-toggle" onClick={() => { setPinned((v) => !v); setScan(!pinned); }}>
          {pinned ? "Hide the code" : "Show the code"}
        </button>
      )}

      {signInUrl && (scan || pinned) && (
        <div className={"qb-scan" + (pinned ? " qb-scan-pin" : "")}>
          <div className="qb-scan-card">
            <div className="qb-scan-cap">{variant.label}</div>
            <div className="qb-scan-title">Scan to check in</div>
            <div className="qb-scan-qr"><QueueQR url={signInUrl} cell={9} /></div>
            <div className="qb-scan-sub">Point a phone camera at the code</div>
          </div>
        </div>
      )}

      {busy.length > 0 && (
        <div className="qb-busy">
          <span className="qb-busy-lbl">Not available</span>
          {busy.slice(0, 8).map((p) => (
            <span key={p.id} className="qb-chip">
              <PixIcon glyph={p.status === "customer" ? "car" : p.status === "lunch" ? "lunch" : "away"} size={15} />
              {nameOf(p.id)}<i>{p.status === "customer" ? "with a customer" : p.status === "lunch" ? "lunch" : "away"}</i>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------------- Casted board (kiosk) ----------------
   A TV is pointed at ?board=<storeId> and left alone. Because this is a real page
   and not a written-into popup, a reboot recovers on its own and a reload picks up
   whatever code is currently deployed. Nobody signs in: it reads the published
   board row with the anon key and nothing else. */

// Reload when a new build ships, so a screen that has been up for weeks is never
// running last month's layout. Vercel fingerprints its asset filenames, so a plain
// comparison against the served page is enough, no version endpoint needed.
function useBuildWatchdog() {
  useEffect(() => {
    const names = (nodes) => nodes.map((n) => String(n).split("/").pop()).filter(Boolean);
    const mine = names([...document.querySelectorAll('script[src],link[rel="stylesheet"]')]
      .map((n) => n.getAttribute("src") || n.getAttribute("href")).filter(Boolean));
    let dead = false;
    const check = async () => {
      if (dead || !mine.length) return;
      try {
        const res = await fetch(window.location.pathname + "?_build=" + Date.now(), { cache: "no-store" });
        if (!res.ok) return;
        const doc = new DOMParser().parseFromString(await res.text(), "text/html");
        const theirs = names([...doc.querySelectorAll('script[src],link[rel="stylesheet"]')]
          .map((n) => n.getAttribute("src") || n.getAttribute("href")).filter(Boolean));
        if (theirs.length && theirs.some((n) => !mine.includes(n)) && !dead) window.location.reload();
      } catch (e) { /* offline: try again next time */ }
    };
    const build = setInterval(check, 10 * 60 * 1000);
    // A clean start every night. This is also what rolls the board onto a new month,
    // since the month it draws is fixed when the page loads.
    const nightly = setInterval(() => {
      const d = new Date();
      if (d.getHours() === 4 && d.getMinutes() < 6) window.location.reload();
    }, 5 * 60 * 1000);
    return () => { dead = true; clearInterval(build); clearInterval(nightly); };
  }, []);
}

function BoardScreen({ storeId }) {
  const [html, setHtml] = useState(null);
  const [msg, setMsg] = useState("Loading the board...");
  useBuildWatchdog();
  useEffect(() => {
    let dead = false, done = false;
    const boot = async () => {
      try {
        const row = await loadShared(boardKey(storeId), null, true);
        if (dead) return;
        if (!row) {
          setMsg("Nothing to read for this store yet. Either the board has not been published from the tool, or this screen is not allowed to read it. In the tool, open The Board and use Publish to TVs, which will name the exact problem.");
          return;
        }
        done = true;
        setHtml(LEADERBOARD_HTML({
          ...row,
          storeKey: boardKey(storeId),
          db: { url: SUPABASE_URL, anonKey: SUPABASE_ANON_KEY },
          tokens: null,
        }));
      } catch (e) {
        if (!dead) setMsg("No connection to the database. This screen keeps trying on its own.");
      }
    };
    boot();
    // Only retries until it has something to draw; after that the board refreshes itself.
    const t = setInterval(() => { if (!done) boot(); }, 60 * 1000);
    return () => { dead = true; clearInterval(t); };
  }, [storeId]);

  return (
    <div style={{ position: "fixed", inset: 0, background: "#0B1622", overflow: "hidden" }}>
      {html
        ? <iframe title="The Board" srcDoc={html} style={{ border: 0, width: "100%", height: "100%", display: "block" }} />
        : <div style={{ height: "100%", display: "grid", placeItems: "center", padding: "32px", textAlign: "center",
            color: "#CFE0F0", font: "500 20px/1.5 system-ui, -apple-system, sans-serif" }}>{msg}</div>}
    </div>
  );
}

/* The mark in the corner is the only thing that has to be in the top bar, so it
   carries the account rather than spending width on a title nobody reads twice. */
function BrandMenu({ session, isOverseer, isAdmin, onSignOut, onReplayIntro, onHelp }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const away = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", away);
    document.addEventListener("keydown", esc);
    return () => { document.removeEventListener("mousedown", away); document.removeEventListener("keydown", esc); };
  }, [open]);
  const initials = String(session?.name || "?").split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase();
  return (
    <div className="brand" ref={ref}>
      <button className={"brand-btn" + (open ? " on" : "")} onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu" aria-expanded={open} title={session?.name || "Account"}>
        {/* The app-icon form: the mark reversed on its ink plate, which is the one
            place in the app the plate appears at all. */}
        <SageMark plate={SAGE_PLATE} base={SAGE_BASE_REVERSED} cap={SAGE_CAP_REVERSED}
          size={36} radius={30} pad={16} />
      </button>
      {open && (
        <div className="brand-menu" role="menu">
          <div className="bm-head">
            <span className="bm-avatar">{initials}</span>
            <span className="bm-who">
              <b>{session?.name}</b>
              <span className="bm-role">{isAdmin ? "Administrator" : isOverseer ? "BDC Oversight" : "Manager"}</span>
            </span>
          </div>
          <div className="bm-app">Sage</div>
          {onHelp && <button className="bm-item" onClick={() => { setOpen(false); onHelp(); }}>Get help</button>}
          {onReplayIntro && (
            <button className="bm-item" onClick={() => { setOpen(false); onReplayIntro(); }}>Replay intro</button>
          )}
          <button className="bm-item" onClick={() => { setOpen(false); onSignOut(); }}>Sign out</button>
        </div>
      )}
    </div>
  );
}

/* ---------------- What a salesperson sees about themselves ----------------
   Two things they could never see before without asking a manager: what they are
   meant to get done today, and how they are actually doing. Both read from data
   the tool already holds. Nothing new is asked of anyone. */
/* Every one of these sheets is a full-screen overlay, so it belongs at the top of
   the document and nowhere else.

   Help is opened from inside My day, so its overlay was a position:fixed element
   nested inside .help-sheet. That sheet runs the helpUp entry animation with
   animation-fill-mode:both, and a filling transform animation leaves the computed
   transform as an identity matrix rather than none. Measured in the browser: the
   sheet reports transform matrix(1,0,0,1,0,0) forever after the animation ends, and
   ANY transform other than none makes an element the containing block for fixed
   descendants. So the Help overlay sized itself against the scrolled sheet instead
   of the screen and was clipped by the sheet's overflow, which is why it surfaced
   part-way up the checklist rather than rising from the bottom. A fixed probe in
   that position read top=-343 h=787 against an 844px viewport; with the animation
   removed it read top=0 h=844.

   The fill mode is fixed below too, but this portal is the guard that holds: it
   keeps working whatever transform, filter or containment an ancestor later grows. */
function Overlay({ children }) {
  if (typeof document === "undefined") return children;
  return createPortal(children, document.body);
}

/* Keyed on the report field an item ticks from, not the item id, because a store can
   rename "Calls" but it still reads the calls column. */
const AUTO_TONE = { calls: "a", video: "b", tasks: "c" };

/* ---- Floorside helpers ------------------------------------------------- */
/* Which field on the activity row each of the day's five numbers reads. Named
   here rather than inline so the one-number screen and the bands can never
   disagree about which figure they are drawing. */
const STAT_FIELD = {
  calls: "calls", video: "video", tasks: "tasks",
  appt: "apptScheduled", shown: "apptShow",
};
const shortDay = (iso) => {
  if (!iso) return "";
  const d = new Date(iso + "T12:00:00");
  return `${d.getDate()} ${d.toLocaleDateString([], { month: "short" }).toUpperCase()}`;
};
const longDay = (iso) => {
  if (!iso) return "";
  const d = new Date(iso + "T12:00:00");
  return d.toLocaleDateString([], { weekday: "long", day: "numeric", month: "long" });
};

/* Three things worth knowing about the fortnight, worked out rather than
   written: the best run against the bar, the weakest weekday, and the days
   nothing was logged at all. Every one of them is silent when it has nothing
   true to say — a read-out that invents a finding stops being read. */
function SfWorthKnowing({ values, days, target }) {
  const rows = [];
  if (target > 0) {
    let run = 0, best = 0;
    for (const v of values) { if (v >= target) { run++; best = Math.max(best, run); } else run = 0; }
    if (best > 0) rows.push({ tone: "g", label: "Best run", text: `${best} day${best === 1 ? "" : "s"} straight at or over ${target}` });
  }
  // weakest weekday, only once a day of the week has turned up twice
  const byDow = {};
  values.forEach((v, i) => {
    const d = new Date(days[i] + "T12:00:00").getDay();
    (byDow[d] = byDow[d] || []).push(v);
  });
  const dowNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  let worst = null;
  for (const d of Object.keys(byDow)) {
    if (byDow[d].length < 2) continue;
    const avg = byDow[d].reduce((x, y) => x + y, 0) / byDow[d].length;
    if (!worst || avg < worst.avg) worst = { d: +d, avg };
  }
  if (worst) rows.push({ tone: "y", label: "Quietest", text: `${dowNames[worst.d]}s, ${Math.round(worst.avg)} on average` });

  const blanks = values.map((v, i) => (v <= 0 ? days[i] : null)).filter(Boolean);
  if (blanks.length === 1) rows.push({ tone: "r", label: "Nothing logged", text: shortDay(blanks[0]) });
  else if (blanks.length > 1) rows.push({ tone: "r", label: "Nothing logged", text: `${blanks.length} days` });

  if (!rows.length) return null;
  return (
    <div className="sf-worth">
      <div className="sf-worth-h">
        <h4>Worth knowing</h4>
        <span>last {values.length} days</span>
      </div>
      <div className="sf-worth-rows">
        {rows.map((r, i) => (
          <div key={i} className="sf-worth-row">
            <span className={"sf-worth-dot t-" + r.tone} />
            <span><b>{r.label}</b> &mdash; {r.text}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function MyDay({ store, date, meId, meName, stats, std, config, updatedAt, monthStats, thresholds, list, variant, onClose }) {
  const LIST = (Array.isArray(list) && list.length) ? list : DEFAULT_CHECKLIST;
  /* Three of these tick themselves. If the report says the calls were made, asking
     someone to also tell us they were made is busywork, and worse, it invites a tick
     on a day the work did not happen. The hand-ticked ones are the things no report
     can see. */
  const a = stats || {};
  const autoFor = (c) => {
    if (!c.from) return null;
    const got = a[c.from] || 0;
    // Tasks are measured against what was actually posted that day, not a standard:
    // the pile is different every morning.
    const need = c.target === "__posted" ? (a.tasksPosted || 0) : c.target ? (std[c.target] || 0) : 1;
    return { got, need, done: need > 0 ? got >= need * 0.8 : got > 0, left: Math.max(0, need - got) };
  };

  const [ticks, setTicks] = useState(() => {
    const out = {};
    for (const c of LIST) {
      try { out[c.id] = localStorage.getItem(checklistKey(store, date, meId + ":" + c.id)) === "1"; }
      catch (e) { out[c.id] = false; }
    }
    return out;
  });
  const toggle = (c) => {
    if (c.from) return;                     // the reports own this one
    setTicks((p) => {
      const v = !p[c.id];
      try { localStorage.setItem(checklistKey(store, date, meId + ":" + c.id), v ? "1" : "0"); } catch (e) {}
      return { ...p, [c.id]: v };
    });
    buzz(10);
  };
  const isDone = (c) => (c.from ? !!(autoFor(c) || {}).done : !!ticks[c.id]);
  const doneCount = LIST.filter(isDone).length;

  // A quiet celebration the first time an automatic one lands, so the moment the
  // reports catch up is actually noticed rather than silently changing colour.
  const seen = useRef(null);
  const [pop, setPop] = useState(null);
  useEffect(() => {
    const now = LIST.filter((c) => c.from && isDone(c)).map((c) => c.id).join(",");
    if (seen.current !== null && now !== seen.current) {
      const fresh = LIST.find((c) => c.from && isDone(c) && !seen.current.includes(c.id));
      if (fresh) { setPop(fresh.id); buzz([18, 40, 18]); setTimeout(() => setPop(null), 1600); }
    }
    seen.current = now;
  }, [a.calls, a.video, a.tasks]); // eslint-disable-line

  const stamp = updatedAt ? new Date(updatedAt) : null;

  /* Closing rates, month to date. A single day of these means nothing: one showroom
     lead and one sale is not a hundred per cent. They come from the month stats the
     board already publishes for this store. */
  const closers = (() => {
    const s = (monthStats && monthStats[norm(meName)]) || null;
    if (!s) return [];
    // The same prevPct the wall reads its triangles from, off the same published row.
    const prev = s.prevPct || {};
    const one = (k, label, unitsF, pctF, leadsF) => ({
      k, label,
      units: s[unitsF] == null ? null : s[unitsF],
      leads: s[leadsF] == null ? null : s[leadsF],
      pct: s[pctF] == null ? null : s[pctF],
      prev: prev[k] == null ? null : prev[k],
    });
    return [
      one("showroom", "Showroom", "showroomUnits", "showroomPct", "showroomLeads"),
      one("phone", "Phone", "phonePct" in s ? "phoneUnits" : "phoneUnits", "phonePct", "phoneLeads"),
      one("internet", "Internet", "internetUnits", "internetPct", "internetLeads"),
    ].filter((c) => c.pct != null || (c.units != null && c.units > 0));
  })();

  /* These percentages are graded on the wall, so they are graded the same way in the
     salesperson's hand. Both the thresholds and the previous reading travel on the
     published board row, so this is not a second opinion about the numbers, it is the
     wall's own arithmetic re-run on the phone. Inventing a separate scale here would
     eventually put a green number on the TV and an amber one in their pocket, and
     nobody on the floor would know which to believe. */
  const thr = normThresholds(thresholds);
  const toneOf = (pct, ch) => {
    if (pct == null) return "dim";
    const t = thr[ch] || DEFAULT_THRESHOLDS[ch] || { green: 20, yellow: 10 };
    const v = pct * 100;
    return v >= t.green ? "g" : v >= t.yellow ? "y" : "r";
  };
  const TONE_MARK = { g: "check", y: "warn", r: "close", dim: "dot" };
  // Direction and distance since the previous report, in percentage points, with the
  // board's own 0.05pt deadband so a rounding wobble is never dressed up as a trend.
  const moveOf = (cur, prv) => {
    if (cur == null || prv == null) return { dir: "flat", delta: "" };
    const d = (cur - prv) * 100;
    if (d > 0.05) return { dir: "up", delta: "+" + d.toFixed(1) };
    if (d < -0.05) return { dir: "down", delta: d.toFixed(1) };
    return { dir: "flat", delta: "" };
  };

  /* The one channel worth naming today: furthest under its own bar, measured as a
     share of the bar so a 5% internet rate against 20 outranks a 28% showroom rate
     against 30. Silent when everything is at or over, because inventing something to
     fix on a good month is how a coaching tool stops being read. */
  const FOCUS_PLAY = {
    internet: "Send a personalized video on every new lead before you do anything else with it. It is the single biggest lever on this number.",
    phone: "Take the phone ups you are passing on, and get the appointment set before you hang up.",
    showroom: "Ask for the appointment before they leave the lot, and log the be-back the same day.",
  };
  const focus = (() => {
    const cand = closers
      .filter((c) => c.pct != null && thr[c.k] && thr[c.k].green > 0)
      .map((c) => ({ ...c, green: thr[c.k].green, share: (c.pct * 100) / thr[c.k].green }))
      .filter((c) => c.share < 1)
      .sort((x, y) => x.share - y.share)[0];
    if (!cand) return null;
    return { label: cand.label, pct: cand.pct, green: cand.green,
      tone: toneOf(cand.pct, cand.k), play: FOCUS_PLAY[cand.k] || "" };
  })();

  const tiles = [
    { k: "calls", label: "Calls", v: a.calls || 0, target: std.minCalls, tone: "a" },
    { k: "video", label: "Videos", v: a.video || 0, target: std.minVideos, tone: "b" },
    { k: "tasks", label: "Tasks done", v: a.tasks || 0, target: a.tasksPosted || null, tone: "c" },
    { k: "appt", label: "Appts set", v: a.apptScheduled || 0, target: null, tone: "d" },
    { k: "shown", label: "Appts shown", v: a.apptShow || 0, target: null, tone: "e" },
  ];

  /* Three screens, not one long scroll: where you are today, that same day as a
     list, and — new — any one of those five numbers on its own with its last ten
     days beside it. They share the frame the way in uses, so crossing from the
     queue into your day is a change of subject rather than a change of app. */
  const [view, setView] = useState("day");
  const [openK, setOpenK] = useState("calls");

  /* The activity rows are already one per store per day, so a fortnight of one
     person's numbers is a single query against keys we can name in advance.

     Read on the way in rather than when the one-number screen is opened: the
     same ten days are what say whether somebody has missed the standard three
     times in the last five, and that has to be known before the day is drawn
     rather than after they have tapped into it. */
  const [series, setSeries] = useState(null);
  useEffect(() => {
    if (!meName) return;
    let dead = false;
    loadMyDays(store, date, [norm(meName)]).then((d) => { if (!dead) setSeries(d); });
    return () => { dead = true; };
  }, [store, date, meName]);

  /* ---- three of the last five ----------------------------------------------
     Jorge: "if someone in the store keeps not getting to their goal I want it to
     flag it and make it obvious for them and they can't do anything in the app
     until they write down why they're not able to fix everything."

     What the block covers was settled by what a salesperson can actually reach.
     Summary, History, Standards and the Dashboard are manager screens they never
     see, so a block naming them would be a block on nothing while looking like
     one. What they have is the line and this panel, and the line stays open
     however far behind they are: locking somebody off the floor is the most
     expensive thing this app could do to a store, and it would land on whoever
     is already having the worst month. So the note stands in front of their own
     figures, and the way back to the line is on the same screen. */
  const whoKey = norm(meName || "");
  const [record, setRecord] = useState(null);
  const [noteText, setNoteText] = useState("");
  const [noteSaving, setNoteSaving] = useState(false);
  const [noteErr, setNoteErr] = useState("");
  useEffect(() => {
    if (!meName) return;
    let dead = false;
    loadGoalRecord(store, date, norm(meName), meId)
      .then((r) => { if (!dead) setRecord(r); })
      /* A record that cannot be read must not become a block. Being shut out by a
         dropped connection, with no way to answer, is worse than a missed flag. */
      .catch(() => { if (!dead) setRecord({ notes: [], lift: null, signedIn: new Set(), failed: true }); });
    return () => { dead = true; };
  }, [store, date, meName, meId]);

  /* The same reading the manager's screen makes of the same days: which of them
     count, and which of those were under the bar. */
  const standing = series
    ? standingFor(series, { std, worked: (record && record.signedIn) || new Set() })
    : null;
  /* Not until both halves have landed: gating on a half-read record would flash a
     block at somebody who has already answered. */
  const owing = !!(standing && record && !record.failed
    && gatesMyDay("myday") && owesNote(record.notes, standing, record.lift));

  const saveNote = async () => {
    const note = makeNote(noteText, {
      forDay: standing.latestMiss, by: meId || "", name: meName || "", who: whoKey, id: meId || "",
      missed: standing.missed, of: standing.counted,
    });
    if (!note) return;
    setNoteSaving(true); setNoteErr("");
    try {
      await writeGoalNote(store, date, note);
      setRecord((r) => ({ ...(r || { lift: null, signedIn: new Set() }),
        notes: notesFor(addNote((r && r.notes) || [], note)) }));
      setNoteText(""); buzz([18, 40, 18]);
      /* And send it to somebody. The floor row is the RECORD — it is what clears
         the flag and what a manager reads back later — but a record nobody is
         prompted to open is the void this was built to avoid. A ticket is the one
         rail in this app that already reaches a person: it survives the browser
         being closed, it lands in the panel, and Supabase carries it out to
         whatever webhook the store has set. Jorge asked for the notes to come to
         him, and this is the route that already goes there.

         Deliberately after the note is saved, and deliberately unable to fail it.
         Somebody who has written their answer is owed their day back whether or
         not a notification went anywhere. */
      try {
        await saveTicket({
          id: uid() + Date.now().toString(36), at: note.at, kind: "standard", status: "open",
          store: store || "", from: meName || "Not given", reach: "",
          who: whoKey, forDay: note.forDay, missed: standing.missed, of: standing.counted,
          days: standing.days, bar: `${std.minCalls} calls and ${std.minVideos} videos a day`,
          body: note.text, context: `My day, ${meName || "unknown"}, ${date}`,
        });
      } catch (e) { /* the note stands either way */ }
    } catch (e) {
      setNoteErr((e && e.message) || "That did not save. Try again in a moment.");
    }
    setNoteSaving(false);
  };

  const spineItems = LIST.map((c) => {
    const auto = autoFor(c);
    return auto ? { got: auto.got, need: auto.need } : { got: 0, need: 0, done: isDone(c) };
  });
  const spine = (
    <SfSpine mode="day" items={spineItems} cap={`${doneCount} of ${LIST.length} done`} />
  );

  const openTile = tiles.find((t) => t.k === openK) || tiles[0];
  const dayValues = series ? series.map((d) => (d.row ? (d.row[STAT_FIELD[openK]] || 0) : 0)) : null;

  const bands = (
    <div className="sf-bands">
      {tiles.map((t) => {
        const p = t.target ? Math.min(100, Math.round(((t.v || 0) / t.target) * 100)) : null;
        const made = t.target ? t.v >= t.target : false;
        return (
          <button key={t.k} type="button" className="sf-band"
            onClick={() => { buzz(8); setOpenK(t.k); setView("one"); }}>
            <span className="sf-band-fig">
              <span className={"sf-band-dm" + (made ? " made" : "")}><DmNumber value={t.v} /></span>
            </span>
            <span className="sf-band-txt">
              <span className="sf-band-lbl">{t.label}</span>
              <span className="sf-band-of">
                {made ? <b>made it</b> : t.target ? `of ${t.target} · ${t.target - t.v} to go` : "no bar set"}
              </span>
              {p != null && <span className={"sf-meter" + (made ? " done" : "")}><i style={{ width: p + "%" }} /></span>}
            </span>
            <span className="sf-band-go"><PixIcon glyph="arrow" size={12} /></span>
          </button>
        );
      })}
    </div>
  );

  let inner;
  if (owing) {
    /* Their own figures and checklist are replaced by the record of what was
       missed and the box to answer in. Not made unopenable: being shut out of the
       one screen that would tell them why would be absurd, and the way back to
       the line is right here, because the floor is never blocked. */
    const missedRows = (series || [])
      .filter((d) => standing.days.includes(d.day))
      .sort((x, y) => String(y.day).localeCompare(String(x.day)));
    inner = (
      <SfScreen spine={spine} className="sf-v-owe">
        <button type="button" className="sf-back" onClick={onClose}>
          <PixIcon glyph="arrowleft" size={12} /><span>Back to the line</span>
        </button>
        <p className="sf-kicker">{longDay(date)}</p>
        <SfDisplay a={standing.missed + " of your last " + standing.counted}
          b="days missed the bar" />
        <p className="sf-sub">
          The bar is {std.minCalls} calls and {std.minVideos} videos in a day. Write down what is
          stopping you and this goes away. Nobody is being marked down for what you say here,
          and it is the only way anyone finds out what you are up against.
        </p>

        <div className="sf-owe-days">
          {missedRows.map((d) => {
            const r = d.row || {};
            return (
              <div key={d.day} className="sf-owe-day">
                <span className="sf-owe-d">{shortDay(d.day)}</span>
                <span className={"sf-owe-f" + ((Number(r.calls) || 0) < std.minCalls ? " under" : "")}>
                  {r.calls || 0}<small>/{std.minCalls} calls</small>
                </span>
                <span className={"sf-owe-f" + ((Number(r.video) || 0) < std.minVideos ? " under" : "")}>
                  {r.video || 0}<small>/{std.minVideos} videos</small>
                </span>
              </div>
            );
          })}
        </div>

        <div className="sf-owe-box">
          <label htmlFor="sf-owe-note">What is stopping you?</label>
          <textarea id="sf-owe-note" rows={4} value={noteText} maxLength={900}
            onChange={(e) => setNoteText(e.target.value)}
            placeholder={"No inventory in my segment, three days on the desk covering, phone system down\u2026"} />
          {noteErr ? <p className="sf-err">{noteErr}</p> : null}
          <button type="button" className="sf-owe-go" disabled={!noteText.trim() || noteSaving}
            onClick={saveNote}>
            {noteSaving ? "Saving\u2026" : "Send it and carry on"}
          </button>
          <p className="sf-owe-fine">
            Your manager reads this. Signing in, taking ups and logging a delivery all keep
            working. This screen is the only thing waiting on you.
          </p>
        </div>
      </SfScreen>
    );
  } else if (view === "one") {
    const peak = dayValues ? Math.max(...dayValues, 1) : 1;
    const CELLS = 7;
    const topIx = dayValues ? dayValues.indexOf(Math.max(...dayValues)) : -1;
    const pct = openTile.target ? Math.min(100, Math.round((openTile.v / openTile.target) * 100)) : null;
    inner = (
      <SfScreen spine={spine} className="sf-v-one">
        <button type="button" className="sf-back" onClick={() => setView("day")}>
          <PixIcon glyph="arrowleft" size={12} /><span>My day</span>
        </button>
        <p className="sf-kicker">{openTile.label} · last {SF_DAYS} days</p>
        <SfDisplay small a="Where the" b={openTile.label.toLowerCase() + " went"} />

        <div className="sf-one">
          <div className="sf-one-head">
            <span className="sf-one-v">
              {openTile.v}
              {openTile.target ? <small> / {openTile.target} today</small> : <small> today</small>}
            </span>
            {pct != null && <span className="sf-one-p">{pct}%</span>}
          </div>
          {pct != null && (
            <div className="sf-one-track">
              {Array.from({ length: 10 }, (_, i) => (
                <i key={i} className={i < Math.round(pct / 10) ? "on" : ""} />
              ))}
            </div>
          )}
          {!dayValues ? (
            <p className="sf-one-wait">Reading the last {SF_DAYS} days&hellip;</p>
          ) : (
            <>
              <div className="sf-cols">
                {dayValues.map((v, i) => {
                  const filled = v <= 0 ? 0 : Math.max(1, Math.round((v / peak) * CELLS));
                  return (
                    <span key={i} className={"sf-col" + (i === topIx && v > 0 ? " top" : "")}>
                      {i === topIx && v > 0 && (
                        <span className="sf-col-call"><b>{v}</b>best day</span>
                      )}
                      {Array.from({ length: CELLS }, (_, r) => (
                        <span key={r} className={"sf-sq" + (r < filled ? "" : " off")} />
                      ))}
                    </span>
                  );
                })}
              </div>
              <div className="sf-axis">
                <span>{shortDay(series[0].day)}</span>
                <span>{shortDay(series[Math.floor(SF_DAYS / 2)].day)}</span>
                <span>{shortDay(series[SF_DAYS - 1].day)}</span>
              </div>
            </>
          )}
        </div>

        {dayValues && <SfWorthKnowing values={dayValues} days={series.map((d) => d.day)} target={openTile.target} />}
      </SfScreen>
    );
  } else if (view === "list") {
    inner = (
      <SfScreen spine={spine} className="sf-v-list">
        <button type="button" className="sf-back" onClick={() => setView("day")}>
          <PixIcon glyph="arrowleft" size={12} /><span>My day</span>
        </button>
        <p className="sf-kicker">{longDay(date)}</p>
        <SfDisplay a="Today's" b="list" />
        <p className="sf-sub">The top three tick themselves off the reports. The rest are yours, and nobody is graded on them.</p>
        <div className="sf-tasks">
          {LIST.map((c) => {
            const auto = autoFor(c);
            const done = isDone(c);
            return (
              <button key={c.id} type="button"
                className={"sf-task" + (done ? " on" : "") + (c.from ? " auto" : "") + (pop === c.id ? " pop" : "")}
                onClick={() => toggle(c)} aria-disabled={!!c.from}>
                <span className="sf-task-top">
                  <span className="sf-task-l">{c.label}</span>
                  <span className={"sf-task-c" + (done ? " good" : "")}>
                    {auto
                      ? (stats ? `${auto.got}/${auto.need}` : "waiting")
                      : (done ? <PixIcon glyph="check" size={13} /> : "tap")}
                  </span>
                </span>
                <span className="sf-task-h">{c.hint}</span>
              </button>
            );
          })}
        </div>
      </SfScreen>
    );
  } else {
    inner = (
      <SfScreen spine={spine} className="sf-v-day">
        <button type="button" className="sf-back" onClick={onClose}>
          <PixIcon glyph="arrowleft" size={12} /><span>Back to the line</span>
        </button>
        <p className="sf-kicker">{longDay(date)}</p>
        <SfDisplay a={meName ? meName.split(" ")[0] + "'s" : "My"} b="day" />

        <div className="sf-cap">
          <span>Today&rsquo;s work</span>
          <b>{tiles.filter((t) => t.target && t.v >= t.target).length} of {tiles.filter((t) => t.target).length} at the bar</b>
        </div>
        {!stats
          ? <p className="sf-sub">Today&rsquo;s numbers have not landed yet. They come in through the day.</p>
          : bands}

        {closers.length > 0 && (
          <>
            <div className="sf-cap"><span>Closing this month</span></div>
            <div className="sf-rates">
              {closers.map((c) => {
                const tn = toneOf(c.pct, c.k);
                const mv = moveOf(c.pct, c.prev);
                return (
                  <div key={c.k} className={"sf-rate sf-tone-" + tn}>
                    <span className="sf-rate-v">{c.pct == null ? "–" : Math.round(c.pct * 100) + "%"}</span>
                    <span className="sf-rate-l">
                      {c.label}<PixIcon className="sf-rate-mark" glyph={TONE_MARK[tn]} size={10} />
                    </span>
                    <span className="sf-rate-g">goal {(thr[c.k] || {}).green}%</span>
                    <span className={"sf-rate-m " + mv.dir}>
                      <PixIcon glyph={mv.dir === "up" ? "triup" : mv.dir === "down" ? "tridown" : "dot"} size={9} />
                      {mv.delta ? <i>{mv.delta}</i> : null}
                    </span>
                  </div>
                );
              })}
            </div>
          </>
        )}

        {focus && (
          <>
            <div className="sf-cap"><span>Start here</span></div>
            <div className={"sf-focus sf-tone-" + focus.tone}>
              <h4>{focus.label}</h4>
              <div className="sf-focus-n">{Math.round(focus.pct * 100)}% against a bar of {focus.green}%</div>
              <p>{focus.play}</p>
            </div>
          </>
        )}

        <button type="button" className="sf-jump" onClick={() => setView("list")}>
          Today&rsquo;s list<span>{doneCount} of {LIST.length}</span>
          <PixIcon glyph="arrow" size={13} />
        </button>

        <div className={"sf-stamp" + (stamp ? "" : " none")}>
          {stamp
            ? `Numbers as of ${stamp.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}`
            : "No activity report has landed for today yet"}
        </div>
        {/* A salesperson's own figures. They are the person most likely to spot a
            wrong one — it is their day — and least likely to have anywhere to say
            so, which is how a wrong number gets lived with for a month. */}
        <HelpButton config={config} who={meName} store={store}
          context={`My day, ${meName || "unknown"}, ${date}`}
          figures={[
            { label: `Calls today`, value: String(stats?.calls ?? "\u2014") },
            { label: `Videos today`, value: String(stats?.video ?? "\u2014") },
            { label: `Texts today`, value: String(stats?.text ?? "\u2014") },
            { label: `Emails today`, value: String(stats?.email ?? "\u2014") },
            { label: `Tasks today`, value: String(stats?.tasks ?? "\u2014") },
            { label: `Ups credited today`, value: String(stats?.visits ?? "\u2014") },
            { label: `Units this month`, value: String(monthStats?.units ?? "\u2014") },
          ]}
          floating={false} />
      </SfScreen>
    );
  }

  return (
    <Overlay>
      <div className={"q-page sf sf-day-root " + ((variant && variant.sf) || "")}
        role="dialog" aria-label="My day">{inner}</div>
    </Overlay>
  );
}

/* ---------------- Help and tickets ----------------
   One button, everywhere, for everyone. A manager who cannot save and a salesperson
   whose name is missing from the line both end up in the same place, and neither has
   to know who to ask. */
function HelpButton({ config, who, store, context, figures, floating = true }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button className={"help-fab" + (floating ? "" : " inline")} onClick={() => setOpen(true)}
        title="Get help, or say a number is wrong" aria-label="Get help, or say a number is wrong">
        <PixIcon glyph="question" size={floating ? 20 : 15} />
        {!floating && <span>Help</span>}
      </button>
      {open && <HelpPanel config={config} who={who} store={store} context={context} figures={figures}
        onClose={() => setOpen(false)} />}
    </>
  );
}

/* ---- "This number is wrong" is not "I need help" ----

   They arrive through the same button because nobody wants to learn two, but they
   are different reports and mixing them loses both. Somebody who cannot sign in
   is stuck and wants an answer. Somebody looking at 84.5 where they know they
   sold 85 is not stuck at all — they are telling us the tool is lying, and that
   is worth more than a support request, because they are the only ones who can
   see it. A screen that only offers "get help" quietly teaches people that a
   wrong number is their problem to live with.

   The difference this makes is what gets captured. "The numbers are off" is
   unactionable and it is what you get if you ask an open question. So the form
   asks the three things that make it fixable — which figure, what it should say,
   and how they know — and takes the rest off the screen itself. */
function HelpPanel({ config, who, store, context, figures, onClose }) {
  const s = (config && config.support) || {};
  const [tab, setTab] = useState("contact");
  const [what, setWhat] = useState("");
  const [name, setName] = useState(who || "");
  const [reach, setReach] = useState("");
  const [sent, setSent] = useState(null);   // null | "sending" | "ok" | "fail"
  // The wrong-number report
  const onScreen = Array.isArray(figures) ? figures.filter((f) => f && f.label) : [];
  const [which, setWhich] = useState("");
  const [shouldBe, setShouldBe] = useState("");
  const [basis, setBasis] = useState("");

  const picked = onScreen.find((f) => f.label === which) || null;
  const wrongReady = !!(which.trim() || what.trim());

  const baseTicket = () => ({
    id: uid() + Date.now().toString(36),
    at: new Date().toISOString(),
    from: name.trim() || "Not given",
    reach: reach.trim(),
    store: store || "",
    // What the app was doing when they hit the button, so a ticket does not
    // arrive as "it broke" with nothing to go on.
    context: context || "",
    page: (typeof window !== "undefined" && window.location ? window.location.pathname + window.location.search : ""),
    agent: (typeof navigator !== "undefined" ? navigator.userAgent : ""),
    status: "open",
  });

  const send = async () => {
    if (!what.trim()) return;
    setSent("sending");
    setSent((await saveTicket({ ...baseTicket(), kind: "problem", body: what.trim() })) ? "ok" : "fail");
  };

  const sendWrong = async () => {
    if (!wrongReady) return;
    setSent("sending");
    const t = {
      ...baseTicket(),
      kind: "figures",
      figure: which.trim(),
      /* Taken off the screen rather than typed. Somebody reporting a wrong number
         should not have to transcribe it correctly to be believed, and what they
         were looking at is the one fact that cannot be reconstructed later — by
         the time anybody reads this, the import may have run again. */
      shown: picked ? String(picked.value) : "",
      expected: shouldBe.trim(),
      basis: basis.trim(),
      /* Everything else that was on the screen at that moment, which is how a
         wrong figure usually gets traced: the one that is off is rarely off
         alone. */
      snapshot: onScreen.map((f) => ({ label: f.label, value: String(f.value) })),
      body: what.trim(),
    };
    setSent((await saveTicket(t)) ? "ok" : "fail");
  };

  return (
    <Overlay>
    <div className="help-back" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="help-sheet" role="dialog" aria-label="Help">
        <div className="help-head">
          {/* The heading follows the tab. "Need a hand?" over a wrong-number form
              tells somebody they are asking for help, which is the framing that
              stops people reporting a bad figure at all: they do not need help,
              they are doing us one. */}
          <h3>{tab === "wrong" ? "Something look wrong?" : tab === "ticket" ? "Something broken?" : "Need a hand?"}</h3>
          <button className="btn-x md-x" onClick={onClose} aria-label="Close">
            <PixIcon glyph="close" size={19} />
          </button>
        </div>
        <div className="help-tabs">
          <button className={"help-tab help-tab-wrong" + (tab === "wrong" ? " on" : "")} onClick={() => setTab("wrong")}>
            A number's wrong
          </button>
          <button className={"help-tab" + (tab === "ticket" ? " on" : "")} onClick={() => setTab("ticket")}>Something's broken</button>
          <button className={"help-tab" + (tab === "contact" ? " on" : "")} onClick={() => setTab("contact")}>Contact</button>
        </div>

        {tab === "wrong" ? (
          <div className="help-body">
            {sent === "ok" ? (
              <div className="help-done">
                <PixIcon glyph="check" size={26} />
                <b>Flagged.</b>
                <p className="hint">
                  {s.name ? s.name.split(" ")[0] : "An administrator"} gets this with the figure you were looking at
                  and everything else on the screen beside it. Nothing about your day changes in the meantime;
                  the number stays as it is until somebody has looked.
                </p>
              </div>
            ) : (
              <>
                <p className="help-intro">
                  If a figure here does not match what you know happened, say so. You are the only one who can
                  see that, and it is worth telling us even when you are not stuck.
                </p>

                <label className="help-lbl">Which number?</label>
                {onScreen.length > 0 ? (
                  <select className="help-in" value={which} onChange={(e) => setWhich(e.target.value)}>
                    <option value="">Pick the one that looks wrong…</option>
                    {onScreen.map((f) => (
                      <option key={f.label} value={f.label}>{f.label}, showing {String(f.value)}</option>
                    ))}
                    <option value="__other">Something else on this screen</option>
                  </select>
                ) : (
                  <input className="help-in" value={which} onChange={(e) => setWhich(e.target.value)}
                    placeholder="e.g. my units for the month" />
                )}

                {which && which !== "__other" && picked && (
                  <div className="help-shown">
                    This screen is showing <b>{String(picked.value)}</b>
                  </div>
                )}

                <div className="help-row">
                  <span>
                    <label className="help-lbl">What should it be?</label>
                    <input className="help-in" value={shouldBe} onChange={(e) => setShouldBe(e.target.value)}
                      placeholder="If you know" />
                  </span>
                  <span>
                    <label className="help-lbl">How do you know?</label>
                    <input className="help-in" value={basis} onChange={(e) => setBasis(e.target.value)}
                      placeholder="e.g. DriveCentric says 12" />
                  </span>
                </div>

                <label className="help-lbl">Anything else worth knowing</label>
                <textarea className="help-area" rows={3} value={what} onChange={(e) => setWhat(e.target.value)}
                  placeholder="Optional. When you noticed it, whether it was right yesterday, anything odd that day." />

                <div className="help-row">
                  <span>
                    <label className="help-lbl">Your name</label>
                    <input className="help-in" value={name} onChange={(e) => setName(e.target.value)}
                      placeholder="So somebody can come back to you" />
                  </span>
                  <span>
                    <label className="help-lbl">Phone or email</label>
                    <input className="help-in" value={reach} onChange={(e) => setReach(e.target.value)} placeholder="Optional" />
                  </span>
                </div>

                <p className="hint">
                  Sent with it: {context ? context + ", " : ""}
                  {onScreen.length > 0
                    ? `and the ${onScreen.length} ${onScreen.length === 1 ? "figure" : "figures"} on this screen as they stand right now.`
                    : "and the page you are on."}
                </p>
                {sent === "fail" && <p className="sched-err">That did not send. Check the connection and try again.</p>}
                <button className="btn" disabled={!wrongReady || sent === "sending"} onClick={sendWrong}>
                  {sent === "sending" ? "Sending…" : "Flag it"}
                </button>
              </>
            )}
          </div>
        ) : tab === "contact" ? (
          <div className="help-body">
            <div className="help-person">
              <span className="help-avatar">{String(s.name || "?").split(/\s+/).slice(0, 2).map((w) => w[0]).join("").toUpperCase()}</span>
              <span>
                <b>{s.name || "Your administrator"}</b>
                {s.role && <span className="help-role">{s.role}</span>}
              </span>
            </div>
            {s.email && <a className="help-link" href={`mailto:${s.email}?subject=${encodeURIComponent("Sage help" + (store ? " (" + store + ")" : ""))}`}>{s.email}</a>}
            {s.phone && <a className="help-link" href={`tel:${String(s.phone).replace(/[^\d+]/g, "")}`}>{s.phone}</a>}
            {s.note && <p className="hint">{s.note}</p>}
            {!s.email && !s.phone && <p className="hint">No contact details have been set yet. Use Report a problem and it will still reach an administrator.</p>}
            <p className="hint">Reporting the problem here sends more detail than a message can, so it is usually the faster route.</p>
          </div>
        ) : (
          <div className="help-body">
            {sent === "ok" ? (
              <div className="help-done">
                <PixIcon glyph="check" size={26} />
                <b>Sent.</b>
                <p className="hint">{s.name ? s.name.split(" ")[0] : "Your administrator"} will see this with the page you were on and what you were doing. You can close this.</p>
              </div>
            ) : (
              <>
                <label className="help-lbl">What happened?</label>
                <textarea className="help-area" rows={4} value={what} onChange={(e) => setWhat(e.target.value)}
                  placeholder="What you were trying to do, and what the screen did instead." />
                <div className="help-row">
                  <span>
                    <label className="help-lbl">Your name</label>
                    <input className="help-in" value={name} onChange={(e) => setName(e.target.value)} placeholder="So they know who to answer" />
                  </span>
                  <span>
                    <label className="help-lbl">Phone or email</label>
                    <input className="help-in" value={reach} onChange={(e) => setReach(e.target.value)} placeholder="Optional" />
                  </span>
                </div>
                {context && <p className="hint">This will include: {context}</p>}
                {sent === "fail" && <p className="sched-err">That did not send. Check the connection and try again, or use the Contact tab.</p>}
                <button className="btn" disabled={!what.trim() || sent === "sending"} onClick={send}>
                  {sent === "sending" ? "Sending..." : "Send it"}
                </button>
              </>
            )}
          </div>
        )}
      </div>
    </div>
    </Overlay>
  );
}

/* ---------------- Repairing a store that got another store's people ----------------
   A cross-store race merged one store's roster, ignore list and departures into
   another, and every snapshot taken afterwards carries the damage, so rolling back
   cannot undo it.

   This does not guess. A store's own imported reports are the record of who actually
   works there: if a name has never appeared in this store's month stats or in any of
   its activity days, it was never in one of its reports, and it does not belong on
   its roster. That test is what makes the repair safe to run.

   Nothing is written until the preview has been read and confirmed, and a full copy
   of the store is saved first. */
function RepairPanel({ config }) {
  const [target, setTarget] = useState("");
  const [source, setSource] = useState("");     // optional: compare against one store
  /* Two faults, and only one of them can be found by looking.

     "shared" is the original: a name on this store's roster that is also on
     another store's. That is what a copied roster looks like, and the comparison
     finds it on its own.

     "pick" is for the one that followed. When another dealership's REPORT was
     filed here, its people arrived with real figures and real activity days
     attached — a full working history at a store they have never set foot in.
     They are on no other store's roster, so the comparison finds nothing and
     says so; and every test of "does this store's own record know them" comes
     back yes, because the wrong record is the one that was written.

     Nothing observable separates them from the real floor. The only authority
     is somebody who knows who works there, so this mode stops guessing and
     asks. */
  const [mode, setMode] = useState("shared");
  const [plan, setPlan] = useState(null);
  const [picked, setPicked] = useState({});
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(null);

  /* How much a store's own records actually say about a person. Used to decide who a
     name belongs to when it appears in two places, because the roster alone cannot
     tell you: a copied roster looks exactly like a real one. Real work leaves a
     trail of days and figures behind it; a name that got in by accident does not. */
  const evidenceFor = (data) => {
    const ev = {};
    const bump = (k, n) => { if (!k) return; ev[k] = (ev[k] || 0) + n; };
    for (const m of Object.values(data.months || {})) {
      for (const [k, s] of Object.entries((m && m.stats) || {})) {
        const real = s && Object.entries(s).some(([f, v]) =>
          typeof v === "number" && v > 0 && !/^prev|Updated$/.test(f));
        bump(k, real ? 3 : 0);
      }
    }
    for (const day of Object.values(data.activity || {})) {
      for (const [k, r] of Object.entries(day || {})) {
        const worked = r && ((r.calls || 0) > 0 || (r.video || 0) > 0 || (r.tasks || 0) > 0);
        bump(k, worked ? 2 : 0);
      }
    }
    return ev;
  };

  const build = async () => {
    if (!target) return;
    setBusy(true); setPlan(null); setDone(null); setPicked({});
    try {
      const data = await loadStore(target, null, true);
      if (!data) { setPlan({ error: "That store has no data document." }); return; }
      const mine = evidenceFor(data);

      // Every other store's roster and evidence, so a shared name can be weighed.
      const others = [];
      for (const s of config.stores || []) {
        if (s.id === target) continue;
        if (source && s.id !== source) continue;
        try {
          const d = await loadStore(s.id, null, true);
          if (!d) continue;
          const plateTags = new Set();
          for (const r of (d.plateRegistry) || []) if (r && r.tag) plateTags.add(normTag(r.tag));
          for (const list of Object.values((d.plates) || {})) {
            for (const p of list || []) if (p && p.tag) plateTags.add(normTag(p.tag));
          }
          others.push({
            id: s.id, name: s.name,
            roster: new Set(((d.roster) || []).map((a) => norm(a.name))),
            excluded: new Set(((d.excluded) || []).map(norm)),
            plateTags,
            ev: evidenceFor(d),
          });
        } catch (e) { /* a store we cannot read is simply not used as evidence */ }
      }

      const judge = (name) => {
        const k = norm(name);
        const home = others.find((o) => o.roster.has(k) || o.excluded.has(k));
        if (!home) return null;
        return { from: home.name, hereScore: mine[k] || 0, thereScore: home.ev[k] || 0 };
      };

      /* What this store's own books have against a name, in the units a manager
         thinks in. It is the thing that makes the choice possible: a person who
         does not work here still shows up with cars beside their name, and those
         cars are in the store's month total right now. */
      const monthUnits = (() => {
        const M = data.months?.[ym()];
        const out = {};
        for (const [k, st] of Object.entries((M && M.stats) || {})) {
          out[k] = (st?.internetUnits ?? 0) + (st?.phoneUnits ?? 0)
                 + (st?.showroomUnits ?? 0) + (st?.campaignUnits ?? 0);
        }
        return out;
      })();
      const daysOnRecord = (() => {
        const out = {};
        for (const day of Object.values(data.activity || {})) {
          for (const [k, r] of Object.entries(day || {})) {
            const worked = r && ((r.calls || 0) > 0 || (r.video || 0) > 0 || (r.tasks || 0) > 0);
            if (worked) out[k] = (out[k] || 0) + 1;
          }
        }
        return out;
      })();
      const detail = (name) => {
        const k = norm(name);
        return { units: monthUnits[k] || 0, days: daysOnRecord[k] || 0 };
      };

      const rows = [];
      const take = (kind, name) => {
        if (mode === "pick") { rows.push({ kind, name, ...detail(name) }); return; }
        const j = judge(name);
        if (j) rows.push({ kind, name, ...j, ...detail(name) });
      };
      for (const a of (data.roster) || []) take("roster", a.name);
      for (const x of (data.excluded) || []) take("excluded", x);
      for (const d of (data.departed) || []) take("departed", d.name);

      /* Plates carry no activity history to weigh, so the evidence is who was holding
         them: a plate logged out to somebody who works at another store came from that
         store. Registry entries follow the same rule, and any tag whose only appearance
         here is in the registry is judged by whether the other store owns it. */
      const goneNames = new Set(rows.filter((r) => r.kind === "roster").map((r) => norm(r.name)));
      const usedHere = new Set();
      const plateRows = [];
      for (const [d, list] of Object.entries((data.plates) || {})) {
        for (const p of list || []) {
          if (!p || !p.tag) continue;
          const who = norm(p.assignee || "");
          /* Who was holding it settles it. If the holder has real work on record at
             another store and none here, the plate came with them. Being on this
             store's roster is not enough on its own, because a contaminated roster
             is exactly what put them there. */
          const home = others.find((o) => (who && o.roster.has(who)) || o.plateTags.has(normTag(p.tag)));
          const holderIsOurs = who && (mine[who] || 0) > 0 && !goneNames.has(who);
          if (home && !holderIsOurs) plateRows.push({ kind: "plate", name: `${p.tag} (${p.assignee || "unassigned"}, ${d})`,
            tag: p.tag, day: d, id: p.id, from: home.name, hereScore: mine[who] || 0,
            thereScore: (home.ev[who] || 0) || 1 });
          else usedHere.add(normTag(p.tag));
        }
      }
      for (const r of (data.plateRegistry) || []) {
        if (!r || !r.tag) continue;
        if (usedHere.has(normTag(r.tag))) continue;
        const home = others.find((o) => o.plateTags.has(normTag(r.tag)));
        if (home) plateRows.push({ kind: "plateReg", name: r.tag, tag: r.tag, id: r.id,
          from: home.name, hereScore: 0, thereScore: 1 });
      }
      rows.push(...plateRows);

      // Ticked by default only where the other store clearly has the stronger claim.
      // Everything else is listed but left for a person to decide.
      const pre = {};
      for (const r of rows) pre[r.kind + ":" + norm(r.name)] = r.thereScore > r.hereScore;
      setPicked(pre);
      setPlan({
        store: (config.stores || []).find((s) => s.id === target)?.name || target,
        total: ((data.roster) || []).length, rows, data,
      });
    } catch (e) {
      setPlan({ error: String(e.message || e) });
    } finally { setBusy(false); }
  };

  const chosen = plan && !plan.error ? plan.rows.filter((r) => picked[r.kind + ":" + norm(r.name)]) : [];

  const apply = async () => {
    if (!chosen.length) return;
    if (!window.confirm(`Remove ${chosen.length} entries from ${plan.store}?\n\nA full copy of the store is saved first, and only the ticked names are touched.`)) return;
    setBusy(true);
    try {
      const stamp = new Date().toISOString().replace(/[:.]/g, "-");
      await saveShared(backupStoreKey(target, `repair-${stamp}`), plan.data);

      const go = { roster: new Set(), excluded: new Set(), departed: new Set() };
      const goPlates = new Set(), goPlateReg = new Set();
      for (const r of chosen) {
        if (r.kind === "plate") goPlates.add(r.day + "|" + (r.id || normTag(r.tag)));
        else if (r.kind === "plateReg") goPlateReg.add(normTag(r.tag));
        else go[r.kind].add(norm(r.name));
      }

      const res = await saveStoreCAS(storeKey(target), (server) => {
        const out = JSON.parse(JSON.stringify(server || plan.data));
        const t = new Date().toISOString();

        /* ---- Removing a person has to be RECORDED, not just done ----

           Filtering the roster here does not remove anybody. Every other manager
           with this store open still holds them, and the roster merge is a union:
           the next save from any tab on the floor puts every one of them straight
           back, and the tool looks like it did nothing. It is the same trap the
           ignore list hit and the same one the plate log hit — the note two blocks
           down explains it for plates — and people were the one thing still doing
           it the old way.

           So a removal is written as an ignore with a timestamp, which is the
           mechanism the merge already honours. It also settles the other half:
           the next import naming them will not add them back either, because the
           importer skips ignored names. Gone, and staying gone. */
        const goneNames = new Set([...go.roster, ...go.departed, ...go.excluded]);
        out.excluded = [...(out.excluded || [])];
        out.ignoredAt = { ...(out.ignoredAt || {}) };
        const already = new Set(out.excluded.map(norm));
        for (const r of chosen) {
          if (r.kind === "plate" || r.kind === "plateReg") continue;
          const k = norm(r.name);
          if (!already.has(k)) { out.excluded.push(r.name); already.add(k); }
          out.ignoredAt[k] = t;
          /* And clear any stamp that says they were let back in, or the same
             comparison that protects this would undo it. */
          if (out.unignored) delete out.unignored[k];
        }

        out.roster = (out.roster || []).filter((a) => !goneNames.has(norm(a.name)));
        out.departed = (out.departed || []).filter((d) => !goneNames.has(norm(d.name)));
        /* Their figures go too, or the Check Out sheet keeps showing them — and,
           worse, the store's month total keeps counting cars it never sold. */
        for (const m of Object.values(out.months || {})) {
          if (!m || !m.stats) continue;
          for (const k of Object.keys(m.stats)) if (goneNames.has(k)) delete m.stats[k];
        }
        for (const day of Object.keys(out.activity || {})) {
          for (const k of Object.keys(out.activity[day] || {})) if (goneNames.has(k)) delete out.activity[day][k];
        }
        /* Tombstoned as well as filtered. Every manager with this store open still
           holds the foreign plates in their tab, and the plate merge treats a plate
           it has not seen before as news — so without a record of the removal the
           next save anywhere on the floor puts them all back. */
        out.plateGone = { ...(out.plateGone || {}) };
        out.plateRegGone = { ...(out.plateRegGone || {}) };
        for (const day of Object.keys(out.plates || {})) {
          for (const p of out.plates[day] || []) {
            if (p && p.id && goPlates.has(day + "|" + (p.id || normTag(p.tag)))) out.plateGone[p.id] = t;
          }
          out.plates[day] = (out.plates[day] || []).filter((p) =>
            !goPlates.has(day + "|" + (p.id || normTag(p.tag))));
          if (!out.plates[day].length) delete out.plates[day];
        }
        for (const r of out.plateRegistry || []) {
          if (r && r.id && goPlateReg.has(normTag(r.tag))) out.plateRegGone[r.id] = t;
        }
        out.plateRegistry = (out.plateRegistry || []).filter((r) => !goPlateReg.has(normTag(r.tag)));
        out.__storeId = target;
        return out;
      });
      setDone(res.ok
        ? `Done. ${chosen.length} entries removed from ${plan.store}, along with their figures. A copy of the store as it was is in the backup list.`
        : `Could not write: ${lastSaveError || "unknown"}`);
      setPlan(null);
    } catch (e) { setDone("Failed: " + String(e.message || e)); }
    finally { setBusy(false); }
  };

  const groups = [["roster", "People"], ["excluded", "Ignored names"], ["departed", "Marked as departed"],
    ["plate", "Plates logged out"], ["plateReg", "Plates on the master list"]];

  return (
    <div className="card">
      <h3>Take people off a store they do not belong to</h3>
      <div className="seg-small" style={{ marginBottom: 10 }}>
        {[["shared", "Find them for me"], ["pick", "I'll pick them"]].map(([id, lbl]) => (
          <button key={id} className={"seg-opt " + (mode === id ? "on" : "")}
            onClick={() => { setMode(id); setPlan(null); setDone(null); setPicked({}); }}>{lbl}</button>
        ))}
      </div>
      {mode === "shared" ? (
        <p className="hint">
          For a store showing names that belong somewhere else. Every shared name is listed with how much
          each store's own records actually say about that person: real days worked and real figures. Where
          the other store clearly has the stronger claim it is ticked for you, and everything else is left
          for you to decide. Nothing is removed until you press the button.
        </p>
      ) : (
        <p className="hint">
          For when the comparison finds nothing and you can see perfectly well that it is wrong. That happens
          when another dealership's <b>report</b> was filed here rather than its roster: its people arrived
          with real figures and real days attached, so they are on no other store's list to be compared
          against, and every test of "does this store know them" comes back yes, because the wrong record
          is the one that got written. Nothing can tell them apart from your real floor except somebody who
          knows who works there. Every name this store carries is below, with the cars it is currently
          counting for each. Tick the ones who do not work here.
        </p>
      )}
      <div className="inline-form">
        <select value={target} onChange={(e) => { setTarget(e.target.value); setPlan(null); setDone(null); }}>
          <option value="">Which store is wrong?</option>
          {(config.stores || []).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
        </select>
        {mode === "shared" && (
          <select value={source} onChange={(e) => { setSource(e.target.value); setPlan(null); }}>
            <option value="">Compare with every store</option>
            {(config.stores || []).filter((s) => s.id !== target).map((s) => <option key={s.id} value={s.id}>Only {s.name}</option>)}
          </select>
        )}
        <button className="btn" disabled={!target || busy} onClick={build}>
          {busy ? "Checking..." : mode === "shared" ? "Check it" : "List everybody"}
        </button>
      </div>

      {done && <p className="hint" style={{ marginTop: 10 }}><b>{done}</b></p>}
      {plan && plan.error && <p className="sched-err">{plan.error}</p>}

      {plan && !plan.error && (
        <div style={{ marginTop: 14 }}>
          {plan.rows.length === 0 ? (
            mode === "shared" ? (
              <p className="hint">
                <b>Nothing shared.</b> No name on {plan.store} also belongs to another store.{" "}
                That is not the same as nothing being wrong: if another dealership's report was filed
                here, its people are on no other store's roster and this comparison cannot see them.
                Switch to <b>I'll pick them</b>.
              </p>
            ) : <p className="hint"><b>{plan.store} carries no names at all.</b></p>
          ) : (
            <>
              <p className="hint">
                <b>{plan.store}</b> has {plan.total} on its roster.{" "}
                {mode === "shared"
                  ? <>{plan.rows.length === 1 ? "One entry is" : `${plan.rows.length} entries are`} shared with another store.{" "}</>
                  : <>{plan.rows.length} {plan.rows.length === 1 ? "name" : "names"} in total.{" "}</>}
                <b>{chosen.length} ticked</b> for removal
                {chosen.length > 0 && (() => {
                  const cars = chosen.reduce((n, r) => n + (r.units || 0), 0);
                  return cars > 0
                    ? <>, carrying <b>{fmtNum(Math.round(cars * 10) / 10)}</b> of this month's cars with them</>
                    : null;
                })()}.
              </p>
              {groups.filter(([k]) => plan.rows.some((r) => r.kind === k)).map(([k, label]) => (
                <div key={k} style={{ marginTop: 12 }}>
                  <div className="md-cap">{label} <span>{plan.rows.filter((r) => r.kind === k).length}</span></div>
                  <div className="rp-list">
                    {plan.rows.filter((r) => r.kind === k).map((r) => {
                      const key = r.kind + ":" + norm(r.name);
                      return (
                        <button key={key} className={"rp-row" + (picked[key] ? " on" : "")}
                          onClick={() => setPicked((p) => ({ ...p, [key]: !p[key] }))}>
                          <span className="md-box">{picked[key] && <PixIcon glyph="check" size={13} />}</span>
                          <span className="rp-nm">{r.name}</span>
                          <span className="rp-ev">
                            {r.kind === "plate" || r.kind === "plateReg"
                              ? <>belongs to {r.from}</>
                              : mode === "pick"
                                /* What this store is counting for them right now, which is
                                   the thing a manager recognises. A name with cars against
                                   it at a store it has never worked at is the whole fault
                                   stated in four words. */
                                ? <>{r.units > 0 ? <><b>{fmtNum(r.units)}</b> cars this month</> : "no cars this month"}
                                  {r.days > 0 ? <> · {r.days} {r.days === 1 ? "day" : "days"} on record</> : " · no days on record"}</>
                                : <>here <b>{r.hereScore}</b> · {r.from} <b>{r.thereScore}</b></>}
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
              <p className="hint" style={{ marginTop: 10 }}>
                {mode === "shared"
                  ? <>The numbers are how much real work each store has on record for that person. A high number
                     somewhere else and a zero here is the clearest sign a name got in by mistake.</>
                  : <>Removing somebody takes this month's cars with them, so the store's total and its pace
                     correct themselves. A copy of the store as it stands is saved first, and the removal is
                     written down rather than just done. Otherwise the next manager whose tab is still open
                     would put everybody straight back.</>}
              </p>
              <button className="btn" style={{ marginTop: 8 }} disabled={busy || !chosen.length} onClick={apply}>
                {busy ? "Working..." : `Remove the ${chosen.length} ticked`}
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------------- Tickets, and who to send them to ---------------- */
function TicketsPanel({ config, onChange }) {
  const [items, setItems] = useState(null);
  const [filter, setFilter] = useState("open");
  const [kind, setKind] = useState("all");
  const s = (config && config.support) || {};
  const [form, setForm] = useState({ name: s.name || "", role: s.role || "", email: s.email || "",
    phone: s.phone || "", note: s.note || "", alertWebhook: s.alertWebhook || "" });

  const reload = () => loadTickets().then(setItems);
  useEffect(() => { reload(); }, []);

  const setStatus = async (t, status) => {
    const next = { ...t, status, closedAt: status === "closed" ? new Date().toISOString() : null };
    if (await saveTicket(next)) reload();
  };
  const saveSupport = () => {
    const next = JSON.parse(JSON.stringify(config));
    next.support = { ...form };
    onChange(next, { action: "Updated support contact", detail: form.name });
  };

  /* A wrong figure outranks a support request, always. Somebody stuck can be
     helped tomorrow; a number that is lying is being read by everybody in the
     meantime, and every hour it stands is an hour of decisions made on it. */
  const shown = (items || [])
    .filter((t) => (filter === "all" ? true : (t.status || "open") === filter))
    .filter((t) => (kind === "all" ? true : (t.kind || "problem") === kind))
    .sort((a, b) => {
      const w = (t) => ((t.status || "open") === "open" && t.kind === "figures" ? 0 : 1);
      return w(a) - w(b) || String(b.at || "").localeCompare(String(a.at || ""));
    });
  const openWrong = (items || []).filter((t) => t.kind === "figures" && (t.status || "open") === "open").length;
  const openBehind = (items || []).filter((t) => t.kind === "standard" && (t.status || "open") === "open").length;
  const openList = (items || []).filter((t) => (t.status || "open") === "open");
  const openCount = openList.length;
  const oldest = openList.map((t) => t.at).filter(Boolean).sort()[0] || null;
  const closedThisMonth = (items || []).filter((t) => t.status === "closed"
    && String(t.closedAt || "").slice(0, 7) === ym()).length;
  /* Which dealership a ticket came from, in that dealership's own colour, so a
     list of tickets across four stores sorts itself by eye. */
  const storeOf = (id) => (config?.stores || []).find((x) => x.id === id || x.name === id) || null;

  return (
    <div className="board-page">
      <div className="card">
        <div className="p-cap2">Who people reach</div>
        <p className="hint">
          What the Help button shows, everywhere. Anything blank is not shown.
        </p>
        <div className="help-row">
          <span><label className="help-lbl">Name</label>
            <input className="help-in" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></span>
          <span><label className="help-lbl">Role</label>
            <input className="help-in" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })} /></span>
        </div>
        <div className="help-row">
          <span><label className="help-lbl">Email</label>
            <input className="help-in" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="name@holler.com" /></span>
          <span><label className="help-lbl">Phone</label>
            <input className="help-in" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="407..." /></span>
        </div>
        <label className="help-lbl">Anything else they should know</label>
        <input className="help-in" value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })}
          placeholder="e.g. Text is fastest on weekends" />

        <label className="help-lbl" style={{ marginTop: 14 }}>Send wrong-number reports to</label>
        <p className="hint">
          A report sitting in this panel until somebody next opens it is barely a report. The value of
          a salesperson saying "that is not what I sold" is that they said it today. Paste an incoming
          webhook here and every flagged number arrives wherever you already look: Slack and Teams both
          hand one out in about a minute, and so does any automation service. Leave it blank and reports
          still land below, just quietly. Reports of things being broken are not sent; only numbers.
        </p>
        <input className="help-in" value={form.alertWebhook || ""}
          onChange={(e) => setForm({ ...form, alertWebhook: e.target.value })}
          placeholder="https://hooks.slack.com/services/…" />
        {form.alertWebhook && !/^https:\/\//i.test(form.alertWebhook.trim()) && (
          <p className="sched-err">That has to start with https. A plain http address would put whatever
            somebody typed across the wire in clear.</p>
        )}
        <button className="go-log2" style={{ marginTop: 12 }} onClick={saveSupport}>Save contact details</button>
      </div>

      <div className="tk-counts">
        <div className="card tk-count">
          <div className="p-cap2">Open</div>
          <div className="tk-cnum wt">{openCount}</div>
          <p className="hint">{oldest ? `oldest raised ${new Date(oldest).toLocaleDateString([], { weekday: "long" })}` : "nothing waiting"}</p>
        </div>
        <div className="card tk-count">
          <div className="p-cap2">Wrong numbers open</div>
          <div className="tk-cnum r">{openWrong}</div>
          <p className="hint">a figure that is lying is read by everybody until it is fixed</p>
        </div>
        <div className="card tk-count">
          <div className="p-cap2">Closed this month</div>
          <div className="tk-cnum ok">{closedThisMonth}</div>
          <p className="hint">{openBehind > 0 ? `${openBehind} still behind the standard` : "nobody flagged as behind"}</p>
        </div>
      </div>

      <div className="card">
        <div className="tk-head">
          <div className="p-cap2">Tickets</div>
          {[["open", "Open"], ["closed", "Closed"], ["all", "All"]].map(([id, lbl]) => (
            <button key={id} className={"tg-sub" + (filter === id ? " on" : "")} onClick={() => setFilter(id)}>{lbl}</button>
          ))}
          <span className="tk-div" />
          {[["all", "Everything"], ["figures", "Wrong numbers"], ["standard", "Behind"], ["problem", "Problems"]].map(([id, lbl]) => (
            <button key={id} className={"tg-sub" + (kind === id ? " on" : "")} onClick={() => setKind(id)}>{lbl}</button>
          ))}
          <span className="r-flex2" />
          <button className="pp-act" onClick={reload}>Refresh</button>
        </div>
        {items === null ? <p className="hint">Loading...</p>
          : shown.length === 0 ? <p className="hint">Nothing here. {filter === "open" ? "No open tickets." : ""}</p>
          : (
            <div className="tk-list">
              {shown.map((t) => (
                <div key={t.id} className={"tk" + ((t.status || "open") === "closed" ? " tk-closed" : "")
                  + (t.kind === "figures" ? " tk-wrong" : "") + (t.kind === "standard" ? " tk-behind" : "")}>
                  <div className="tk-top">
                    {(() => { const st = storeOf(t.store); return st
                      ? <span className="tk-store" title={st.name}>
                          <i style={{ background: (st.brand || DEFAULT_BRAND).primary }} />{st.name}
                        </span> : null; })()}
                    {t.kind === "figures" && <span className="tk-kind">number's wrong</span>}
                    {t.kind === "standard" && <span className="tk-kind tk-kind-behind">behind the standard</span>}
                    <b>{t.from || "Anonymous"}</b>
                    {t.reach && <a className="tk-reach" href={t.reach.includes("@") ? `mailto:${t.reach}` : `tel:${t.reach.replace(/[^\d+]/g, "")}`}>{t.reach}</a>}
                    <span className="tk-when">{t.at ? new Date(t.at).toLocaleString() : ""}</span>
                  </div>
                  {t.kind === "figures" && (
                    <div className="tk-fig">
                      <div className="tk-fig-line">
                        <span className="tk-fig-what">{t.figure === "__other" ? "Something on that screen" : (t.figure || "A figure")}</span>
                        <span className="tk-fig-vs">
                          {t.shown ? <>showing <b>{t.shown}</b></> : "value not captured"}
                          {t.expected ? <> · should be <b>{t.expected}</b></> : null}
                        </span>
                      </div>
                      {t.basis && <div className="tk-fig-basis">Their source: {t.basis}</div>}
                      {/* The rest of what was on that screen at that moment. A wrong
                          figure is rarely wrong alone, and this is usually where the
                          shape of the fault shows up. */}
                      {Array.isArray(t.snapshot) && t.snapshot.length > 0 && (
                        <details className="tk-snap">
                          <summary>Everything else on that screen ({t.snapshot.length})</summary>
                          <div className="tk-snap-rows">
                            {t.snapshot.map((f, i) => (
                              <div key={i} className={"tk-snap-row" + (f.label === t.figure ? " on" : "")}>
                                <span>{f.label}</span><b>{f.value}</b>
                              </div>
                            ))}
                          </div>
                        </details>
                      )}
                    </div>
                  )}
                  {/* Somebody who kept missing the bar, and what they said was stopping
                      them. Above the note rather than below it, because the note is
                      the answer to it and reads as thin without the question. */}
                  {t.kind === "standard" && (
                    <div className="tk-behind-head">
                      Missed the bar on <b>{t.missed}</b> of their last <b>{t.of}</b> days
                      {t.bar ? <> · the bar is {t.bar}</> : null}
                      {Array.isArray(t.days) && t.days.length > 0 && (
                        <span className="tk-behind-days">{t.days.map((d) => shortDay(d)).join(" · ")}</span>
                      )}
                    </div>
                  )}
                  {t.body && <p className="tk-body">{t.body}</p>}
                  <div className="tk-meta">
                    {t.store && <span>{t.store}</span>}
                    {t.context && <span>{t.context}</span>}
                    {t.page && <span className="tk-page">{t.page}</span>}
                  </div>
                  <div className="tk-actions">
                    {(t.status || "open") === "open"
                      ? <button className="btn-quiet" onClick={() => setStatus(t, "closed")}>Mark handled</button>
                      : <button className="btn-quiet" onClick={() => setStatus(t, "open")}>Reopen</button>}
                  </div>
                </div>
              ))}
            </div>
          )}
      </div>
    </div>
  );
}

/* ---------------- Claim your name ----------------
   Which store, and which name on its roster. The roster comes from the store's
   published board row, which is readable with no account at all, so this works
   on the sign-up screen before there is one. A store whose board has never been
   opened has no published roster; the person still names the store and types
   their name, and the manager picks the roster name when they join them. */
function ClaimPicker({ config, value, onChange, onName }) {
  const stores = (config && config.stores) || [];
  const [roster, setRoster] = useState(null);
  const store = value && value.store ? value.store : "";
  useEffect(() => {
    if (!store) { setRoster(null); return; }
    let dead = false;
    setRoster(null);
    loadShared(`lpc:board:${store}:v1`, null).then((b) => {
      if (dead) return;
      const list = (b && Array.isArray(b.roster) ? b.roster : []).filter((r) => r && r.id && r.name);
      setRoster(list.slice().sort((a, b2) => String(a.name).localeCompare(String(b2.name))));
    }).catch(() => { if (!dead) setRoster([]); });
    return () => { dead = true; };
  }, [store]);
  return (
    <>
      <label className="lf-label">Your store</label>
      <select className="lf-in lf-sel" value={store} onChange={(e) => onChange({ store: e.target.value, person: null, name: "" })}>
        <option value="">Pick your store…</option>
        {stores.map((st) => <option key={st.id} value={st.id}>{st.name}</option>)}
      </select>
      {store && roster === null && <p className="lf-kindnote">Reading the roster…</p>}
      {store && roster && roster.length > 0 && (
        <>
          <label className="lf-label">Your name on the roster</label>
          <select className="lf-in lf-sel" value={value.person || ""}
            onChange={(e) => {
              const r = roster.find((x) => x.id === e.target.value) || null;
              onChange({ store, person: r ? r.id : null, name: r ? r.name : "" });
              if (r && onName) onName(r.name);
            }}>
            <option value="">Pick your name…</option>
            {roster.map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
          </select>
        </>
      )}
      {store && roster && roster.length === 0 && (
        <p className="lf-kindnote">This store has not published its roster yet. Type your name below and your manager will match it.</p>
      )}
    </>
  );
}

/* ---------------- Login (real accounts) ---------------- */
function Login({ config, onBack, onAuthed, onHandover, onJump }) {
  const [mode, setMode] = useState("signin"); // signin | signup | forgot
  const [kind, setKind] = useState("associate");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [password2, setPassword2] = useState("");
  const [name, setName] = useState("");
  const [claim, setClaim] = useState({ store: "", person: null, name: "" });
  const [err, setErr] = useState("");
  const [ok, setOk] = useState("");
  const [busy, setBusy] = useState(false);
  /* The card's own 760ms deconstruction is gone with the handover it belonged
     to. The arrival takes the screen apart now, from the press, so there is
     nothing left here to run. */

  const domains = config.approvedDomains || [];
  const canRegister = config.registrationOpen && domains.length > 0;

  /* ---- the press starts the jump, and the network runs underneath it ----
     The jump used to wait for the sign-in call to come back, which is why it read
     as "loading first, then the animation". It starts on the press now, and the
     420ms hold and 520ms gather are spent while the request is in flight, so by
     the time the streaks are gone the answer is nearly always already here. Two
     things have to be true and are:

       if the sign-in FAILS, the jump is cancelled and the form comes back — the
       error is more important than the animation and arrives well inside the
       first beat

       if the sign-in is SLOW, the flash holds white until it lands rather than
       handing over to a screen that is not ready */
  const jumping = useRef(null);
  const markRef = useRef(null);
  const emailRef = useRef(null);
  const pwRef = useRef(null);
  /* null until a press finds the mark unfinished; see RUSH. */
  const [rushTyped, setRushTyped] = useState(null);
  const hurryBuild = (from) => {
    const t0 = (typeof performance !== "undefined" ? performance : Date).now();
    const step = () => {
      const now = (typeof performance !== "undefined" ? performance : Date).now();
      const p = Math.min(1, (now - t0) / RUSH);
      setRushTyped(from + (34 - from) * p);
      if (p < 1) rushRaf.current = requestAnimationFrame(step);
    };
    rushRaf.current = requestAnimationFrame(step);
  };
  /* ---- an autofill is typing too, as far as the mark is concerned ----
     A password manager sets both fields without React seeing a thing: no
     keystrokes, and in Chrome often no input event this component is mounted in
     time to hear. So `typed` stayed 0, the mark stayed dark, and the one piece of
     feedback this screen has did nothing for the people most likely to use it.

     The values are read back off the DOM instead of waited for — on mount, on
     the animation Chrome fires against :-webkit-autofill, and on a couple of
     ticks after that for the managers that fill late. Anything found is fed
     through the same rush the sign-in press uses, so the mark BUILDS to where the
     text is rather than snapping to it. */
  useEffect(() => {
    let done = false;
    const sync = () => {
      if (done) return;
      const e = emailRef.current, w = pwRef.current;
      const ev = e ? e.value : "", wv = w ? w.value : "";
      if (!ev && !wv) return;
      if (ev === email && wv === password) return;
      done = true;
      const was = Math.min(34, email.length + password.length);
      setEmail(ev); setPassword(wv);
      if (Math.min(34, ev.length + wv.length) > was) hurryBuild(was);
    };
    const onAnim = (ev) => { if (ev.animationName === "sageAutofill") sync(); };
    document.addEventListener("animationstart", onAnim, true);
    const ts = [0, 120, 400, 900].map((ms) => setTimeout(sync, ms));
    return () => {
      document.removeEventListener("animationstart", onAnim, true);
      ts.forEach(clearTimeout);
    };
  }, []); // eslint-disable-line
  const rushRaf = useRef(0);
  useEffect(() => () => cancelAnimationFrame(rushRaf.current), []);
  const heldRef = useRef(onJump);
  heldRef.current = onJump;
  const abortJump = () => {
    if (jumping.current) { jumping.current(); jumping.current = null; }
    if (heldRef.current) heldRef.current(false);
  };
  useEffect(() => () => { if (jumping.current) { jumping.current(); jumping.current = null; } }, []);

  const signIn = async () => {
    setErr(""); setOk("");
    if (!email.trim() || !password) { setErr("Enter your email and password."); return; }
    setBusy(true);
    signInPressed = true;
    /* ---- hold the screen for the length of the jump ----
       The sign-in call is not the only thing that brings the session in: the
       client fires SIGNED_IN the moment it succeeds, the app's own auth listener
       refreshes the profile off that, and the session lands about 300ms after the
       press — a quarter of the way into the hold. The root would then swap to the
       dashboard, this component would unmount, and the jump's cleanup would take
       every beat class with it. Measured: beats gone at 255ms, dashboard already
       up. That is the whole animation, over before the gather, which is why it
       looked like nothing happened.

       So the jump says when it is running and the root keeps the sign-in screen
       on until it says otherwise. The session can arrive whenever it likes. */
    if (onJump) onJump(true);
    /* Before anything moves: tell the ground where the mark is, so the field's
       streaks leave along lines drawn from the logo rather than from the middle
       of the frame. Measured here because here is the only place that knows. */
    tellJumpOrigin(markRef.current);
    /* A saved password fills both fields at once, so the mark is barely started
       when the button is pressed. Finish it first, and push the whole jump back
       by exactly as long as that takes: the streaks have to leave a whole word. */
    const short = typed < 34;
    if (short) hurryBuild(typed);
    let authed = null;                       // null = still in flight
    let flashed = false;
    let handedOver = false;
    const handOver = () => {
      if (handedOver || !flashed || authed !== true) return;
      handedOver = true;
      /* This is the frame the white is covering, and it is a handful of class
         names: the dashboard has been mounted and laid out since the hold. */
      if (onHandover) onHandover();
    };
    jumping.current = runJump({
      lead: short ? RUSH : 0,
      onFlash: () => {
        /* Nothing to hand over to yet: hold the flash rather than dropping back
           onto a sign-in screen that has already taken itself apart. */
        if (authed === null) document.documentElement.classList.add("sage-flash-hold");
      },
      onDone: () => { flashed = true; handOver(); },
    });
    /* A THROW has to land here as well as a returned error. It is not a
       hypothetical: the flash holds white while it waits for an answer, so an
       exception escaping this call leaves a white screen with nothing behind it
       and no way back. Anything that is not a clean success puts the form back. */
    let res;
    try {
      res = await authSignIn(email.trim().toLowerCase(), password);
    } catch (e) {
      res = { error: "Couldn't reach sign-in. Check your connection and try again." };
    }
    if (!res || res.error) {
      abortJump();
      signInPressed = false;
      document.documentElement.classList.remove("sage-flash-hold");
      authed = false;
      setBusy(false); setErr((res && res.error) || "Sign-in didn't complete. Try again.");
      return;
    }
    authed = true;
    document.documentElement.classList.remove("sage-flash-hold");
    /* From here the only thing between the user and the page is the white, so
       nothing on this path is allowed to throw its way out of the handover. */
    /* Load the profile NOW, not at the handover. The screen is held for the rest
       of the jump either way, so the fetch costs nothing here and everything
       there: gating the swap on a round trip that only starts at the handover put
       the dashboard on screen most of a second after the flash had been asked
       for, which is far too late for the flash to cover it. By the time the white
       is up the session is already in hand and the swap is a state flip. */
    try { await onAuthed(); } catch (e) { console.error("profile load at handover", e); }
    handOver();
  };

  const signUp = async () => {
    setErr(""); setOk("");
    const e = email.trim().toLowerCase();
    if (!e.includes("@")) { setErr("Enter a valid email."); return; }
    if (!name.trim()) { setErr("Enter your full name."); return; }
    if (password.length < 8) { setErr("Password must be at least 8 characters."); return; }
    if (password !== password2) { setErr("The two passwords do not match."); return; }
    // The very first account created becomes the admin, so it is not domain-gated.
    const domainOf = (addr) => String(addr).split("@")[1] || "";
    if (domains.length > 0 && !domains.includes(domainOf(e))) {
      setErr("Email must be on an approved company domain (" + domains.join(", ") + ").");
      return;
    }
    if (kind === "associate" && !claim.store && (config.stores || []).length > 0) { setErr("Pick your store."); return; }
    setBusy(true);
    const res = await authSignUp(e, password, name.trim(), kind, kind === "associate" ? claim : null);
    setBusy(false);
    if (res.error) { setErr(res.error); return; }
    setOk("Account created.");
    onAuthed();
  };

  const forgot = async () => {
    setErr(""); setOk("");
    const e = email.trim().toLowerCase();
    if (!e.includes("@")) { setErr("Enter your email first."); return; }
    setBusy(true);
    const res = await authResetPassword(e);
    setBusy(false);
    if (res.error) { setErr(res.error); return; }
    setOk("If that email has an account, a reset link is on its way. Check your inbox.");
  };

  /* ---- the mark builds as the form is filled ----
     73 dots against 34 characters of email and password. Driven off the real
     input values rather than off keystrokes, so a password manager filling both
     fields in one go lands where a person typing them lands. */
  const typed = Math.min(34, email.length + password.length);
  /* While the hurry is running the count comes from it rather than from the
     fields, so the mark finishes drawing itself under its own steam. */
  const shownTyped = rushTyped === null ? typed : rushTyped;
  const revealed = Math.round((shownTyped / 34) * 73);
  const filled = Math.min(5, Math.round((shownTyped / 34) * 5));

  return (
    <div className="login">
      {/* The field belongs to this screen and lives as long as it does: held for
          the whole jump, gone with it at the handover, underneath the white. */}
      <SageField />
      <div className={"login-card " + (busy ? "login-busy" : "")}>
        <p className="login-eyebrow">{greetingFor()}</p>
        {/* No spinner here any more. Signing in used to swap the wordmark for a
            loading indicator, which is a different object appearing in the place
            of the thing you were looking at. The mark stays and goes to work
            instead: the same 73 dots, running a wave left to right. */}
        <div className="login-logo" ref={markRef}>
          {/* Still driven by `revealed` while signing in, because the hurry is
              what finishes the drawing — dropping it on press would snap the
              rest of the word in and there would be nothing to hurry. */}
          <SageMark word size={64} revealed={mode === "signin" ? revealed : undefined} />
        </div>

        {!AUTH_ENABLED && <p className="setup-note">This is a preview. Real sign-in works on the hosted site.</p>}

        {/* Each mode's fields live in a keyed container so switching modes
            remounts it and plays the entrance: the fields build up from below in
            the same vocabulary as everything else here. The mark above never
            moves — it belongs to all three. */}
        {mode === "signin" && (
          <div className="lf-mode" key="signin">
            <label className="lf-label">Work email</label>
            <input className="lf-in" ref={emailRef} value={email} onChange={(e) => { setEmail(e.target.value); setErr(""); }}
              placeholder="you@company.com" autoComplete="username" />
            <label className="lf-label lf-label-row">
              Password
              {/* Inline on the label row, where the eye already is when the field
                  is the thing that went wrong. */}
              <button type="button" className="lf-forgot"
                onClick={() => { setMode("forgot"); setErr(""); setOk(""); }}>Forgot?</button>
            </label>
            <input className="lf-in" ref={pwRef} type="password" value={password} onChange={(e) => { setPassword(e.target.value); setErr(""); }}
              onKeyDown={(e) => e.key === "Enter" && signIn()} placeholder="Your password" autoComplete="current-password" />
            {err && <div className="login-err">{err}</div>}
            {ok && <div className="login-ok">{ok}</div>}
            {/* The five dots fill on the same ratio the mark builds on, so the
                button and the mark are two readings of one thing. */}
            <button className="lf-go" onClick={signIn} disabled={busy}>
              <span>{busy ? "Signing in\u2026" : "Sign in"}</span>
              <span className="lf-dots">
                {[0, 1, 2, 3, 4].map((i) => <i key={i} className={i < filled ? "on" : ""} />)}
              </span>
            </button>
            <button className="lf-alt" onClick={() => { setMode("signup"); setErr(""); setOk(""); setPassword(""); }}>Create New Account</button>
            {onBack && <button className="btn-link" onClick={onBack}>&larr; Back to start</button>}
          </div>
        )}

        {/* ---- the other two modes speak the same vocabulary ----
            They were still bare <label> and <input>, which pick up the app's
            general bordered field, and a .btn wide where the sign-in has its
            pill. Two thirds of the way into somebody's first minute with the
            product they hit Create Account and the screen changed style under
            them. Same labels, same underline fields, same pill, same quiet
            secondary link — the only difference between the three modes is which
            fields are on screen. */}
        {mode === "signup" && (
          <div className="lf-mode" key="signup">
            <p className="lf-note">
              {canRegister
                ? "Create your account. What happens next depends on which of these you are."
                : "Create your account. Heads up: the very first account created becomes the group admin."}
            </p>
            {/* Asked first, because the answer changes what the rest of this
                screen is promising. */}
            <label className="lf-label">What do you do here</label>
            <div className="lf-kinds">
              {Object.entries(ACCOUNT_KINDS).map(([k, v]) => (
                <button key={k} type="button" className={"lf-kind" + (kind === k ? " on" : "")}
                  onClick={() => { setKind(k); setErr(""); }} aria-pressed={kind === k}>
                  {v.label}
                </button>
              ))}
            </div>
            <p className="lf-kindnote">
              {kind === "manager"
                ? "Your group admin grants you the stores you look after. You will see the dashboard once they do."
                : "You do not need the dashboard. Say which store and which name is yours; your manager joins the two with one tap, and then the line, your standards and your day show up on your phone."}
            </p>
            {kind === "associate" && (
              <ClaimPicker config={config} value={claim} onChange={(c) => { setClaim(c); setErr(""); }}
                onName={(nm) => { if (!name.trim()) setName(nm); }} />
            )}
            <label className="lf-label">Work email</label>
            <input className="lf-in" value={email} onChange={(e) => { setEmail(e.target.value); setErr(""); }}
              placeholder="you@company.com" autoComplete="username" />
            <label className="lf-label">Full name</label>
            <input className="lf-in" value={name} onChange={(e) => { setName(e.target.value); setErr(""); }} placeholder="First Last" />
            <label className="lf-label">Password</label>
            <input className="lf-in" type="password" value={password} onChange={(e) => { setPassword(e.target.value); setErr(""); }}
              placeholder="At least 8 characters" autoComplete="new-password" />
            <label className="lf-label">Confirm password</label>
            <input className="lf-in" type="password" value={password2} onChange={(e) => { setPassword2(e.target.value); setErr(""); }}
              onKeyDown={(e) => e.key === "Enter" && signUp()} placeholder="Repeat it" autoComplete="new-password" />
            {err && <div className="login-err">{err}</div>}
            {ok && <div className="login-ok">{ok}</div>}
            <button className="lf-go lf-solo" onClick={signUp} disabled={busy}>
              <span>{busy ? "Creating\u2026" : "Create account"}</span>
            </button>
            <button className="lf-alt" onClick={() => { setMode("signin"); setErr(""); setPassword(""); setPassword2(""); }}>Back to sign in</button>
          </div>
        )}

        {mode === "forgot" && (
          <div className="lf-mode" key="forgot">
            <p className="lf-note">Enter your email and we will send a link to set a new password.</p>
            <label className="lf-label">Work email</label>
            <input className="lf-in" value={email} onChange={(e) => { setEmail(e.target.value); setErr(""); }}
              onKeyDown={(e) => e.key === "Enter" && forgot()} placeholder="you@company.com" />
            {err && <div className="login-err">{err}</div>}
            {ok && <div className="login-ok">{ok}</div>}
            <button className="lf-go lf-solo" onClick={forgot} disabled={busy}>
              <span>{busy ? "Sending\u2026" : "Send reset link"}</span>
            </button>
            <button className="lf-alt" onClick={() => { setMode("signin"); setErr(""); setOk(""); }}>Back to sign in</button>
          </div>
        )}
      </div>
    </div>
  );
}

/* ---------------- Switching tools ----------------
   300ms of streaks in the tool you are going TO, travelling the way the eye just
   moved: right if the new tool sits right of the old one in the bar, left if it
   sits left. The outgoing screen unmounts and the new one mounts fresh, so its
   own entrance plays underneath.

   Written against the DOM rather than through React on purpose. A tool switch
   already unmounts and remounts a large tree, and putting 34 streaks through
   state at the same moment would put the animation in the same frame budget as
   the mount it is covering — which is exactly what it exists to hide.

   The hue is the tool's own accent, taken from the app rather than from the
   handoff's table. The handoff calls those "the existing pill colours" and lists
   values that are close to but not the same as the ones in this file; the pill
   the finger just left is the thing the eye is carrying, so the app's own value
   is the one that matches it. */
const WARP_ORDER = ["perf", "activity", "board", "floor", "line", "online"];
/* How long the outgoing page has to leave before the streaks cross. It is not a
   taste number: the last staggered block starts at 66ms and its exit runs 190ms,
   so anything below 256 cuts a block off mid-exit, and a block that vanishes
   halfway through leaving is exactly what reads as a flicker. */
const TOOL_EXIT = 260;
let toolTimers = [];
/* Cards fade up as they scroll into view, and until the observer has marked one
   it sits at opacity 0. A block that has just been animated into place has not
   been through that yet, so the frame after a move ended it could drop straight
   back out — a landing followed by a blink. Anything on screen when a move
   finishes is, by definition, in view: say so before letting go of it. */
function settleReveals() {
  if (typeof document === "undefined") return;
  const h = window.innerHeight || 0;
  document.querySelectorAll(".card:not(.is-in), .reveal:not(.is-in)").forEach((el) => {
    const r = el.getBoundingClientRect();
    if (r.top < h && r.bottom > 0) el.classList.add("is-in");
  });
}
function clearToolMove() {
  toolTimers.forEach(clearTimeout);
  toolTimers = [];
  if (typeof document === "undefined") return;
  settleReveals();
  document.documentElement.classList.remove("tool-move", "tool-exit", "tool-enter", "tool-dir-r", "tool-dir-l");
}
const WARP_HUE = { perf: "#404E44", activity: "#404E44", board: "#404E44",
  floor: "#10B981", line: "#5566F0", online: "#8B5CF6" };

function warpTo(from, to) {
  if (typeof document === "undefined") return;
  try {
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  } catch (e) { /* no matchMedia is not a reason to skip it */ }
  const dir = WARP_ORDER.indexOf(to) >= WARP_ORDER.indexOf(from) ? "r" : "l";
  const hue = WARP_HUE[to] || "#404E44";
  const host = document.createElement("div");
  host.className = "warp warp-" + dir;
  const h = window.innerHeight;
  let html = "";
  for (let i = 0; i < 34; i++) {
    const len = 180 + ((i * 137) % 520);          // 180-700px
    const tall = 2 + ((i * 7) % 3);               // 2-4px
    const top = Math.round(((i * 617) % 1000) / 1000 * h);
    const delay = (i * 31) % 132;                 // 0-132ms
    html += `<i style="top:${top}px;width:${len}px;height:${tall}px;background:${hue};animation-delay:${delay}ms"></i>`;
  }
  host.innerHTML = html;
  document.body.appendChild(host);
  setTimeout(() => host.remove(), 520);
}

/* ---------------- The arrival ----------------
   Press Sign in and the mark gathers, every dot of it stretches into a streak
   past the frame, a flash covers the snap, and the dashboard builds outward from
   the centre. 2.7 seconds, once a day.

   ---- what this replaces ----
   The app already played a cinematic on the first sign-in of each calendar day,
   keyed the same way, per device and per person. Jorge chose to replace it: two
   of them would be a minute of animation before anybody sees a number, and the
   old one ended by drawing a stand-in dashboard that this one does not need
   because it hands over to the real one.

   ---- why the streaks pin at the near end ----
   Each dot's wrapper is rotated to its own angle out of the mark's centre with
   the origin at the near end, and scaled along X. There is no translate: the
   near end stays exactly where the dot was, so nothing detaches from the mark
   and re-attaches somewhere else. The layer around them carries them off frame.

   ---- and why no will-change ----
   Straight from the handoff, which found it the expensive way: scaling a 10px
   dot to 177x with will-change made the browser hold every streak as a promoted
   layer at its full scaled extent. 1664ms stall against a 21ms median without.
   ------------------------------------------------------------------- */
/* The store this browser was last working in. Only stores: see the note where it
   is read. */
const LAST_VIEW_KEY = "lpc:last-view";
function lastView() {
  try { return localStorage.getItem(LAST_VIEW_KEY) || null; } catch (e) { return null; }
}
function rememberView(v) {
  if (!v || v === "admin" || v === "combined") return;
  try { localStorage.setItem(LAST_VIEW_KEY, v); } catch (e) {}
}

const ARRIVAL = { hold: 420, gather: 520, stretch: 880, flash: 420, assemble: 1400 };
/* The new arrival's clock. cruiseMin is the shortest stay in the tunnel even on
   an instant load, so the destination sign gets long enough on screen to be
   read. cruiseCap is the honest ceiling: if the store has not answered by then,
   the jump lands anyway — onto whatever screen the app has to show about it
   (the stuck screen, the mismatch panel), because a tunnel that never ends is a
   spinner with better art. */
const JUMP_T = { ratchet: 620, reform: 840, streaks: 800, cruiseMin: 1400, cruiseCap: 15000, burst: 520 };

/* ---- what the jump is waiting for, and where it is going ----
   Told by the root, read by the engine each frame of the cruise. Module state
   for the same reason lastJumpOrigin is: the engine lives outside React so the
   handover cannot tear it down mid-flight. */
let arrivalReady = false;
let arrivalDest = null;   // { name, color } for the travel sign, or null
/* The engine announces its beats so the root can schedule the expensive work
   into the right one: the dashboard mounts during the CRUISE, which is the
   loading zone, instead of during the ratchet, which is the most watched
   moment of the whole animation. */
const JUMP_PHASE = "sage-jump-phase";
const tellPhase = (ph) => {
  try { document.dispatchEvent(new CustomEvent(JUMP_PHASE, { detail: ph })); } catch (e) {}
};
let activeEngineSend = null;   // set by runJump while a jump is flying
function tellArrivalReady(ready, dest) {
  arrivalReady = !!ready;
  if (dest !== undefined) arrivalDest = dest;
  if (activeEngineSend) {
    activeEngineSend({ type: "ready", ready: arrivalReady });
    activeEngineSend({ type: "dest", dest: arrivalDest });
  }
}
/* ---- every time, not once a day ----
   The handoff asked for the first sign-in of the day, like the morning round-up,
   and Jorge changed it: it plays on every arrival now. So there is no stored key
   and nothing to reset — which also means it plays on a page RELOAD, because a
   reload restores the session and that is an arrival as far as this app is
   concerned. That is the honest reading of "every time"; if a refresh at the
   desk should go straight in, the trigger moves from "a session appeared" to
   "the sign-in button was pressed" and this comment is where to start. */

/* ---- the jump runs ON the sign-in screen, not over it ----
   The first build of this was a fixed, opaque panel at z-index 9000 with its own
   360px copy of the wordmark at dead viewport centre. It painted over the sign-in
   screen the instant the button was pressed, so the form never faded, the dot
   field and the blobs never gathered, and the streaks fired from the middle of
   the frame off a mark that was neither the size nor in the place of the one the
   eye was on. Nothing of the sign-in screen ever left, because nothing of it was
   ever in the animation.

   So there is no overlay any more. The beats are classes on the document, and
   every rule they carry points at the real elements: the real form fades, the
   real dot field and the real blobs pull in and blow out, and the streaks are the
   real mark's own dots, where they sit, at the size they are. What is left here
   is only the clock.

   The white flash is the one piece that cannot live on this screen, because the
   sign-in screen is gone by the time it peaks: it is mounted at the root, where
   the ground is, for the same reason. */
/* ---- the hurry ----
   The handoff's first beat, and the one this file never had. A saved password
   fills both fields in one go, so the mark is nowhere near drawn when the button
   is pressed — and the streaks have to start from a finished mark, not half a
   word. So the build is rushed to the end first, and every beat after it is
   pushed back by the same 320ms. The table says as much: "Hurry | 0 | 320ms | Only
   if the form is not finished", and "add 320ms to every figure when the hurry runs
   first". */
const RUSH = 320;
/* ---- the arrival engine's core ----
   Every moving dot of the jump, drawn from one self-contained function. Self-
   contained is load-bearing: this function is stringified and run inside a
   Worker against an OffscreenCanvas, so the tunnel keeps flowing at full frame
   rate while the main thread mounts the dashboard — the "slow down in the
   middle of the animation" was exactly that mount freezing a main-thread
   canvas. It must not touch the DOM and must not reference anything outside
   its own arguments. The same function drives the main-thread fallback where
   OffscreenCanvas does not exist, so there is one copy of this math, ever.

   ctx: a 2d context (offscreen or not). world: geometry measured at the press.
   post(type, data): reports "phase" and "flash" back to the driver. */
function arrivalEngineCore(ctx, world, post) {
  const { W, H, dpr, T, FP, mk, field, tunnel, font } = world;
  const cx = W / 2, cy = H / 2;
  const maxR = Math.hypot(W, H) / 2 + 160;
  ctx.scale(dpr, dpr);
  const pow = (p, k) => Math.pow(Math.min(1, Math.max(0, p)), k);
  const ease = (p) => 1 - Math.pow(1 - Math.min(1, Math.max(0, p)), 3);
  const easeInOut = (p) => (p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2);

  let phase = "ratchet", t0 = 0, lastNow = 0, cruiseT0 = 0, burstT0 = 0;
  let ready = false, dest = null, done = false;

  const drawTunnel = (dt, S) => {
    for (const q of tunnel) {
      if (q.wait > 0) { q.wait -= dt * Math.max(1, S * 0.6); continue; }
      if (q.r <= maxR) {
        q.r += (40 + q.r * 2.1) * S * q.v * dt;
        q.t = Math.max(0, q.r - (200 + q.size * 55));
      } else {
        q.t += (30 + q.t * 1.9) * S * q.v * dt * 1.7;
        if (q.t > maxR) {
          q.ang = Math.random() * Math.PI * 2; q.r = 2; q.t = 0;
          q.wait = Math.random() * 1.1; q.v = 0.55 + Math.random() * 0.9;
          continue;
        }
      }
      const ux = Math.cos(q.ang), uy = Math.sin(q.ang);
      const head = Math.min(q.r, maxR);
      ctx.globalAlpha = Math.min(0.85, q.r / 70);
      ctx.strokeStyle = q.tint; ctx.lineWidth = q.size; ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(cx + ux * q.t, cy + uy * q.t);
      ctx.lineTo(cx + ux * head, cy + uy * head);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  };

  const drawSign = (now, mode) => {
    if (!dest || !dest.name) return;
    let scale = 1, alpha = 1;
    if (mode === "cruise") {
      alpha = Math.min(1, (now - cruiseT0) / 400);
      scale = 0.82 + 0.18 * ease(Math.min(1, (now - cruiseT0) / 1600)) + 0.012 * Math.sin(now / 420);
    } else {
      const p = pow((now - burstT0) / (T.burst * 0.7), 1.6);
      scale = 1 + p * 1.9; alpha = Math.max(0, 1 - p);
    }
    if (alpha <= 0) return;
    const color = dest.color || "#2F7F72";
    ctx.save(); ctx.translate(cx, cy); ctx.scale(scale, scale); ctx.globalAlpha = alpha;
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 190);
    g.addColorStop(0, color + "3A"); g.addColorStop(1, color + "00");
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, 190, 0, 7); ctx.fill();
    ctx.font = "600 24px " + font;
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    const tw = ctx.measureText(dest.name).width, padX = 26, h = 52, w = tw + padX * 2;
    ctx.shadowColor = color + "66"; ctx.shadowBlur = 26;
    ctx.fillStyle = color;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(-w / 2, -h / 2, w, h, h / 2);
    else ctx.rect(-w / 2, -h / 2, w, h);
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = "#FFFFFF";
    ctx.fillText(dest.name, 0, 1);
    ctx.restore(); ctx.globalAlpha = 1;
  };

  const drawFieldDots = (pull) => {
    for (const d of field) {
      const x = cx + (d.x - cx) * (1 - pull), y = cy + (d.y - cy) * (1 - pull);
      ctx.globalAlpha = Math.min(1, 0.26 + pull * 0.8);
      ctx.fillStyle = d.tint;
      ctx.beginPath(); ctx.arc(x, y, d.size / 2, 0, 7); ctx.fill();
    }
    ctx.globalAlpha = 1;
  };

  const tick = (now) => {
    if (done) return;
    if (!t0) { t0 = now + (world.lead || 0); lastNow = now; }
    /* A long gap between frames means the thread was taken (only possible in
       the main-thread fallback). Hold the clocks rather than skipping. */
    const lost = now - lastNow;
    if (lost > 120) {
      const shift = lost - 16;
      t0 += shift; if (cruiseT0) cruiseT0 += shift; if (burstT0) burstT0 += shift;
    }
    const dt = Math.min(0.05, (now - lastNow) / 1000);
    lastNow = now;
    const t = now - t0;
    if (t < 0) return;   // the hurry's lead
    ctx.clearRect(0, 0, W, H);

    if (phase === "ratchet") drawFieldDots(0);
    else if (phase === "reform") drawFieldDots(ease(t / T.reform) * FP);
    else if (phase === "streaks") {
      const p = t / T.streaks;
      const mR = Math.hypot(W, H) / 2 + 120;
      for (const d of field) {
        /* Each dot on its own WIDE clock: departures scatter across half the
           beat, so the endings scatter just as far — nothing leaves or finishes
           in formation. */
        const pd = Math.min(1, Math.max(0, (p - d.jit * 0.5) / 0.5));
        const dx = d.x - cx, dy = d.y - cy, dist = Math.hypot(dx, dy) || 1;
        const ux = dx / dist, uy = dy / dist;
        const r0 = dist * (1 - FP);
        if (pd <= 0) {
          ctx.fillStyle = d.tint; ctx.globalAlpha = 1;
          ctx.beginPath(); ctx.arc(cx + ux * r0, cy + uy * r0, d.size / 2, 0, 7); ctx.fill();
          continue;
        }
        const pFar = pow(Math.min(1, pd / 0.62), 1.7);
        const pNear = pow(Math.max(0, (pd - 0.38) / 0.62), 2.0);
        const rNear = r0 + pNear * (mR - r0), rFar = r0 + 2 + pFar * (mR - r0);
        if (rNear >= rFar) continue;
        ctx.globalAlpha = 1;
        ctx.strokeStyle = d.tint; ctx.lineWidth = d.size; ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(cx + ux * rNear, cy + uy * rNear);
        ctx.lineTo(cx + ux * rFar, cy + uy * rFar);
        ctx.stroke();
      }
      if (p > 0.45) drawTunnel(dt, 0.6 * ((p - 0.45) / 0.55));
      /* the mark leaves the same way, each dot at its own moment */
      const mRk = mR;
      for (const d of mk) {
        const pd = Math.min(1, Math.max(0, (p - d.jit * 0.45) / 0.55));
        const dx = d.sx - cx, dy = d.sy - cy, dist = Math.hypot(dx, dy) || 1;
        const ux = dx / dist, uy = dy / dist;
        if (pd <= 0) {
          ctx.fillStyle = d.fill;
          ctx.beginPath(); ctx.arc(d.sx, d.sy, d.sr, 0, 7); ctx.fill();
          continue;
        }
        const pFar = pow(Math.min(1, pd / 0.55), 1.6);
        const pNear = pow(Math.max(0, (pd - 0.3) / 0.7), 2.0);
        const rNear = dist + pNear * (mRk - dist), rFar = dist + 2 + pFar * (mRk - dist);
        if (rNear >= rFar) continue;
        ctx.strokeStyle = d.fill; ctx.lineWidth = d.sr * 2; ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(cx + ux * rNear, cy + uy * rNear);
        ctx.lineTo(cx + ux * rFar, cy + uy * rFar);
        ctx.stroke();
      }
    } else if (phase === "cruise") {
      drawTunnel(dt, 1);
      drawSign(now, "cruise");
    } else if (phase === "burst") {
      drawTunnel(dt, 1 + pow(t / T.burst, 1.6) * 7);
      drawSign(now, "burst");
    }

    if (phase === "ratchet" && mk.length && t <= T.ratchet) {
      const p = t / T.ratchet;
      for (const d of mk) {
        const w = p * 1.35 - d.delay * 0.35;
        const k = Math.max(0, Math.sin(Math.min(1, Math.max(0, w)) * Math.PI));
        ctx.fillStyle = d.fill;
        ctx.beginPath(); ctx.arc(d.hx + k * 2.5, d.hy, d.hr * (1 + k * 0.5), 0, 7); ctx.fill();
      }
    } else if (phase === "reform" && mk.length) {
      const p = t / T.reform;
      for (const d of mk) {
        const lp = easeInOut(Math.min(1, Math.max(0, (p - d.delay * 0.3) / 0.7)));
        const mx = (d.hx + d.sx) / 2, my = Math.max(d.hy, d.sy) + 90;
        const ix = (1 - lp) * (1 - lp) * d.hx + 2 * (1 - lp) * lp * mx + lp * lp * d.sx;
        const iy = (1 - lp) * (1 - lp) * d.hy + 2 * (1 - lp) * lp * my + lp * lp * d.sy;
        ctx.fillStyle = d.fill;
        ctx.beginPath(); ctx.arc(ix, iy, d.hr + (d.sr - d.hr) * lp, 0, 7); ctx.fill();
      }
    }

    if (phase === "ratchet" && t >= T.ratchet) { phase = "reform"; t0 = now; post("phase", "reform"); }
    else if (phase === "reform" && t >= T.reform) { phase = "streaks"; t0 = now; post("phase", "streaks"); }
    else if (phase === "streaks" && t >= T.streaks) { phase = "cruise"; t0 = now; cruiseT0 = now; post("phase", "cruise"); }
    else if (phase === "cruise") {
      const tc = now - cruiseT0;
      if ((ready && tc >= T.cruiseMin) || tc >= T.cruiseCap) {
        phase = "burst"; t0 = now; burstT0 = now; post("phase", "burst");
      }
    } else if (phase === "burst" && t >= T.burst) { done = true; post("flash"); }
  };

  return {
    tick,
    msg: (m) => {
      if (m.type === "ready") ready = !!m.ready;
      if (m.type === "dest") dest = m.dest;
      if (m.type === "stop") done = true;
    },
  };
}

function runJump({ onFlash, onDone, lead = 0 }) {
  /* The driver. Measures the world at the press, hands the drawing to
     arrivalEngineCore — inside a Worker with an OffscreenCanvas wherever the
     browser has one, so the tunnel keeps its frame rate while the main thread
     mounts the dashboard — and keeps for itself the two jobs a worker cannot
     do: choreographing the DOM (the card's fade, the clouds' pull and blow-out)
     and the flash handover. */
  const root = typeof document === "undefined" ? null : document.documentElement;
  if (!root) { onFlash(); onDone(); return () => {}; }
  let reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  } catch (e) {}
  if (reduce) {
    tellPhase("cruise");
    const t = setTimeout(() => { onFlash(); onDone(); }, 180);
    return () => clearTimeout(t);
  }
  jumpOwnsEntrance = true;
  jumpLanded = false;

  const W = window.innerWidth, H = window.innerHeight;
  const cx = W / 2, cy = H / 2;
  lastJumpOrigin = { x: cx, y: cy };
  root.style.setProperty("--jx", cx + "px");
  root.style.setProperty("--jy", cy + "px");

  /* ---- the mark, measured where it actually sits ---- */
  const gWord = sageDots({ word: true });
  let mk = [];
  if (lastMarkEl) {
    const mr = lastMarkEl.getBoundingClientRect();
    const scale = Math.min(mr.width / gWord.w, mr.height / gWord.h) || 1;
    const ox = mr.left + (mr.width - gWord.w * scale) / 2;
    const oy = mr.top + (mr.height - gWord.h * scale) / 2;
    const gS = sageDots({ word: false });
    const seatScale = scale * 0.62;
    const seats = gS.dots.map((d) => ({
      x: cx + (d.x - gS.w / 2) * seatScale,
      y: cy + (d.y - gS.h / 2) * seatScale,
      r: d.r * seatScale,
    })).sort((a, b) => a.x - b.x || a.y - b.y);
    const home = gWord.dots.map((d) => ({ x: ox + d.x * scale, y: oy + d.y * scale, r: d.r * scale, fill: d.fill }))
      .sort((a, b) => a.x - b.x || a.y - b.y);
    const spanX = (home[home.length - 1].x - home[0].x) || 1;
    mk = home.map((d, i) => {
      const seat = seats[Math.round((i * (seats.length - 1)) / (home.length - 1))] || { x: cx, y: cy, r: d.r };
      return { hx: d.x, hy: d.y, hr: d.r, fill: d.fill,
        sx: seat.x, sy: seat.y, sr: seat.r,
        delay: (d.x - home[0].x) / spanX, jit: Math.random() };
    });
  }

  /* ---- the field: the page's own grid, continued past every edge ---- */
  const field = [];
  {
    let i = 0;
    for (let y = GROUND_PITCH / 2; y < H; y += GROUND_PITCH)
      for (let x = GROUND_PITCH / 2; x < W; x += GROUND_PITCH) {
        const bright = i % 3 === 0;
        field.push({ x, y, size: bright ? 4.4 : 2.6, tint: GROUND_TINTS[i % GROUND_TINTS.length], jit: Math.random() });
        i++;
      }
    const padX = W * 0.5, padY = H * 0.5;
    for (let y = GROUND_PITCH / 2 - padY; y < H + padY; y += GROUND_PITCH)
      for (let x = GROUND_PITCH / 2 - padX; x < W + padX; x += GROUND_PITCH) {
        if (x > 0 && x < W && y > 0 && y < H) continue;
        const bright = i % 3 === 0;
        field.push({ x, y, size: bright ? 4.4 : 2.6, tint: GROUND_TINTS[i % GROUND_TINTS.length], jit: Math.random() });
        i++;
      }
  }

  /* ---- the tunnel: seeded mid-life so the sky starts in steady state ---- */
  const maxR = Math.hypot(W, H) / 2 + 160;
  const tunnel = [];
  {
    const n = Math.round((W * H) / 7800);
    for (let i = 0; i < n; i++) {
      const waiting = Math.random() < 0.18;
      const r = waiting ? 2 : Math.pow(Math.random(), 1.7) * maxR;
      tunnel.push({
        ang: Math.random() * Math.PI * 2, r,
        t: Math.max(0, r - (200 + Math.random() * 160)),
        wait: waiting ? Math.random() * 0.9 : 0,
        v: 0.55 + Math.random() * 0.9,
        size: 1.4 + Math.random() * 2.2,
        tint: GROUND_TINTS[Math.floor(Math.random() * GROUND_TINTS.length)],
      });
    }
  }

  const cv = document.createElement("canvas");
  cv.className = "sage-jump-canvas";
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  cv.style.width = W + "px"; cv.style.height = H + "px";
  document.body.appendChild(cv);
  root.classList.add("sage-cv");

  const card = document.querySelector(".login-card");
  const blobs = Array.from(document.querySelectorAll(".sg-blob")).map((el) => {
    const r = el.getBoundingClientRect();
    const bx = r.left + r.width / 2, by = r.top + r.height / 2;
    const dx = bx - cx, dy = by - cy, dist = Math.hypot(dx, dy) || 1;
    return { el, ux: dx / dist, uy: dy / dist };
  });
  const restoreDom = () => {
    if (card) { card.style.opacity = ""; card.style.transform = ""; }
    for (const b of blobs) { b.el.style.transform = ""; b.el.style.opacity = ""; }
  };
  const bodyFont = (() => {
    try { return getComputedStyle(document.body).fontFamily || "sans-serif"; }
    catch (e) { return "sans-serif"; }
  })();

  const world = { W, H, dpr, T: JUMP_T, FP: 0.5, mk, field, tunnel, font: bodyFont, lead };

  let flashing = false, stopped = false, raf = 0, domRaf = 0;
  let worker = null, engine = null;

  const toFlash = () => {
    if (flashing || stopped) return;
    flashing = true;
    activeEngineSend = null;
    restoreDom();
    root.classList.add("sage-beat-flash");
    root.classList.remove("sage-cv");
    if (worker) { try { worker.terminate(); } catch (e) {} worker = null; }
    if (cv.parentNode) cv.parentNode.removeChild(cv);
    onFlash();
    let frames = 0;
    const painted = () => {
      if (stopped) return;
      if (++frames < 2) { requestAnimationFrame(painted); return; }
      setTimeout(() => { if (!stopped) onDone(); }, 20);
    };
    requestAnimationFrame(painted);
  };

  const onPost = (type, data) => {
    if (stopped) return;
    if (type === "phase") tellPhase(data);
    else if (type === "flash") toFlash();
  };

  /* Worker where the browser has one; the same core on the main thread where
     it does not. Either way the maths exists once. */
  let usingWorker = false;
  try {
    if (typeof OffscreenCanvas !== "undefined" && cv.transferControlToOffscreen && typeof Worker !== "undefined") {
      const off = cv.transferControlToOffscreen();
      const src = "let eng=null;self.onmessage=function(e){var m=e.data;" +
        "if(m.type==='init'){var ctx=m.canvas.getContext('2d');" +
        "var core=(" + arrivalEngineCore.toString() + ");" +
        "eng=core(ctx,m.world,function(t,d){self.postMessage({type:t,data:d});});" +
        "var loop=function(now){if(!eng)return;eng.tick(now);requestAnimationFrame(loop);};" +
        "requestAnimationFrame(loop);}else if(eng){eng.msg(m);}};";
      worker = new Worker(URL.createObjectURL(new Blob([src], { type: "text/javascript" })));
      worker.onmessage = (e) => onPost(e.data.type, e.data.data);
      worker.postMessage({ type: "init", canvas: off, world }, [off]);
      usingWorker = true;
    }
  } catch (e) { try { if (worker) worker.terminate(); } catch (e2) {} worker = null; usingWorker = false; }
  if (!usingWorker) {
    const ctx = cv.getContext("2d");
    engine = arrivalEngineCore(ctx, world, onPost);
    const loop = (now) => {
      if (stopped || flashing) return;
      engine.tick(now);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
  }
  activeEngineSend = (m) => {
    if (worker) worker.postMessage(m);
    else if (engine) engine.msg(m);
  };
  activeEngineSend({ type: "ready", ready: arrivalReady });
  activeEngineSend({ type: "dest", dest: arrivalDest });

  /* ---- the DOM's own choreography, on a matching clock ----
     The card's fade and the clouds' pull and blow-out are DOM work, which a
     worker cannot touch. They run here, done before the cruise begins — which
     is exactly why the dashboard mount was moved INTO the cruise: by then the
     main thread has nothing visual left to animate. */
  const ease3 = (p) => 1 - Math.pow(1 - Math.min(1, Math.max(0, p)), 3);
  const pw = (p, k) => Math.pow(Math.min(1, Math.max(0, p)), k);
  const domT0 = performance.now() + lead;
  const R = JUMP_T.ratchet, F = JUMP_T.reform, S = JUMP_T.streaks;
  const domLoop = (now) => {
    if (stopped || flashing) return;
    const t = now - domT0;
    if (t >= R && t < R + F) {
      const k = ease3((t - R) / F);
      if (card) {
        card.style.opacity = String(Math.max(0, 1 - k * 1.15));
        card.style.transform = "scale(" + (1 - k * 0.08) + ")";
      }
      for (const b of blobs) {
        b.el.style.transform = "translate(" + (-b.ux * k * 150) + "px," + (-b.uy * k * 150) + "px) scale(" + (1 - k * 0.1) + ")";
        b.el.style.opacity = String(1 - k * 0.3);
      }
    } else if (t >= R + F && t < R + F + S) {
      const k = pw((t - R - F) / S, 1.8);
      const out = k * Math.max(W, H) * 0.75;
      if (card) card.style.opacity = "0";
      for (const b of blobs) {
        b.el.style.transform = "translate(" + (b.ux * (out - 150 * (1 - k))) + "px," + (b.uy * (out - 150 * (1 - k))) + "px) scale(" + (0.9 + k * 0.5) + ")";
        b.el.style.opacity = String(Math.max(0, 0.7 - k * 1.1));
      }
    } else if (t >= R + F + S) {
      if (card) card.style.opacity = "0";
      for (const b of blobs) b.el.style.opacity = "0";
      return;   // nothing left for the main thread to animate
    }
    domRaf = requestAnimationFrame(domLoop);
  };
  domRaf = requestAnimationFrame(domLoop);

  return () => {
    if (flashing) return;
    stopped = true;
    activeEngineSend = null;
    cancelAnimationFrame(raf); cancelAnimationFrame(domRaf);
    if (worker) { try { worker.postMessage({ type: "stop" }); worker.terminate(); } catch (e) {} worker = null; }
    if (engine) engine.msg({ type: "stop" });
    restoreDom();
    root.classList.remove("sage-cv", "sage-beat-flash");
    if (cv.parentNode) cv.parentNode.removeChild(cv);
    jumpOwnsEntrance = false;
    tellPhase("off");   // release the mount gate: this jump is not landing
  };
}

/* True from the press until the arrival has finished. The app has an entrance of
   its own — .lpc.is-entering, the bar dropping in from above and the cards rising
   from below — and it is keyed off the session appearing, which now happens in the
   middle of the jump. Both ran, with different origins and unrelated timings, and
   that is what made the landing read as segmented: nothing came from the centre
   because appBar comes from the top edge and appRise from the bottom. Out-ranking
   it in CSS is a losing game (.lpc.is-entering .hero is three classes), so the
   app's entrance simply does not start when the arrival owns the screen. */
let jumpOwnsEntrance = false;
/* True from the moment landDashboard reveals the app until the hold is released.
   The root's layout effect hides the app whenever the sign-in screen is up, and
   it re-runs when the session object changes identity — which, on real auth,
   happens more than once: SIGNED_IN fires again after the first profile load.
   Without this latch a re-run inside the landing window put jump-under BACK on
   a revealed app: the impact played out hidden, the flash faded over a bare
   ground, and the dashboard popped in plain a second and a half later. A white
   screen, made of two pieces of code both doing their job. */
let jumpLanded = false;

/* Set by the sign-in button and read where the session lands. A page RELOAD
   restores a session without anyone pressing anything, and there is no sign-in
   screen for the jump to start from — no mark to streak, no form to fade. Jorge's
   call: a refresh at the desk goes straight in. So the trigger is the press, not
   the session. */
let signInPressed = false;

function SageArrival({ onComplete }) {
  const done = useRef(onComplete);
  done.current = onComplete;
  /* Only the last beat is left here. Everything before it happened on the sign-in
     screen, which is gone by the time this mounts — that is what the flash is
     covering. The beat reaches the dashboard as a class on the document rather
     than as a prop threaded through six components that have no other reason to
     know about it. */
  /* A LAYOUT effect, not an ordinary one, and that is the whole difference
     between this landing and the stutter it replaced.

     The blocks have to be measured before they are first painted, and the old
     code waited a frame for it — held them at opacity 0, asked for a
     requestAnimationFrame, and measured in that. But the frame it was waiting for
     is the one the browser spends mounting the dashboard, and under that load it
     did not come back for a SECOND: measured in the built app, the page arrived
     at 2134ms and the blocks were still invisible at 3180ms. The screen recording
     is 1.2 seconds of a byte-identical frame — the white had faded, the streaks
     were gone, and nothing at all was moving. That is the stutter.

     A layout effect runs after the DOM is committed and before the browser
     paints, so layout is already there to be read and the animation is on the
     blocks the first time they are drawn. Nothing to hide, nothing to wait for,
     and once the animation has started it belongs to the compositor and runs
     however busy the main thread gets. */
  useLayoutEffect(() => {
    const root = document.documentElement;
    /* The flash beat belongs to the sign-in screen's clock, which has stopped.
       Hand it over rather than letting the two overlap: .sage-assemble carries an
       identical saFlash shorthand, so the running flash is not restarted by the
       swap, it simply changes which rule is holding it. */
    /* Both: sage-assemble is what the dashboard's own rules key off, and
       sage-beat-assemble is what the GROUND decelerates on. Adding only the first
       left the ground with no landing at all — the field and the blobs snapped
       from full streak back to rest the moment the flash class came off, which is
       the opposite of coming out of lightspeed. */
    root.classList.add("sage-assemble", "sage-beat-assemble");
    root.classList.remove("sage-beat-flash");
    let reduce = false;
    try {
      reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    } catch (e) {}
    let undo = () => {};
    if (!reduce) undo = radialAssemble();
    const t = setTimeout(() => done.current(), reduce ? 320 : ARRIVAL.assemble);
    return () => {
      clearTimeout(t);
      undo();
      jumpOwnsEntrance = false;
      root.classList.remove("sage-assemble", "sage-beat-assemble", "sage-beat-flash");
    };
  }, []);
  return null;
}

/* The flash is not a component. It is a static div in index.html, because the
   handover it covers is the moment the signed-out tree is replaced by the
   signed-in one and those two have different root components: React tears the
   whole subtree down between them, so anything mounted inside either one is
   destroyed by the very swap it was drawn to hide. It needs nothing from React
   anyway — the beats drive it through classes on the document element. */

function greetingFor(d = new Date()) {
  const h = d.getHours();
  return h < 12 ? "Good morning" : h < 17 ? "Good afternoon" : "Good evening";
}

const GROUND_PITCH = 44;
const GROUND_TINTS = ["rgba(46,58,50,0.34)", "rgba(120,150,120,0.44)", "rgba(110,150,160,0.42)",
  "rgba(160,158,110,0.40)", "rgba(120,130,170,0.38)"];

/* Where the jump's streaks radiate FROM. The field's own centre by default, and
   the sign-in mark once the sign-in screen has told it where the mark is: the
   whole point of the jump is that it starts at the logo, and a field flying out
   of the middle of the frame while the mark flies out of a point 250px above it
   gives the eye two vanishing points to choose between. One origin, everything
   on the same lines. */
const JUMP_ORIGIN = "sage-jump-origin";
/* Kept outside the component for the same reason the flash is kept outside React:
   the ground is torn down and rebuilt at the handover along with the rest of the
   signed-out tree, and a ground that came back not knowing where the mark was
   would land its streaks on different lines from the ones they left on. */
let lastJumpOrigin = null;
let lastMarkEl = null;
function tellJumpOrigin(el) {
  if (typeof document === "undefined" || !el) return;
  lastMarkEl = el;
  const r = el.getBoundingClientRect();
  lastJumpOrigin = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  /* Published on the document as well as broadcast, because the spark that marks
     the far end of the jump is a static element in index.html and has no other
     way to know where the vanishing point is. */
  const root = document.documentElement;
  root.style.setProperty("--jx", lastJumpOrigin.x + "px");
  root.style.setProperty("--jy", lastJumpOrigin.y + "px");
  document.dispatchEvent(new CustomEvent(JUMP_ORIGIN, { detail: lastJumpOrigin }));
}

/* ---------------- coming out of lightspeed ----------------
   The dashboard does not fade up and it does not scale up in place. It comes out
   of the point the streaks converged on: every block starts at that point, small,
   and flies out along its own line to where it belongs, the near ones landing
   first and the far ones sweeping out after them.

   That vector cannot be written in CSS. Each block's direction and distance
   depend on where it happens to sit relative to a point that moves with the
   sign-in mark, so each one is measured once, on the frame the dashboard mounts,
   and handed its own --rx/--ry/--rd. After that it is an ordinary composited
   transform like everything else here.

   Measured once and never again: this reads layout for every block in one pass
   before writing anything back, so it costs a single forced reflow rather than
   one per element. */
const RADIAL_PARTS = ".topbar, .app-header, .seg-wrap, .hero, .card, .assoc-card, .empty, .sect-strip";

/* ---- the handover does no React work at all ----
   Everything the dashboard needs in order to appear is a class on the document
   and a transform on a handful of blocks — and the dashboard itself has been
   mounted and laid out since the hold. So the handover is done here, imperatively,
   rather than by setting state.

   It was state, and the cost was a single 490ms task measured right after the
   flash: changing anything on the root re-renders the whole app tree, and this
   tree is very large. The mount had already been moved under the streaks by then,
   so what was left was React reconciling a dashboard that was not changing. Now
   the frame that reveals it touches four class names and reads the geometry of six
   blocks, and the state is settled a second and a half later when a re-render
   costs nothing anyone can see. */
function landDashboard() {
  if (typeof document === "undefined") return () => {};
  jumpLanded = true;
  const root = document.documentElement;
  /* One style change: the app comes out of hiding, the sign-in layer goes, and the
     landing rules come on together. */
  root.classList.remove("jump-under", "sage-beat-flash");
  root.classList.add("sage-assemble", "sage-beat-assemble", "signin-gone");
  let reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  } catch (e) {}
  const undo = reduce ? () => {} : radialAssemble();
  return () => {
    undo();
    root.classList.remove("sage-assemble", "sage-beat-assemble", "signin-gone");
  };
}
function radialAssemble() {
  if (typeof document === "undefined") return () => {};
  const o = lastJumpOrigin || { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  const els = Array.from(document.querySelectorAll(RADIAL_PARTS));
  if (!els.length) return () => {};
  /* Read everything first. Interleaving reads and writes here is the classic way
     to turn one reflow into forty. */
  const plan = [];
  const vw = window.innerWidth, vh = window.innerHeight;
  for (const el of els) {
    const r = el.getBoundingClientRect();
    /* Anything not actually laid out is skipped. The section strip is
       display:none above phone width, so its rect is all zeros — it was being
       handed a vector to the top-left corner of the screen and, being the
       furthest "element" on the page, it set the scale that every other block's
       delay was measured against. One invisible element was compressing the
       whole stagger. */
    if (r.width < 1 || r.height < 1) continue;
    /* ---- every element flies, but nothing crosses the screen ----
       Two failed versions taught this shape. Letting every block fly the full
       94% of its vector sent below-the-fold cards raining across the viewport.
       Skipping the off-screen blocks instead meant most of a real board simply
       appeared, and the impact read as not happening at all. So the TRAVEL is
       capped: everything takes the same radial journey out of the centre's
       direction, and a block whose home is far away takes a short hop along
       that line rather than a screen-crossing flight. The radial identity is
       everywhere; the chaos is nowhere. */
    let dx = o.x - (r.left + r.width / 2);
    let dy = o.y - (r.top + r.height / 2);
    const dist = Math.hypot(dx, dy) || 1;
    const cap = Math.min(vw, vh) * 0.55;
    if (dist > cap) { dx = (dx / dist) * cap; dy = (dy / dist) * cap; }
    plan.push({ el, dx, dy, dist: Math.min(dist, cap) });
  }
  if (!plan.length) return () => {};
  const far = Math.max(1, ...plan.map((p) => p.dist));
  for (const p of plan) {
    p.el.style.setProperty("--rx", p.dx.toFixed(1) + "px");
    p.el.style.setProperty("--ry", p.dy.toFixed(1) + "px");
    /* Nearest out first, so the screen opens from the point rather than arriving
       as one sheet. Capped so the last block is not left behind. */
    p.el.style.setProperty("--rd", Math.round((p.dist / far) * 260) + "ms");
    p.el.classList.add("sa-radial");
    /* The shadows follow the landing rather than clicking in after it: none
       while a block is in flight, bloomed in over a breath the moment ITS OWN
       animation ends, each block on its own clock like everything else here. */
    p.onEnd = (e) => {
      if (e.target !== p.el || e.animationName !== "saRadial") return;
      p.el.classList.add("sa-shadowin");
    };
    p.el.addEventListener("animationend", p.onEnd);
  }
  return () => {
    for (const p of plan) {
      p.el.removeEventListener("animationend", p.onEnd);
      p.el.classList.remove("sa-radial", "sa-shadowin");
      p.el.style.removeProperty("--rx");
      p.el.style.removeProperty("--ry");
      p.el.style.removeProperty("--rd");
    }
  };
}

function buildField(w, h, origin) {
  const dots = [];
  const cx = origin ? origin.x : w / 2, cy = origin ? origin.y : h / 2;
  let i = 0;
  for (let y = GROUND_PITCH / 2; y < h; y += GROUND_PITCH) {
    for (let x = GROUND_PITCH / 2; x < w; x += GROUND_PITCH) {
      /* A third of them, not an eighth. The handoff's eighth is the number that
         keeps the cost down, and it left the frame nearly empty at the peak of
         the jump — the mark's 73 streaks against a field that had already faded
         out. A third still costs nothing to animate (they are transforms with no
         promoted layers) and it is the difference between flying through
         something and flying through nothing. */
      /* Bright is now only about SIZE. Every dot streaks — Jorge asked for the
         whole page to go, not a third of it — and the handoff's "only the bright
         minority needs its own streak" was a cost note, written against
         will-change promoting each one into its own layer. Without that these are
         ordinary composited transforms and the whole field is affordable, which
         is the difference between flying through weather and flying through a
         sprinkling. */
      const bright = i % 3 === 0;
      const dx = x - cx, dy = y - cy;
      dots.push({
        x, y, bright,
        size: bright ? 4.4 : 2.6,
        tint: GROUND_TINTS[i % GROUND_TINTS.length],
        /* Its own angle out of the centre, so in the jump every streak leaves
           along the line it is already on. */
        angle: (Math.atan2(dy, dx) * 180) / Math.PI,
        dist: Math.hypot(dx, dy),
        dur: 2600 + ((i * 971) % 5000),
        delay: (i * 337) % 4200,
      });
      i++;
    }
  }
  return dots;
}

/* The blobs, and only the blobs. These are the layer the handoff says continues
   through the transition rather than being swapped, so they are mounted once at
   the root and outlive both screens. The dot field is the sign-in screen's; see
   SageField. */
function SageGround({ beat = "idle" }) {
  return (
    <div className={"sage-ground beat-" + beat} aria-hidden="true">
      <div className="sg-blobs">
        <i className="sg-blob b1" /><i className="sg-blob b2" />
        <i className="sg-blob b3" /><i className="sg-blob b4" />
      </div>
    </div>
  );
}

/* ---------------- The dot field ----------------
   The sign-in screen's, and nobody else's. The handoff builds it under "The
   sign-in screen" and its prototype keys the whole thing off whether that screen
   is visible — `signinVisible ? ... : "off"` — while saying of the BLOBS, and only
   the blobs, that they "live behind both the sign-in screen and the dashboard,
   the same layer continuing through the transition rather than being swapped".
   Two different lifetimes, and this file had given both of them the longer one.

   That cost more than tidiness. 660 dots left on the dashboard meant 660 dots
   decelerating out of full streak while React mounted the dashboard, and the
   landing was measurably the worse for it: stalls of 467-983ms with the field
   there against none at all without it. The choppy landing and the drift Jorge
   could see on the dashboard are the same mistake seen from two sides.

   Rendered by the sign-in screen, so it is held for the whole jump and goes with
   that screen at the handover, underneath the white. */
/* ---------------- the streaks, on a canvas ----------------
   The field is 660 dots, and for the length of the stretch each one is a streak
   the size of the screen. As DOM elements that cannot be drawn at frame rate and
   it is not close: measured in the built app, tapered with a gradient it managed
   23-38 frames with stalls up to a second, as pills 44-47, and only as flat
   rectangles did it run clean at 64. The taper is not the problem, the element
   count is — 660 large composited layers is simply too many to paint.

   So for the one beat that needs them, the streaks stop being elements. One
   canvas, one texture upload a frame, and each streak drawn as a spike: full dot
   width at the near end, tapering to a point at the far one, which is what a
   streak looks like and what a scaled dot never did. Paths are batched by colour,
   so a frame is five fills rather than six hundred and sixty.

   Only for the stretch. At rest the dots are ordinary elements with a CSS
   twinkle, which costs nothing and keeps the sign-in screen still. */
function SageStreaks({ dots, origin, w, h }) {
  const ref = useRef(null);
  useEffect(() => {
    const cv = ref.current;
    if (!cv) return undefined;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    cv.width = Math.round(w * dpr);
    cv.height = Math.round(h * dpr);
    const ctx = cv.getContext("2d");
    ctx.scale(dpr, dpr);
    /* Grouped once, so a frame sets fillStyle five times rather than 660. */
    /* The canvas takes over mid-move, so it has to start where the gather left
       the dots: pulled in toward the origin by the field layer's own scale.
       Starting from their resting places would snap the whole field outward on
       the frame the streaks begin. */
    const ox = origin ? origin.x : w / 2, oy = origin ? origin.y : h / 2;
    const G = 0.86;
    const byTint = new Map();
    for (const d of dots) {
      const a = (d.angle * Math.PI) / 180;
      const arr = byTint.get(d.tint) || [];
      arr.push({
        x: ox + (d.x - ox) * G, y: oy + (d.y - oy) * G,
        ux: Math.cos(a), uy: Math.sin(a), r: (d.size / 2) * G, dist: d.dist,
      });
      byTint.set(d.tint, arr);
    }
    const groups = [...byTint.entries()];
    const t0 = performance.now();
    let raf = 0;
    /* ---- and it keeps accelerating to the end ----
       The streaks used to stop. The beat ended, the canvas held its last frame,
       and a screen full of static lines sat there for the quarter second the
       flash and the mount took — motion halted and then the page landed, which is
       the stutter at the join. Nothing about the shape was wrong; it simply never
       left.

       So the curve never flattens (a power curve, not a smoothstep, which eases
       OUT at the end), the travel is far enough to carry every near end off the
       frame rather than only the far ends, and it runs past the beat into the
       flash, fading as it goes. Whatever is still on screen when the sign-in
       screen goes is under the white by then. */
    const RUN = ARRIVAL.stretch + 300;
    const draw = () => {
      const p = Math.min(1, (performance.now() - t0) / RUN);
      const e = Math.pow(p, 2.2);
      ctx.clearRect(0, 0, w, h);
      ctx.globalAlpha = p < 0.72 ? 1 : Math.max(0, 1 - (p - 0.72) / 0.28);
      for (const [tint, arr] of groups) {
        ctx.fillStyle = tint;
        ctx.beginPath();
        for (const d of arr) {
          /* The near end leaves too, so the field opens out of the origin
             instead of stretching from a standstill. */
          const lead = e * (90 + d.dist * 1.75);
          const len = e * (150 + d.dist * 2.4);
          const nx = d.x + d.ux * lead, ny = d.y + d.uy * lead;
          const fx = nx + d.ux * len, fy = ny + d.uy * len;
          const px = -d.uy * d.r, py = d.ux * d.r;
          ctx.moveTo(nx + px, ny + py);
          ctx.lineTo(nx - px, ny - py);
          ctx.lineTo(fx, fy);
        }
        ctx.fill();
      }
      if (p < 1) raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, [dots, origin, w, h]);
  return <canvas ref={ref} className="sg-streaks" style={{ width: w, height: h }} aria-hidden="true" />;
}

/* Whether the jump is at the beat that needs the canvas. Read off the document
   because that is where the beats live; see runJump. */
function useStretching() {
  const [on, setOn] = useState(false);
  useEffect(() => {
    const root = document.documentElement;
    const read = () => setOn(root.classList.contains("sage-beat-stretch")
      || root.classList.contains("sage-beat-flash"));
    read();
    const mo = new MutationObserver(read);
    mo.observe(root, { attributes: true, attributeFilter: ["class"] });
    return () => mo.disconnect();
  }, []);
  return on;
}

function SageField() {
  const [size, setSize] = useState(() => ({
    w: typeof window === "undefined" ? 1440 : window.innerWidth,
    h: typeof window === "undefined" ? 900 : window.innerHeight,
  }));
  const [origin, setOrigin] = useState(lastJumpOrigin);
  useEffect(() => {
    let t = null;
    const onResize = () => {
      clearTimeout(t);
      t = setTimeout(() => setSize({ w: window.innerWidth, h: window.innerHeight }), 220);
    };
    const onOrigin = (e) => setOrigin(e.detail);
    window.addEventListener("resize", onResize);
    document.addEventListener(JUMP_ORIGIN, onOrigin);
    return () => {
      window.removeEventListener("resize", onResize);
      document.removeEventListener(JUMP_ORIGIN, onOrigin);
      clearTimeout(t);
    };
  }, []);
  /* Rebuilt when the origin arrives, and only then: once per sign-in, not once
     per render. Rebuilding it per render was the handoff's second performance
     note and it still holds. */
  const dots = useMemo(() => buildField(size.w, size.h, origin), [size.w, size.h, origin]);
  const stretching = useStretching();
  if (stretching) {
    return <SageStreaks dots={dots} origin={origin} w={size.w} h={size.h} />;
  }
  return (
    <div className="sg-field" aria-hidden="true">
      {dots.map((d, i) => (
        <i key={i} className={"sg-dot" + (d.bright ? " bright" : "")}
          style={{
            left: d.x, top: d.y, width: d.size, height: d.size, color: d.tint,
            animationDuration: d.dur + "ms", animationDelay: d.delay + "ms",
            /* Read by the jump; set here so nothing has to be measured later.
               --d carries how far this dot sits from the origin, so the ones near
               the logo travel less than the ones out at the corners and the whole
               field opens rather than sliding as a sheet. */
            "--a": d.angle + "deg",
            "--d": d.dist.toFixed(1),
          }} />
      ))}
    </div>
  );
}

/* ---------------- Waiting on approval ---------------- */
function PendingScreen({ profile, onSignOut, config = null, onClaimed = null }) {
  const first = (profile.name || "").split(" ")[0];
  const [claim, setClaim] = useState({ store: "", person: null, name: "" });
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const storeName = (id) => (((config && config.stores) || []).find((st) => st.id === id) || {}).name || id;
  const claimed = profile.claim && profile.claim.store ? profile.claim : null;
  const sendClaim = async () => {
    if (!claim.store) { setErr("Pick your store."); return; }
    setBusy(true); setErr("");
    const r = await authClaimName(claim);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    if (onClaimed) onClaimed();
  };
  /* What they asked to be at sign-up, if the account carries it. Two people wait
     on this screen for opposite reasons and the old copy only described one of
     them: a salesperson was told to wait for store access they will never be
     given and do not need. */
  const wants = profile.wants || profile.requested_role || null;
  const isAssociate = wants === "associate";
  return (
    <div className="login">
      <div className="login-card">
        <div className="login-logo"><SageMark word size={56} className="logo-anim" /></div>
        <h1 className="login-title">{isAssociate ? "One thing left" : "Almost there"}</h1>
        {/* The first screen after signing up, so it speaks the same language as
            the one they just left rather than the app's general chrome. */}
        <p className="lf-note">
          {isAssociate ? (claimed ? (<>
            You are in{first ? ", " + first : ""}. Your manager at <b>{storeName(claimed.store)}</b> has
            a note that this account is <b>{claimed.name || "you"}</b>; one tap from them and the line,
            your standards and your day are on this phone. This screen will let you through on its own.
          </>) : (<>
            Your account exists{first ? ", " + first : ""}. Say which store you work at and which
            name on the roster is yours. Your manager joins the two with one tap, and then the line,
            your standards and your day are on your phone.
          </>)) : (<>
            Your account exists{first ? ", " + first : ""}, but no store has been assigned to it yet.
            Your group admin needs to approve you and grant access. Once they do, sign in again and you are in.
          </>)}
        </p>
        {/* The one thing this screen can hand somebody that is useful to the
            person on the other end of the conversation. */}
        {isAssociate && !claimed && (
          <div className="lf-mode">
            <ClaimPicker config={config} value={claim} onChange={(c) => { setClaim(c); setErr(""); }} />
            {err && <div className="login-err">{err}</div>}
            <button className="lf-go lf-solo" onClick={sendClaim} disabled={busy}><span>{busy ? "Sending…" : "That's me"}</span></button>
          </div>
        )}
        <p className="lf-note lf-acctid">Account <b>{String(profile.id || "").slice(0, 8)}</b> · {profile.email || ""}</p>
        <button className={isAssociate && !claimed ? "lf-alt" : "lf-go lf-solo"} onClick={onSignOut}>{isAssociate && !claimed ? "Sign out" : <span>Sign out</span>}</button>
      </div>
    </div>
  );
}

/* ---------------- Import badge ---------------- */
function ImportBadge({ storeData, activity }) {
  const M = storeData.months[ym()];
  const t = M?.imports?.[today()] || {};
  if (activity) {
    return <span className={"badge " + (t.activity ? "badge-ok" : "badge-warn")}>{t.activity ? <PixIcon glyph="check" size={11} /> : "0/1"}</span>;
  }
  // Delivery Summaries arrive by email, so the manager only uploads two.
  const done = ["appointment", "video"].filter((k) => t[k]).length;
  return <span className={"badge " + (done === 2 ? "badge-ok" : "badge-warn")}>{done}/2</span>;
}

